/** Arrastrar desde la barra de gráficos: incrustar PFD, vista 3D o mando (mismo motor que modo Visual vuelo). */
const FLIGHT_VIZ_DRAG_PFD = "varmon-flight-viz:pfd";
const FLIGHT_VIZ_DRAG_3D = "varmon-flight-viz:3d";
const FLIGHT_VIZ_DRAG_JOYSTICK = "varmon-flight-viz:stick";
const FLIGHT_VIZ_DRAG_LIVE_REPLAY = "varmon-flight-viz:live-replay";
const FLIGHT_VIZ_DRAG_HIST = "varmon-live-hist:delta";
const FLIGHT_VIZ_DRAG_LIVE_FFT = "varmon-live-hist:fft";
const FLIGHT_VIZ_DRAG_SCAN_WIDGET = "varmon-mavlink-scan:widget";
const FLIGHT_VIZ_DRAG_ENTROPY_SCAN = "varmon-entropy-scan:widget";
const MAX_ENTROPY_SCAN_VARS = 32;

function parseFlightVizDragToken(name) {
    if (name === FLIGHT_VIZ_DRAG_PFD) return "pfd";
    if (name === FLIGHT_VIZ_DRAG_3D) return "scene";
    if (name === FLIGHT_VIZ_DRAG_JOYSTICK) return "stick";
    if (name === FLIGHT_VIZ_DRAG_LIVE_REPLAY) return "live_replay";
    if (name === FLIGHT_VIZ_DRAG_HIST) return "hist";
    if (name === FLIGHT_VIZ_DRAG_LIVE_FFT) return "live_fft";
    if (name === FLIGHT_VIZ_DRAG_SCAN_WIDGET) return "scan_widget";
    if (name === FLIGHT_VIZ_DRAG_ENTROPY_SCAN) return "entropy_scan_widget";
    return null;
}

/** Incrusta PFD o vista 3D en un slot de gráfico (misma lógica que soltar el token desde la barra). */
function applyFlightVizToGraphSlot(gid, paneId, fvKind) {
    if ((fvKind === "pfd" || fvKind === "scene" || fvKind === "stick") && !hasPlugin("flight_viz")) {
        setPlotSlotToChartMode(gid, paneId, "timeseries");
        return;
    }
    const st = getPlotPaneState(paneId);
    graphFlightVizByGid[gid] = fvKind;
    // PFD/3D/mando no comparten series con gráficos; replay live e histogramas Δt / FFT conservan asignación.
    if (fvKind !== "live_replay" && fvKind !== "hist" && fvKind !== "live_fft" && fvKind !== "scan_widget" && fvKind !== "entropy_scan_widget") {
        removeGidFromVarGraphMap(st.varGraphAssignment, gid);
        for (const [eName, g] of Object.entries(st.arrayElemAssignment)) {
            if (g === gid) delete st.arrayElemAssignment[eName];
        }
    }
    if (st.graphViewModeByGid && typeof st.graphViewModeByGid === "object") delete st.graphViewModeByGid[gid];
    syncPlotGlobalsMirror(st);
    rebuildPlotArea();
    saveConfig();
    nextAllowedRenderAt = 0;
    syncStaticPlotEmptyAfterPlotStateChange();
    schedulePlotRender();
}

/** Serie temporal o barras: quita flight-viz del slot si lo hubiera y fija `graphViewModeByGid`. */
function setPlotSlotToChartMode(gid, paneId, chartMode) {
    const st = getPlotPaneState(paneId);
    if (graphFlightVizByGid[gid]) delete graphFlightVizByGid[gid];
    delete graphDeltaAnalysisStepByGid[gid];
    delete graphDeltaAnalysisMaxPlotMsByGid[gid];
    delete graphScanWidgetViewByGid[gid];
    delete graphScanWidgetTimePresetByGid[gid];
    delete graphScanWidgetPrefsByGid[gid];
    delete graphScanWidgetPinnedByGid[gid];
    delete graphScanWidgetPinnedSnapshotByGid[gid];
    delete graphEntropyScanVarsByGid[gid];
    delete graphEntropyScanWindowSecByGid[gid];
    delete graphEntropyScanBinsByGid[gid];
    if (!st.graphViewModeByGid || typeof st.graphViewModeByGid !== "object") st.graphViewModeByGid = {};
    st.graphViewModeByGid[gid] = chartMode === "columns" ? "columns" : "timeseries";
    syncPlotGlobalsMirror(st);
    rebuildPlotArea();
    saveConfig();
    nextAllowedRenderAt = 0;
    syncStaticPlotEmptyAfterPlotStateChange();
    schedulePlotRender();
}

/** Valor del desplegable: timeseries | columns | pfd | visual (3D = scene en motor). */
function getPlotSlotDisplayMode(gid, st) {
    const fv = graphFlightVizByGid[gid];
    if ((fv === "pfd" || fv === "scene" || fv === "stick") && !hasPlugin("flight_viz")) {
        return getGraphViewMode(gid, st) === "columns" ? "columns" : "timeseries";
    }
    if (fv === "pfd") return "pfd";
    if (fv === "scene") return "visual";
    if (fv === "stick") return "joystick";
    if (fv === "live_replay") return "live_replay";
    if ((fv === "hist" || fv === "live_fft") && !hasMavlinkRuntimeProvider()) {
        return getGraphViewMode(gid, st) === "columns" ? "columns" : "timeseries";
    }
    if (fv === "scan_widget" && !hasMavlinkScanProvider()) {
        return getGraphViewMode(gid, st) === "columns" ? "columns" : "timeseries";
    }
    if (fv === "entropy_scan_widget") return "entropy_scan_widget";
    if (fv === "hist") return "hist";
    if (fv === "live_fft") return "live_fft";
    if (fv === "scan_widget") return "scan_widget";
    return getGraphViewMode(gid, st) === "columns" ? "columns" : "timeseries";
}

function applyPlotSlotDisplayMode(gid, paneId, mode) {
    if ((mode === "pfd" || mode === "visual" || mode === "joystick") && !hasPlugin("flight_viz")) {
        setPlotSlotToChartMode(gid, paneId, "timeseries");
        return;
    }
    if (mode === "pfd") {
        applyFlightVizToGraphSlot(gid, paneId, "pfd");
        return;
    }
    if (mode === "visual") {
        applyFlightVizToGraphSlot(gid, paneId, "scene");
        return;
    }
    if (mode === "joystick") {
        applyFlightVizToGraphSlot(gid, paneId, "stick");
        return;
    }
    if (mode === "live_replay") {
        applyFlightVizToGraphSlot(gid, paneId, "live_replay");
        return;
    }
    if (mode === "hist") {
        if (!hasMavlinkRuntimeProvider()) {
            setPlotSlotToChartMode(gid, paneId, "timeseries");
            return;
        }
        applyFlightVizToGraphSlot(gid, paneId, "hist");
        return;
    }
    if (mode === "live_fft") {
        if (!hasMavlinkRuntimeProvider()) {
            setPlotSlotToChartMode(gid, paneId, "timeseries");
            return;
        }
        applyFlightVizToGraphSlot(gid, paneId, "live_fft");
        return;
    }
    if (mode === "scan_widget") {
        if (!hasMavlinkScanProvider()) {
            setPlotSlotToChartMode(gid, paneId, "timeseries");
            return;
        }
        applyFlightVizToGraphSlot(gid, paneId, "scan_widget");
        return;
    }
    if (mode === "entropy_scan_widget") {
        applyFlightVizToGraphSlot(gid, paneId, "entropy_scan_widget");
        return;
    }
    if (mode === "timeseries" || mode === "columns") {
        setPlotSlotToChartMode(gid, paneId, mode);
    }
}

function clearFlightVizFromGraphSlot(gid, paneId) {
    if (!graphFlightVizByGid[gid]) return;
    setPlotSlotToChartMode(gid, paneId, "timeseries");
}

/** API del módulo externo `replay_alias` (alias en replay / offline). */
function replayAliasApi() {
    const results = fireHook("replay_alias_api");
    return results && results[0] ? results[0] : null;
}

function _replayAliasMod() {
    return replayAliasApi();
}

function normalizeReplayAliasMap(raw) {
    const m = _replayAliasMod();
    if (m && typeof m.normalizeReplayAliasMap === "function") return m.normalizeReplayAliasMap(raw);
    return normalizeReplayAliasMapShim(raw);
}
function detectReplayAliasCollisions(map) {
    const m = _replayAliasMod();
    if (m && typeof m.detectReplayAliasCollisions === "function") return m.detectReplayAliasCollisions(map);
    return { duplicateTargets: [] };
}
function suggestReplayAliasMatches(tsvName, canonicalNames, opts) {
    const m = _replayAliasMod();
    if (m && typeof m.suggestReplayAliasMatches === "function") return m.suggestReplayAliasMatches(tsvName, canonicalNames, opts);
    return [];
}
function replayAliasStorageKey(fileName, sourceName) {
    const m = _replayAliasMod();
    if (m && typeof m.replayAliasStorageKey === "function") return m.replayAliasStorageKey(fileName, sourceName);
    return String(fileName || sourceName || "").trim() || "__local__";
}
function filterReplayAliasSources(sources, query, filterKind, map, canonicalSet) {
    const m = _replayAliasMod();
    if (m && typeof m.filterReplayAliasSources === "function") {
        return m.filterReplayAliasSources(sources, query, filterKind, map, canonicalSet);
    }
    return Array.isArray(sources) ? sources.slice() : [];
}
function effectiveReplayAliasMap(sources, draft) {
    const m = _replayAliasMod();
    if (m && typeof m.effectiveReplayAliasMap === "function") return m.effectiveReplayAliasMap(sources, draft);
    const out = {};
    const d = draft && typeof draft === "object" ? draft : {};
    for (const src of sources || []) {
        const v = d[src];
        out[src] = v != null && String(v).trim() !== "" ? String(v).trim() : src;
    }
    return out;
}
function replayAliasRowStatus(source, map, canonicalSet) {
    const m = _replayAliasMod();
    if (m && typeof m.replayAliasRowStatus === "function") return m.replayAliasRowStatus(source, map, canonicalSet);
    const raw = map && map[source] != null ? String(map[source]).trim() : "";
    const target = raw !== "" ? raw : source;
    const identity = target === source;
    const inCanon = canonicalSet && canonicalSet.has(target);
    return { source, target, hasMap: !identity, identity, inCanon, kind: identity ? "identity" : (inCanon ? "mapped" : "unknown_target") };
}
function replayAliasMetaMismatchMessage(meta, current) {
    const m = _replayAliasMod();
    if (m && typeof m.replayAliasMetaMismatchMessage === "function") return m.replayAliasMetaMismatchMessage(meta, current);
    return [];
}
function sanitizeReplayAliasProfileName(name) {
    const m = _replayAliasMod();
    if (m && typeof m.sanitizeReplayAliasProfileName === "function") return m.sanitizeReplayAliasProfileName(name);
    return String(name ?? "").trim().slice(0, 64).replace(/[\x00-\x1f]/g, "") || "";
}

