let liveReplayEmbedSessionSeries = Object.create(null);

function clearLiveReplayEmbedSessionSeries() {
    liveReplayEmbedSessionSeries = Object.create(null);
}

function isVarInLiveReplayEmbed(name) {
    if (!name || !liveReplayEmbedDataset || !Array.isArray(liveReplayEmbedDataset.names)) return false;
    const idx = name.indexOf("[");
    const base = idx >= 0 && name.endsWith("]") ? name.substring(0, idx) : name;
    return liveReplayEmbedDataset.names.includes(base);
}

function collectVarsAssignedToLiveReplayGraphs() {
    const out = new Set();
    for (const paneId of getLivePlotLeafIds()) {
        const st = getPlotPaneState(paneId);
        for (const gid of st.graphList || []) {
            if (graphFlightVizByGid[gid] !== "live_replay") continue;
            for (const n of getVarsForGraphInPane(gid, paneId)) {
                out.add(n);
            }
        }
    }
    return out;
}

function appendLiveReplayEmbedSessionSampleTick(embedTs) {
    if (!isLiveMode() || !liveReplayEmbedDataset || !liveReplayEmbedPlayback.isPlaying) return;
    const minTs = liveReplayEmbedDataset.minTs;
    const relT = embedTs - minTs;
    if (!Number.isFinite(relT) || relT < 0) return;
    for (const name of collectVarsAssignedToLiveReplayGraphs()) {
        const vd = varsByName[name];
        if (!vd || Array.isArray(vd.value)) continue;
        const v = Number(vd.value);
        if (!Number.isFinite(v)) continue;
        if (!liveReplayEmbedSessionSeries[name]) {
            liveReplayEmbedSessionSeries[name] = { relT: [], y: [] };
        }
        const s = liveReplayEmbedSessionSeries[name];
        if (s.relT.length > 0 && Math.abs(s.relT[s.relT.length - 1] - relT) < 1e-9) {
            s.y[s.y.length - 1] = v;
        } else {
            s.relT.push(relT);
            s.y.push(v);
        }
    }
}

function getLiveReplaySessionHistTrimmed(name, relEnd) {
    const s = liveReplayEmbedSessionSeries[name];
    if (!s || !s.relT.length || !Number.isFinite(relEnd)) return null;
    const ts = [];
    const vs = [];
    for (let i = 0; i < s.relT.length; i++) {
        if (s.relT[i] <= relEnd + 1e-9) {
            ts.push(s.relT[i]);
            vs.push(s.y[i]);
        }
    }
    if (ts.length === 0) return null;
    return { timestamps: ts, values: vs };
}

function mapRefSeriesToRelativeTime(series, minTs) {
    if (!series || !Array.isArray(series.timestamps) || !Array.isArray(series.values)) return null;
    const ts = series.timestamps.map((t) => t - minTs);
    return { timestamps: ts, values: series.values.slice() };
}

