function stableSerializeArincDef(def) {
    if (!def || typeof def !== "object") return "";
    try {
        const n = normalizeLabelEntry({ ...def });
        return JSON.stringify(n || def);
    } catch {
        return JSON.stringify(def);
    }
}

function snapshotArincRegistryBaseline() {
    arincRegistryBaseline = {};
    for (const k of Object.keys(arincLabelRegistry)) {
        arincRegistryBaseline[k] = stableSerializeArincDef(arincLabelRegistry[k]);
    }
}

function isArincEntryModifiedByBaseline(entryKey) {
    if (!arincDbStatus || !arincDbStatus.loaded || !arincRegistryBaseline) return false;
    const def = arincLabelRegistry[entryKey];
    if (!def) return false;
    const sig = stableSerializeArincDef(def);
    const prev = arincRegistryBaseline[entryKey];
    if (prev === undefined) return true;
    return sig !== prev;
}

