function applyM1553BulkNameEdits() {
    const pfx = document.getElementById("m1553BulkNamePrefix");
    const spfx = document.getElementById("m1553BulkNameStripPrefix");
    const sfx = document.getElementById("m1553BulkNameSuffix");
    const find = document.getElementById("m1553BulkNameFind");
    const rep = document.getElementById("m1553BulkNameReplace");
    const prefix = pfx ? String(pfx.value || "") : "";
    const stripP = spfx ? String(spfx.value || "") : "";
    const suffix = sfx ? String(sfx.value || "") : "";
    const findStr = find ? String(find.value || "") : "";
    const repStr = rep ? String(rep.value || "") : "";
    const keys = getM1553BulkTargetKeys();
    const tr = I18N[currentLang] || I18N.es;
    if (!keys.length) {
        alert(tr.arincBulkNeedSelection || "Marque al menos una fila (casilla) o use «Seleccionar filtradas».");
        return;
    }
    pushM1553UndoSnapshot();
    for (const k of keys) {
        const def = m1553LabelRegistry[k];
        if (!def) continue;
        let nm = String(def.name || "");
        if (stripP && nm.startsWith(stripP)) nm = nm.slice(stripP.length);
        if (findStr) nm = nm.split(findStr).join(repStr);
        nm = prefix + nm + suffix;
        if (nm.trim()) def.name = nm.trim();
    }
    setM1553DbDirty(true);
    saveConfig();
    renderM1553RegistryTable();
    rebuildMonitorList();
    updateMonitorValues();
}

function applyM1553BulkRtWkDelta() {
    const tr = I18N[currentLang] || I18N.es;
    const keys = getM1553BulkTargetKeys();
    if (!keys.length) {
        alert(tr.arincBulkNeedSelection || "Marque al menos una fila (casilla) o use «Seleccionar filtradas».");
        return;
    }
    const drIn = document.getElementById("m1553BulkRtDelta");
    const dwIn = document.getElementById("m1553BulkWkDelta");
    const dr = (drIn && drIn.value !== "") ? Number(drIn.value) : 0;
    const dw = (dwIn && dwIn.value !== "") ? Number(dwIn.value) : 0;
    if (!Number.isFinite(dr) || !Number.isFinite(dw)) {
        alert(tr.m1553BulkRtWkInvalid || "Valores numéricos inválidos para Δ RT / Δ W.");
        return;
    }
    if (dr === 0 && dw === 0) {
        alert(tr.m1553BulkRtWkNoOp || "Indique Δ RT o Δ W distinto de 0.");
        return;
    }
    const clamp = (n) => Math.max(0, Math.min(31, Math.trunc(n)));
    const nextNk = new Map();
    for (const k of keys) {
        const def = m1553LabelRegistry[k];
        if (!def) continue;
        const newRt = clamp((def.rt ?? 0) + dr);
        const newWk = clamp((def.wordKind ?? 0) + dw);
        const nk = m1553EntryKey(newRt, newWk, def.suffix);
        nextNk.set(k, nk);
    }
    const nkCount = new Map();
    for (const nk of nextNk.values()) nkCount.set(nk, (nkCount.get(nk) || 0) + 1);
    for (const [k, nk] of nextNk) {
        if (nkCount.get(nk) > 1) {
            alert(tr.m1553BulkRtWkMergeConflict || "Varias filas seleccionadas convergen en la misma clave.");
            return;
        }
        if (nk !== k && m1553LabelRegistry[nk] && !keys.includes(nk)) {
            alert((tr.m1553BulkRtWkTargetOccupied || "La clave %s ya existe.").replace("%s", nk));
            return;
        }
    }
    pushM1553UndoSnapshot();
    const next = { ...m1553LabelRegistry };
    for (const k of keys) delete next[k];
    for (const k of keys) {
        const def = m1553LabelRegistry[k];
        if (!def) continue;
        const nk = nextNk.get(k);
        if (!nk) continue;
        const newRt = clamp((def.rt ?? 0) + dr);
        const newWk = clamp((def.wordKind ?? 0) + dw);
        const norm = normalizeM1553Row({ ...def, rt: newRt, wordKind: newWk });
        if (!norm) continue;
        next[nk] = norm;
    }
    m1553LabelRegistry = next;
    for (const k of keys) {
        m1553BulkSelectedKeys.delete(k);
        m1553ExpandedPackedKeys.delete(k);
    }
    for (const nk of nextNk.values()) m1553BulkSelectedKeys.add(nk);
    setM1553DbDirty(true);
    saveConfig();
    renderM1553RegistryTable();
    rebuildMonitorList();
    updateMonitorValues();
}

