async function sha256HexFromString(text) {
    try {
        const data = new TextEncoder().encode(String(text ?? ""));
        const buf = await crypto.subtle.digest("SHA-256", data);
        return Array.from(new Uint8Array(buf))
            .map((b) => b.toString(16).padStart(2, "0"))
            .join("");
    } catch {
        return "";
    }
}

function refreshArincImportValidationPanel() {
    const block = document.getElementById("arincImportValidationBlock");
    if (!block) return;
    if (!arincImportPending || arincImportPending.type !== "tabular") {
        block.style.display = "none";
        block.innerHTML = "";
        return;
    }
    const { headers, rows, mapping, rowKinds } = arincImportPending;
    const gInput = document.getElementById("arincImportTargetGroupInput");
    const tg = gInput ? (String(gInput.value || "").trim() || "General") : "General";
    const results = fireHook("arinc_validate_tabular_import", {
        headers,
        rows,
        mapping,
        rowKinds,
        targetGroup: tg,
    });
    const report = results.find((x) => x && typeof x === "object" && Array.isArray(x.issues));
    if (!report) {
        block.style.display = "none";
        block.innerHTML = "";
        return;
    }
    const tr = I18N[currentLang] || I18N.es;
    const errs = report.issues.filter((i) => i.severity === "error");
    const warns = report.issues.filter((i) => i.severity === "warning");
    const title = tr.arincImportValidationTitle || "Validación previa (módulo ARINC)";
    const errL = tr.arincImportValidationErrors || "Errores";
    const warnL = tr.arincImportValidationWarnings || "Advertencias";
    let html = `<div class="arinc-import-validation-inner"><strong>${escapeHtml(title)}</strong>`;
    html += `<div class="arinc-import-validation-counts">${escapeHtml(tr.arincImportValidationSummary || "")
        .replace("%1$d", String(errs.length))
        .replace("%2$d", String(warns.length))
        .replace("%3$d", String(report.labelRowCount || 0))}</div>`;
    if (errs.length) {
        html += `<div class="arinc-import-validation-err"><span>${escapeHtml(errL)}</span><ul>` +
            errs.map((i) => `<li>${escapeHtml(i.message || i.code || "")}</li>`).join("") + "</ul></div>";
    }
    if (warns.length) {
        html += `<div class="arinc-import-validation-warn"><span>${escapeHtml(warnL)}</span><ul>` +
            warns.map((i) => `<li>${escapeHtml(i.message || i.code || "")}</li>`).join("") + "</ul></div>";
    }
    html += "</div>";
    block.style.display = "block";
    block.innerHTML = html;
}

function refreshArincProConflictDiff() {
    const el = document.getElementById("arincImportProDiff");
    if (!el) return;
    if (!arincImportPending) {
        el.style.display = "none";
        el.innerHTML = "";
        return;
    }
    let incoming = null;
    try {
        incoming = collectArincImportIncomingBuilt();
    } catch {
        el.style.display = "none";
        return;
    }
    if (!incoming) {
        el.style.display = "none";
        return;
    }
    const results = fireHook("arinc_list_import_conflicts", incoming, arincLabelRegistry);
    const list = results.find((x) => Array.isArray(x));
    if (!list || !list.length) {
        el.style.display = "none";
        el.innerHTML = "";
        return;
    }
    const tr = I18N[currentLang] || I18N.es;
    const hdr = tr.arincImportDiffTitle || "Cambios respecto al registro actual (módulo ARINC)";
    let html = `<div class="arinc-import-pro-diff-inner"><strong>${escapeHtml(hdr)}</strong><ul>`;
    for (const c of list.slice(0, 40)) {
        const flds = Array.isArray(c.fieldsChanged) && c.fieldsChanged.length
            ? ` [${c.fieldsChanged.join(", ")}]`
            : "";
        html += `<li><code>${escapeHtml(String(c.oct || ""))}</code> (${escapeHtml(String(c.group || ""))})${escapeHtml(flds)}</li>`;
    }
    html += list.length > 40 ? `<li>…</li>` : "";
    html += "</ul></div>";
    el.style.display = "block";
    el.innerHTML = html;
}

function getArincLabelDefForOct(labelOct, preferredGroup = "") {
    const grp = String(preferredGroup || "").trim();
    if (grp) {
        const key = arincFindEntryKeyByGroupOct(arincLabelRegistry, grp, labelOct);
        if (key && arincLabelRegistry[key]) {
            const scoped = { [labelOct]: arincLabelRegistry[key] };
            const scopedDef = registryGetArincLabelDef(scoped, labelOct);
            if (scopedDef && (!scopedDef.group || scopedDef.group === "General")) scopedDef.group = grp;
            return scopedDef;
        }
    }
    return registryGetArincLabelDef(arincLabelRegistry, labelOct);
}
