function renderNotesList() {
    if (!notesListEl) return;
    notesListEl.innerHTML = "";
    if (!Array.isArray(notesByTs) || notesByTs.length === 0) return;
    const rows = notesByTs.slice().sort((a, b) => a.ts - b.ts).slice(-120);
    for (let i = 0; i < rows.length; i++) {
        const n = rows[i];
        const row = document.createElement("div");
        row.className = "note-item";
        const txt = document.createElement("span");
        const relTs = (offlineDataset && Number.isFinite(offlineDataset.minTs))
            ? Math.max(0, n.ts - offlineDataset.minTs) : n.ts;
        txt.textContent = `${relTs.toFixed(3)}s | ${n.text}`;
        const go = document.createElement("button");
        go.className = "btn-small";
        go.textContent = "Ir";
        go.addEventListener("click", () => {
            applyOfflineTime(n.ts);
            schedulePlotRender();
        });
        const del = document.createElement("button");
        del.className = "btn-small";
        del.textContent = "✕";
        del.title = "Borrar nota";
        del.addEventListener("click", () => {
            const idx = notesByTs.indexOf(n);
            if (idx >= 0) {
                notesByTs.splice(idx, 1);
                renderNotesList();
                saveConfig();
            }
        });
        row.appendChild(txt);
        row.appendChild(go);
        row.appendChild(del);
        notesListEl.appendChild(row);
    }
}

function renderSegmentsUi() {
    if (!segmentSelectEl) return;
    if (!hasPlugin("segments")) { segmentSelectEl.closest(".segment-controls")?.style.setProperty("display", "none"); return; }
    const fmtDraft = (v) => {
        if (!Number.isFinite(v)) return "--";
        if (offlineDataset && Number.isFinite(offlineDataset.minTs)) return `${(v - offlineDataset.minTs).toFixed(3)}s`;
        return `${v.toFixed(3)}s`;
    };
    if (segStartLabel) segStartLabel.textContent = `S: ${fmtDraft(segmentDraft.start)}`;
    if (segEndLabel) segEndLabel.textContent = `E: ${fmtDraft(segmentDraft.end)}`;
    segmentSelectEl.innerHTML = "";
    const list = Array.isArray(offlineSegments) ? offlineSegments : [];
    if (list.length === 0) {
        const op = document.createElement("option");
        op.value = "";
        op.textContent = "(sin segmentos)";
        segmentSelectEl.appendChild(op);
        return;
    }
    for (let i = 0; i < list.length; i++) {
        const seg = list[i];
        const op = document.createElement("option");
        op.value = String(i);
        const s = (offlineDataset && Number.isFinite(offlineDataset.minTs)) ? seg.start - offlineDataset.minTs : seg.start;
        const e = (offlineDataset && Number.isFinite(offlineDataset.minTs)) ? seg.end - offlineDataset.minTs : seg.end;
        op.textContent = `${seg.name || ("Seg " + (i + 1))} [${s.toFixed(2)}-${e.toFixed(2)}s]`;
        segmentSelectEl.appendChild(op);
    }
}

function buildLayoutSnapshot() {
    return JSON.stringify({
        monitoredOrder: monitoredOrder.slice(),
        varGraphAssignment: varGraphAssignment,
        arrayElemAssignment: arrayElemAssignment,
        graphList: graphList.slice(),
        graphColumns: graphColumns.map((col) => col.slice()),
        graphColumnFlexByPaneId: JSON.parse(JSON.stringify(graphColumnFlexByPaneId)),
        graphFlightViz: { ...graphFlightVizByGid },
        graphDeltaAnalysisStepByGid: { ...graphDeltaAnalysisStepByGid },
        graphDeltaAnalysisMaxPlotMsByGid: { ...graphDeltaAnalysisMaxPlotMsByGid },
        graphScanWidgetViewByGid: { ...graphScanWidgetViewByGid },
        graphScanWidgetTimePresetByGid: { ...graphScanWidgetTimePresetByGid },
        graphScanWidgetPrefsByGid: JSON.parse(JSON.stringify(graphScanWidgetPrefsByGid)),
        graphScanWidgetGlobalPrefs: JSON.parse(JSON.stringify(graphScanWidgetGlobalPrefs)),
        graphScanWidgetPinnedByGid: { ...graphScanWidgetPinnedByGid },
        graphEntropyScanVarsByGid: JSON.parse(JSON.stringify(graphEntropyScanVarsByGid)),
        graphEntropyScanWindowSecByGid: { ...graphEntropyScanWindowSecByGid },
        graphEntropyScanBinsByGid: { ...graphEntropyScanBinsByGid },
        monitorColumnsCount,
        monitorPaneWidthPx,
        hideLevels,
        compactMonitorLevel,
        liveLayout: liveRoot ? JSON.parse(JSON.stringify(liveRoot)) : null,
        liveLayoutVersion: LIVE_LAYOUT_VERSION,
        plotPaneStateByLeafId: JSON.parse(JSON.stringify(plotPaneStateByLeafId)),
        monitorPaneOrderByLeafId: JSON.parse(JSON.stringify(monitorPaneOrderByLeafId)),
    });
}

function applyLayoutSnapshot(snapshotRaw) {
    try {
        const s = JSON.parse(snapshotRaw);
        applyingLayoutHistory = true;
        monitoredNames.clear();
        monitoredOrder = Array.isArray(s.monitoredOrder) ? s.monitoredOrder.slice() : [];
        monitoredOrder.forEach((n) => monitoredNames.add(n));
        varGraphAssignment = (s.varGraphAssignment && typeof s.varGraphAssignment === "object") ? { ...s.varGraphAssignment } : {};
        migrateVarGraphAssignmentMap(varGraphAssignment);
        arrayElemAssignment = (s.arrayElemAssignment && typeof s.arrayElemAssignment === "object") ? { ...s.arrayElemAssignment } : {};
        graphList = Array.isArray(s.graphList) ? s.graphList.slice() : [];
        graphColumns = Array.isArray(s.graphColumns) ? s.graphColumns.map((col) => Array.isArray(col) ? col.slice() : []) : [];
        graphColumnFlexByPaneId =
            s.graphColumnFlexByPaneId && typeof s.graphColumnFlexByPaneId === "object"
                ? JSON.parse(JSON.stringify(s.graphColumnFlexByPaneId))
                : {};
        graphFlightVizByGid = s.graphFlightViz && typeof s.graphFlightViz === "object" ? { ...s.graphFlightViz } : {};
        graphDeltaAnalysisStepByGid =
            s.graphDeltaAnalysisStepByGid && typeof s.graphDeltaAnalysisStepByGid === "object"
                ? { ...s.graphDeltaAnalysisStepByGid }
                : {};
        graphDeltaAnalysisMaxPlotMsByGid =
            s.graphDeltaAnalysisMaxPlotMsByGid && typeof s.graphDeltaAnalysisMaxPlotMsByGid === "object"
                ? { ...s.graphDeltaAnalysisMaxPlotMsByGid }
                : {};
        graphScanWidgetViewByGid =
            s.graphScanWidgetViewByGid && typeof s.graphScanWidgetViewByGid === "object"
                ? { ...s.graphScanWidgetViewByGid }
                : {};
        graphScanWidgetTimePresetByGid =
            s.graphScanWidgetTimePresetByGid && typeof s.graphScanWidgetTimePresetByGid === "object"
                ? { ...s.graphScanWidgetTimePresetByGid }
                : {};
        graphScanWidgetPrefsByGid =
            s.graphScanWidgetPrefsByGid && typeof s.graphScanWidgetPrefsByGid === "object"
                ? JSON.parse(JSON.stringify(s.graphScanWidgetPrefsByGid))
                : {};
        graphScanWidgetGlobalPrefs =
            s.graphScanWidgetGlobalPrefs && typeof s.graphScanWidgetGlobalPrefs === "object"
                ? JSON.parse(JSON.stringify(s.graphScanWidgetGlobalPrefs))
                : { stepMs: 5, maxPlotMs: 200, mask: { flight: true, nav: true, system: true, other: true } };
        graphScanWidgetPinnedByGid =
            s.graphScanWidgetPinnedByGid && typeof s.graphScanWidgetPinnedByGid === "object"
                ? { ...s.graphScanWidgetPinnedByGid }
                : {};
        graphScanWidgetPinnedSnapshotByGid = {};
        graphEntropyScanVarsByGid = {};
        if (s.graphEntropyScanVarsByGid && typeof s.graphEntropyScanVarsByGid === "object") {
            for (const k of Object.keys(s.graphEntropyScanVarsByGid)) {
                const v = s.graphEntropyScanVarsByGid[k];
                graphEntropyScanVarsByGid[k] = Array.isArray(v) ? v.slice() : [];
            }
        }
        migrateGraphEntropyScanVarsFromConfig();
        graphEntropyScanWindowSecByGid =
            s.graphEntropyScanWindowSecByGid && typeof s.graphEntropyScanWindowSecByGid === "object"
                ? { ...s.graphEntropyScanWindowSecByGid }
                : {};
        graphEntropyScanBinsByGid =
            s.graphEntropyScanBinsByGid && typeof s.graphEntropyScanBinsByGid === "object"
                ? { ...s.graphEntropyScanBinsByGid }
                : {};
        if (typeof s.monitorColumnsCount === "number") monitorColumnsCount = Math.max(1, Math.min(3, s.monitorColumnsCount));
        monitorPaneWidthPx = (typeof s.monitorPaneWidthPx === "number" && Number.isFinite(s.monitorPaneWidthPx)) ? s.monitorPaneWidthPx : null;
        if (typeof s.hideLevels === "number") hideLevels = s.hideLevels;
        if (typeof s.compactMonitorLevel === "number") compactMonitorLevel = Math.max(0, Math.min(100, s.compactMonitorLevel));
        if (hideLevelsInput) hideLevelsInput.value = String(hideLevels);
        liveRoot = null;
        if (s.liveLayout != null) {
            const raw = s.liveLayout;
            const parsed = parseLiveLayout(typeof raw === "string" ? JSON.parse(raw) : raw);
            if (parsed) liveRoot = parsed;
        }
        if (!liveRoot) migrateLegacyLiveLayout();
        sanitizeLiveWidgetDuplicates(liveRoot);
        if (s.plotPaneStateByLeafId && typeof s.plotPaneStateByLeafId === "object") {
            plotPaneStateByLeafId = {};
            for (const k of Object.keys(s.plotPaneStateByLeafId)) {
                const p = s.plotPaneStateByLeafId[k];
                plotPaneStateByLeafId[k] = clonePlotPaneState({
                    graphList: p.graphList,
                    graphColumns: p.graphColumns,
                    varGraphAssignment: p.varGraphAssignment,
                    arrayElemAssignment: p.arrayElemAssignment,
                    graphViewModeByGid: p.graphViewModeByGid,
                    graphBarsYLockByGid: p.graphBarsYLockByGid,
                });
            }
        }
        if (s.monitorPaneOrderByLeafId && typeof s.monitorPaneOrderByLeafId === "object") {
            monitorPaneOrderByLeafId = {};
            for (const k of Object.keys(s.monitorPaneOrderByLeafId)) {
                const o = s.monitorPaneOrderByLeafId[k];
                monitorPaneOrderByLeafId[k] = Array.isArray(o) ? o.slice() : [];
            }
        }
        migratePlotPaneStateIfNeeded();
        migrateMonitorPaneOrderIfNeeded();
        normalizeGraphLayout();
        applyMonitorColumns();
        updateCompactMonitorUi();
        rebuildMonitorList();
        renderLiveLayout();
        renderBrowserList();
        schedulePlotRender();
        saveConfig();
    } catch (e) {
        console.error("No se pudo aplicar snapshot layout:", e);
    } finally {
        applyingLayoutHistory = false;
    }
}

function maybePushLayoutHistory() {
    if (applyingLayoutHistory) return;
    const snap = buildLayoutSnapshot();
    if (snap === lastLayoutSnapshot) return;
    layoutHistoryPast.push(snap);
    if (layoutHistoryPast.length > 80) layoutHistoryPast.shift();
    layoutHistoryFuture = [];
    lastLayoutSnapshot = snap;
}

function doLayoutUndo() {
    if (layoutHistoryPast.length <= 1) return;
    const current = layoutHistoryPast.pop();
    layoutHistoryFuture.push(current);
    const prev = layoutHistoryPast[layoutHistoryPast.length - 1];
    if (prev) applyLayoutSnapshot(prev);
}

function doLayoutRedo() {
    if (layoutHistoryFuture.length === 0) return;
    const next = layoutHistoryFuture.pop();
    if (!next) return;
    layoutHistoryPast.push(next);
    applyLayoutSnapshot(next);
}

function renderArincBusHealth() {
    if (!arincBusHealthPanel) return;
    if (!hasPlugin("arinc")) { arincBusHealthPanel.style.display = "none"; return; }
    arincBusHealthPanel.style.display = "";
    if (isPlaybackMode()) {
        arincBusHealthPanel.innerHTML =
            `<div>ARINC bus health</div>` +
            `<div>Words: ${arincBusHealth.totalWords} | Parity err: ${arincBusHealth.parityErrors} | SSM err: ${arincBusHealth.ssmErrors}</div>`;
        return;
    }
    const labels = Object.entries(arincBusHealth.labels || {}).sort((a, b) => b[1] - a[1]).slice(0, 6);
    const top = labels.length ? labels.map(([k, v]) => `${k}:${v}`).join(" | ") : "—";
    const topParity = Object.entries(arincBusHealth.parityByLabel || {}).sort((a, b) => b[1] - a[1]).slice(0, 4);
    const topParityTxt = topParity.length ? topParity.map(([k, v]) => `${k}:${v}`).join(" | ") : "—";
    const topUnknown = Object.entries(arincBusHealth.unknownByLabel || {}).sort((a, b) => b[1] - a[1]).slice(0, 6);
    const topUnknownTxt = topUnknown.length ? topUnknown.map(([k, v]) => `${k}:${v}`).join(" | ") : "—";
    const tr = I18N[currentLang] || I18N.es;
    const srcLine = (tr.arincBusHealthDefSourceLine || "BD usuario: %1$d | Demo: %2$d")
        .replace("%1$d", String(arincBusHealth.userHits || 0))
        .replace("%2$d", String(arincBusHealth.demoHits || 0));
    arincBusHealthPanel.innerHTML =
        `<div>ARINC bus health</div>` +
        `<div>Words: ${arincBusHealth.totalWords} | Parity err: ${arincBusHealth.parityErrors} | SSM err: ${arincBusHealth.ssmErrors} | Unknown label: ${arincBusHealth.unknownLabels}</div>` +
        `<div>${escapeHtml(srcLine)}</div>` +
        `<div>Top labels (trafico): ${top}</div>` +
        `<div>Top labels (paridad): ${topParityTxt}</div>` +
        `<div>${escapeHtml(tr.arincBusHealthUnknownTop || "Top labels (sin definir en BD):")} ${topUnknownTxt}</div>`;
}

