/**
 * Aplicar config guardada tras el primer tick del módulo.
 * En Firefox, JSON.parse(localStorage) con varmon_config muy grande puede bloquear el hilo >10s;
 * en ventana privada el almacenamiento está vacío → no hay bloqueo → parece "instantáneo".
 */
function readProtocolRegistryTableExpandSession() {
    try {
        const a = sessionStorage.getItem("vm_proto_arinc_show");
        if (a === "1") arincRegistryTableExpanded = true;
        else if (a === "0") arincRegistryTableExpanded = false;
        const m = sessionStorage.getItem("vm_proto_m1553_show");
        if (m === "1") m1553RegistryTableExpanded = true;
        else if (m === "0") m1553RegistryTableExpanded = false;
    } catch {
        /* ignore */
    }
}

function applyInitialConfigFromStorage() {
    loadGlobalDerivedTransformLibrary();
    loadConfig();
    if (!liveRoot) {
        liveRoot = { kind: "leaf", id: "l0", widget: "empty" };
    }
    ensureLiveLayoutHasPlotPane();
    /* Sin credenciales en sesión no se puede usar API sensible (git, editor, BD…): volver a live hasta que el usuario autentique. */
    {
        const needSens = !!authStatus.sensitive_modes_required;
        const needGlob = !!authStatus.auth_required;
        const missingSens = needSens && !sessionStorage.getItem("varmon_sensitive_password");
        const missingGlob = needGlob && !sessionStorage.getItem("varmon_password");
        if ((missingSens || missingGlob) &&
            (appMode === "arinc_registry" || appMode === "file_edit" || appMode === "git_workspace")) {
            appMode = "live";
        }
    }
    readProtocolRegistryTableExpandSession();
    const pss = document.getElementById("arincRegistryPageSizeSelect");
    if (pss) pss.value = String(arincRegistryPageSize);
    pruneArincDerivedFromMonitored();
    applyTheme(currentTheme);
    applyLanguage(currentLang);
    applyMonitorColumns();
    updateCompactMonitorUi();
    applyMonitorGridLines();
    if (adaptiveLoadCheckbox) adaptiveLoadCheckbox.checked = !!adaptiveLoadEnabled;
    if (compactMonitorSlider) compactMonitorSlider.value = String(compactMonitorLevel);
    if (downsampleMaxPointsInput) downsampleMaxPointsInput.value = String(downsampleMaxPoints);
    renderSegmentsUi();
    renderNotesList();
    renderPerfTelemetry();
    renderArincBusHealth();
    setModeUi();
    ensureOfflineAdvancedToolsButtons();
    pruneFlightVizGraphConfigIfNeeded();
    /* Modos plugin: onEnter solo se dispara dentro de setAppMode() al cambiar modo; al restaurar appMode desde localStorage hace falta montar el panel (p. ej. flight_viz). */
    if (hasRegisteredAppMode(appMode)) {
        const pm = getRegisteredAppModeMeta(appMode);
        if (pm && typeof pm.onEnter === "function") {
            queueMicrotask(() => {
                try {
                    pm.onEnter();
                } catch (e) {
                    console.error("[VarMonitor] onEnter modo plugin (config inicial):", e);
                }
            });
        }
    }
    renderLiveLayout();
    if (!window._livePaletteWired) {
        window._livePaletteWired = true;
        wireLivePaletteAndSlots();
    }
    lastLayoutSnapshot = buildLayoutSnapshot();
    layoutHistoryPast = [lastLayoutSnapshot];
    (async () => {
        if (appMode !== "offline") return;
        try {
            await refreshServerRecordings();
            const hasOverlay = Array.isArray(offlineOverlaySelectedRecordings) && offlineOverlaySelectedRecordings.length > 1;
            if (hasOverlay) {
                const ok = await restoreOfflineOverlayFromConfig({
                    offlineOverlaySelectedRecordings,
                    offlineOverlayUnifyTime,
                    offlineOverlayDeltaSec,
                }, { preserveLayout: true });
                if (!ok && offlineRecordingName) {
                    await loadRecordingFromServer(offlineRecordingName, { preserveLayout: true });
                }
                return;
            }
            if (!offlineRecordingName) return;
            await loadRecordingFromServer(offlineRecordingName, { preserveLayout: true });
        } catch (e) {
            console.warn("No se pudo restaurar TSV guardado:", offlineRecordingName, e);
        }
    })();
}

function _initRecordingFormatSelector() {
    if (!recordingFormatSelect) return;
    const descriptions = {
        tsv: "Formato tabular (TSV) compatible con cualquier hoja de cálculo.",
    };
    function updateInfo() {
        if (recordingFormatInfo) {
            recordingFormatInfo.textContent = descriptions[recordingFormatSelect.value] || "";
        }
    }
    recordingFormatSelect.addEventListener("change", () => {
        updateInfo();
        saveConfig();
    });
    updateInfo();
}

/* Timeout acotado: si import() de plugins cuelga, el arranque sigue (tema/layout). */
const _PLUGINS_LOAD_MS = 20000;
function loadExternalPluginsWithGuard() {
    return Promise.race([
        loadExternalPlugins(),
        new Promise((_, rej) =>
            setTimeout(() => rej(new Error("loadExternalPlugins timeout")), _PLUGINS_LOAD_MS),
        ),
    ]);
}

loadExternalPluginsWithGuard()
    .catch((e) => {
        console.warn("[VarMonitor] plugins externos (se continúa el arranque):", e);
    })
    .then(async () => {
        syncPluginModeOptions();
        refreshHelpModalBody();
        await refreshAuthStatus();
        fireHook("on_app_init");
        refreshAnalysisReportContext();
        fireHook("offline_plugin_mount", document.getElementById("offlinePluginMount"));
        _initRecordingFormatSelector();
        applyInitialConfigFromStorage();
        wireArincRegistryUi();
        wireProtocolRegistryTabs();
        applyProtocolRegistryTab(getProtocolRegistryTab());
        wireReplayAliasUi();
        await checkAuthThenStart();
        if (!authOverlay || window.getComputedStyle(authOverlay).display === "none") {
            openFirstRunModePickerIfNeeded();
        }
    });

