// --- Visor de log del servidor ---
const logBtn = document.getElementById("logBtn");
const logOverlay = document.getElementById("logOverlay");
const logCloseBtn = document.getElementById("logCloseBtn");
const logRefreshBtn = document.getElementById("logRefreshBtn");
const logAutoRefreshCheckbox = document.getElementById("logAutoRefreshCheckbox");
const logSourceSelect = document.getElementById("logSourceSelect");
const logViewerContent = document.getElementById("logViewerContent");
const logFilterInput = document.getElementById("logFilterInput");
const logSaveBtn = document.getElementById("logSaveBtn");
let logAutoRefreshInterval = null;
let logViewerRawLines = [];
/** Último seq del buffer Python (GET /api/log); el auto-refresh usa since_seq para no bajar 2000 líneas cada vez. */
let logViewerMaxSeq = 0;

function escapeLogHtml(s) {
    return String(s)
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;");
}

function logLineClass(line) {
    const l = line.toLowerCase();
    if (/\b(200|ok|success)\b/.test(l) || /-> 200\b/.test(line)) return "log-line-ok";
    if (/\b(500|404|503|error|exception|failed|fail|incorrecta|denied)\b/.test(l) || /-> (4|5)\d{2}\b/.test(line)) return "log-line-error";
    if (/\[varmonitor shm\]/i.test(line)) {
        if (/pérdida|perdida/i.test(line)) return "log-line-error";
        if (/warning/i.test(line)) return "log-line-warn";
    }
    if (/\b(4\d{2}|warn|warning|aviso)\b/.test(l)) return "log-line-warn";
    if (/\[req\]/.test(l)) return "log-line-req";
    return "";
}

function applyLogViewerFilter() {
    if (!logViewerContent) return;
    const q = (logFilterInput && logFilterInput.value) ? logFilterInput.value.trim().toLowerCase() : "";
    const lines = q
        ? logViewerRawLines.filter((line) => line.toLowerCase().includes(q))
        : logViewerRawLines;
    if (lines.length === 0) {
        logViewerContent.textContent = q ? "(ninguna línea coincide con el filtro)" : "(vacío)";
        logViewerContent.className = "log-viewer-content";
        return;
    }
    const cls = "log-viewer-content";
    const html = lines
        .map((line) => {
            const c = logLineClass(line);
            return '<span class="log-line ' + (c ? c : "") + '">' + escapeLogHtml(line) + "</span>\n";
        })
        .join("");
    logViewerContent.innerHTML = html;
    logViewerContent.className = cls;
    logViewerContent.scrollTop = logViewerContent.scrollHeight;
}

async function fetchLogViewer(options) {
    if (!logViewerContent) return;
    const incremental = options && options.incremental;
    const source = (logSourceSelect && logSourceSelect.value) || "python";
    try {
        let url;
        if (incremental && source === "python" && logViewerMaxSeq > 0) {
            url =
                "/api/log?since_seq=" +
                encodeURIComponent(String(logViewerMaxSeq)) +
                "&limit=500&source=python";
        } else {
            url = `/api/log?tail=2000&source=${encodeURIComponent(source)}`;
        }
        const r = await fetch(url);
        if (!r.ok) {
            logViewerRawLines = [`Error ${r.status}: ${r.statusText}`];
            applyLogViewerFilter();
            return;
        }
        const contentType = r.headers.get("content-type") || "";
        if (contentType.includes("application/json")) {
            const data = await r.json();
            const rows = data.lines || [];
            const toText = (x) => (x.ts ? x.ts + " " : "") + (x.msg || "");
            if (!incremental) {
                logViewerMaxSeq = source === "cpp" ? 0 : typeof data.max_seq === "number" ? data.max_seq : 0;
            } else if (typeof data.max_seq === "number" && data.max_seq >= logViewerMaxSeq) {
                logViewerMaxSeq = data.max_seq;
            }
            if (incremental && source === "python" && rows.length > 0) {
                logViewerRawLines = logViewerRawLines.concat(rows.map(toText));
                const cap = 3500;
                if (logViewerRawLines.length > cap) {
                    logViewerRawLines = logViewerRawLines.slice(-cap);
                }
            } else {
                logViewerRawLines = rows.map(toText);
            }
        } else {
            const text = await r.text() || "";
            logViewerRawLines = text ? text.split("\n") : [];
        }
        applyLogViewerFilter();
    } catch (e) {
        logViewerRawLines = ["Error al cargar el registro: " + (e.message || String(e))];
        applyLogViewerFilter();
    }
}

function downloadLogViewer() {
    const text = logViewerContent ? logViewerContent.textContent : "";
    if (!text) return;
    const now = new Date();
    const stamp =
        now.getFullYear() +
        String(now.getMonth() + 1).padStart(2, "0") +
        String(now.getDate()).padStart(2, "0") +
        "_" +
        String(now.getHours()).padStart(2, "0") +
        String(now.getMinutes()).padStart(2, "0") +
        String(now.getSeconds()).padStart(2, "0");
    const name = "varmon_log_" + stamp + ".txt";
    const blob = new Blob([text], { type: "text/plain;charset=utf-8" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    a.href = url;
    a.download = name;
    a.click();
    URL.revokeObjectURL(url);
}

if (logBtn && logOverlay) {
    logBtn.addEventListener("click", () => {
        logOverlay.style.display = "flex";
        fetchLogViewer();
    });
}
if (logCloseBtn && logOverlay) {
    logCloseBtn.addEventListener("click", () => {
        logOverlay.style.display = "none";
        if (logAutoRefreshInterval) {
            clearInterval(logAutoRefreshInterval);
            logAutoRefreshInterval = null;
        }
        if (logAutoRefreshCheckbox) logAutoRefreshCheckbox.checked = false;
    });
}
logOverlay.addEventListener("click", (e) => {
    if (e.target === logOverlay) {
        logOverlay.style.display = "none";
        if (logAutoRefreshInterval) {
            clearInterval(logAutoRefreshInterval);
            logAutoRefreshInterval = null;
        }
        if (logAutoRefreshCheckbox) logAutoRefreshCheckbox.checked = false;
    }
});
if (logRefreshBtn) {
    logRefreshBtn.addEventListener("click", () => fetchLogViewer());
}
if (logAutoRefreshCheckbox) {
    logAutoRefreshCheckbox.addEventListener("change", () => {
        if (logAutoRefreshCheckbox.checked) {
            if (logAutoRefreshInterval) clearInterval(logAutoRefreshInterval);
            logAutoRefreshInterval = setInterval(() => {
                if (logOverlay && logOverlay.style.display === "flex") {
                    fetchLogViewer({ incremental: true });
                }
            }, 4000);
        } else {
            if (logAutoRefreshInterval) {
                clearInterval(logAutoRefreshInterval);
                logAutoRefreshInterval = null;
            }
        }
    });
}
if (logSourceSelect) {
    logSourceSelect.addEventListener("change", () => fetchLogViewer());
}
if (logFilterInput) {
    logFilterInput.addEventListener("input", () => applyLogViewerFilter());
    logFilterInput.addEventListener("keydown", (e) => {
        if (e.key === "Escape") {
            logFilterInput.value = "";
            applyLogViewerFilter();
        }
    });
}
if (logSaveBtn) {
    logSaveBtn.addEventListener("click", () => downloadLogViewer());
}

// --- Panel Perf (fases; lease renovado solo con panel abierto o stats avanzadas) ---
const perfBtn = document.getElementById("perfBtn");
const perfOverlay = document.getElementById("perfOverlay");
const perfCloseBtn = document.getElementById("perfCloseBtn");
const perfPanelBody = document.getElementById("perfPanelBody");
let perfPollInterval = null;

const PERF_BAR_COLORS = ["#6c8cff", "#4ade80", "#fb923c", "#a78bfa", "#f472b6", "#22d3ee", "#eab308"];

function perfBarColorAt(i) {
    return PERF_BAR_COLORS[i % PERF_BAR_COLORS.length];
}

/** Barra apilada + leyenda (mismo orden izquierda→derecha que la barra). */
function buildPerfBarSegments(phases) {
    if (!phases || phases.length === 0) {
        return '<div class="perf-bar perf-bar-empty">Sin datos</div>';
    }
    let sum = 0;
    phases.forEach((p) => {
        sum += Math.max(0, Number(p.ema_us) || 0);
    });
    if (sum <= 0) sum = 1;
    let barHtml = '<div class="perf-bar">';
    let legendHtml =
        '<div class="perf-bar-legend"><span class="perf-bar-legend-title">Leyenda:</span>';
    phases.forEach((p, i) => {
        const w = (Math.max(0, Number(p.ema_us) || 0) / sum) * 100;
        const title = escapeLogHtml(String(p.id || ""));
        const col = perfBarColorAt(i);
        barHtml +=
            '<div class="perf-bar-seg" style="width:' +
            w.toFixed(1) +
            "%;background:" +
            col +
            '" title="' +
            title +
            '"></div>';
        legendHtml +=
            '<span class="perf-legend-item"><span class="perf-legend-swatch" style="background:' +
            col +
            '"></span><span class="perf-legend-label">' +
            title +
            "</span></span>";
    });
    barHtml += "</div>";
    legendHtml += "</div>";
    return '<div class="perf-bar-block">' + barHtml + legendHtml + "</div>";
}

function renderPerfPanel(data) {
    if (!perfPanelBody) return;
    if (!data) {
        perfPanelBody.innerHTML = '<p class="perf-hint">No se pudo cargar /api/perf.</p>';
        return;
    }
    if (!data.lease_active) {
        perfPanelBody.innerHTML =
            '<p class="perf-hint">Sesión de medición inactiva. Cierra y vuelve a abrir, o activa la tira de estadísticas avanzadas.</p>';
        return;
    }
    const layers = data.layers || {};
    const layerOrder = [
        ["cpp", "C++ (write_snapshot → SHM)"],
        ["sidecar", "Sidecar (varmon_sidecar, grabación)"],
        ["python", "Python (backend)"],
        ["browser", "Navegador (gráficos, esta pestaña)"],
    ];
    let html = "";
    layerOrder.forEach(([key, title]) => {
        let phases = (layers[key] && layers[key].phases) ? layers[key].phases.slice() : [];
        if (key === "browser") {
            const r = renderStats;
            phases = [
                {
                    id: "browser.plot_render_ms",
                    last_us: (Number(r.lastMs) || 0) * 1000,
                    ema_us: (Number(r.avgMs) || 0) * 1000,
                    samples: Number(r.ticks) || 0,
                },
            ];
        }
        html += '<section class="perf-layer"><h3>' + escapeLogHtml(title) + "</h3>";
        if (key === "cpp") {
            html +=
                '<p class="perf-layer-note">Las fases C++ miden el <strong>tiempo de CPU</strong> dentro de una ejecución de <code>write_snapshot</code> (suele ser muy pequeño). ' +
                "El <strong>ciclo SHM</strong> de la tira de estadísticas avanzadas es el <strong>intervalo entre snapshots</strong> (ritmo del proceso RT; p. ej. ~50&nbsp;ms si publicas cada 50&nbsp;ms): " +
                "no es la suma de estas fases ni el “coste” de escribir SHM en milisegundos de pared.</p>";
        }
        if (key === "sidecar") {
            html +=
                '<p class="perf-layer-note">Tiempos de <strong>reloj monótono</strong> (pared) por ciclo de consumo SHM durante <strong>REC sidecar</strong>: <code>sem_wait</code> incluye bloqueo hasta el siguiente <code>post</code> del C++. ' +
                "Ruta <strong>anillo v2</strong>: fases <code>ring_*</code>; ruta snapshot: <code>parse_snapshot</code>, <code>snap_*</code>. Sin grabación activa esta capa suele estar vacía.</p>";
        }
        html += buildPerfBarSegments(phases);
        html +=
            '<table class="perf-table"><thead><tr><th class="perf-th-swatch"></th><th>Fase</th><th>Último (ms)</th><th>EMA (ms)</th><th>Muestras</th></tr></thead><tbody>';
        if (!phases.length) {
            html += '<tr><td colspan="5">Sin datos</td></tr>';
        } else {
            phases.forEach((p, i) => {
                const id = escapeLogHtml(String(p.id || ""));
                const lu = ((Number(p.last_us) || 0) / 1000).toFixed(3);
                const em = ((Number(p.ema_us) || 0) / 1000).toFixed(3);
                const sm = Number(p.samples) || 0;
                const col = perfBarColorAt(i);
                html +=
                    '<tr><td class="perf-td-swatch"><span class="perf-row-swatch" style="background:' +
                    col +
                    '" title="' +
                    id +
                    '"></span></td><td>' +
                    id +
                    "</td><td>" +
                    lu +
                    "</td><td>" +
                    em +
                    "</td><td>" +
                    sm +
                    "</td></tr>";
            });
        }
        html += "</tbody></table></section>";
    });
    perfPanelBody.innerHTML = html;
}

async function fetchPerfPanel() {
    try {
        const r = await fetch("/api/perf");
        if (!r.ok) {
            renderPerfPanel(null);
            return;
        }
        const d = await r.json();
        renderPerfPanel(d);
    } catch (e) {
        if (perfPanelBody) {
            perfPanelBody.innerHTML =
                '<p class="perf-hint">Error: ' + escapeLogHtml(e.message || String(e)) + "</p>";
        }
    }
}

function stopPerfPolling() {
    if (perfPollInterval) {
        clearInterval(perfPollInterval);
        perfPollInterval = null;
    }
}

if (perfBtn && perfOverlay) {
    perfBtn.addEventListener("click", () => {
        perfOverlay.style.display = "flex";
        fetchPerfPanel();
        stopPerfPolling();
        perfPollInterval = setInterval(() => {
            if (perfOverlay && perfOverlay.style.display === "flex") fetchPerfPanel();
        }, 1000);
    });
}
if (perfCloseBtn && perfOverlay) {
    perfCloseBtn.addEventListener("click", () => {
        perfOverlay.style.display = "none";
        stopPerfPolling();
    });
}
if (perfOverlay) {
    perfOverlay.addEventListener("click", (e) => {
        if (e.target === perfOverlay) {
            perfOverlay.style.display = "none";
            stopPerfPolling();
        }
    });
}

// --- Variable browser drawer (columna 1 como panel lateral derecho) ---

const browserToggleBtn = document.getElementById("browserToggleBtn");
const varDrawer = document.getElementById("varDrawer");
const browserCloseBtn = document.getElementById("browserCloseBtn");
const colMonitorEl = document.querySelector(".col-monitor");
let varDrawerMeasureEl = null;

function estimateVarDrawerDesiredWidth() {
    const baseWidth = 300;
    if (!Array.isArray(knownVarNames) || knownVarNames.length === 0) return baseWidth;
    let longest = "";
    for (let i = 0; i < knownVarNames.length; i++) {
        const n = String(knownVarNames[i] || "");
        if (n.length > longest.length) longest = n;
    }
    if (!longest) return baseWidth;
    if (!varDrawerMeasureEl) {
        varDrawerMeasureEl = document.createElement("span");
        varDrawerMeasureEl.className = "tree-leaf-name";
        varDrawerMeasureEl.style.position = "fixed";
        varDrawerMeasureEl.style.left = "-99999px";
        varDrawerMeasureEl.style.top = "0";
        varDrawerMeasureEl.style.visibility = "hidden";
        varDrawerMeasureEl.style.whiteSpace = "nowrap";
        document.body.appendChild(varDrawerMeasureEl);
    }
    varDrawerMeasureEl.textContent = longest;
    // Texto + checkbox + badge TSV + paddings/márgenes del item.
    const measured = Math.ceil(varDrawerMeasureEl.getBoundingClientRect().width + 110);
    return Math.max(280, Math.min(820, measured));
}

function positionVarDrawer() {
    if (!varDrawer || !colMonitorEl) return;
    const rect = colMonitorEl.getBoundingClientRect();
    const margin = 8;
    const desiredWidth = estimateVarDrawerDesiredWidth();
    const availableRight = Math.max(220, window.innerWidth - rect.right - margin);
    const width = Math.min(desiredWidth, availableRight);
    const left = Math.min(rect.right + margin, window.innerWidth - width - margin);
    const top = Math.max(0, rect.top);
    const height = Math.max(200, rect.height);
    varDrawer.style.left = `${Math.max(margin, left)}px`;
    varDrawer.style.top = `${top}px`;
    varDrawer.style.height = `${height}px`;
    varDrawer.style.width = `${width}px`;
}

function openVarDrawer() {
    if (varDrawer) {
        positionVarDrawer();
        varDrawer.style.display = "flex";
        // Tras mostrar el cajón, el alto real de #varBrowserList ya es fiable; re-renderiza la lista virtual.
        requestAnimationFrame(() => {
            renderBrowserList();
            positionVarDrawer();
        });
    }
}

function closeVarDrawer() {
    if (varDrawer) varDrawer.style.display = "none";
}

if (browserToggleBtn && varDrawer) {
    browserToggleBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const visible = varDrawer.style.display === "flex";
        if (visible) closeVarDrawer(); else openVarDrawer();
    });
}
if (browserCloseBtn) {
    browserCloseBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        closeVarDrawer();
    });
}
window.addEventListener("resize", () => {
    applyMonitorPaneWidth();
    if (varDrawer && varDrawer.style.display === "flex") positionVarDrawer();
    schedulePlotGridResize();
});

if (monitorResizeHandle && colMonitorEl) {
    let dragState = null;
    const onMove = (e) => {
        if (!dragState) return;
        const dx = e.clientX - dragState.startX;
        monitorPaneWidthPx = clampMonitorPaneWidth(dragState.startWidth + dx);
        applyMonitorPaneWidth();
        positionVarDrawer();
        schedulePlotGridResize();
    };
    const onUp = () => {
        if (!dragState) return;
        dragState = null;
        monitorResizeHandle.classList.remove("dragging");
        document.body.style.cursor = "";
        document.removeEventListener("mousemove", onMove);
        document.removeEventListener("mouseup", onUp);
        saveConfig();
    };
    monitorResizeHandle.addEventListener("mousedown", (e) => {
        if (window.matchMedia("(max-width: 900px)").matches) return;
        e.preventDefault();
        const rect = colMonitorEl.getBoundingClientRect();
        dragState = { startX: e.clientX, startWidth: rect.width };
        monitorResizeHandle.classList.add("dragging");
        document.body.style.cursor = "col-resize";
        document.addEventListener("mousemove", onMove);
        document.addEventListener("mouseup", onUp);
    });
}

