// --- WebSocket ---

let connectionId = 0;
let connectionInfo = null;
let udsInstances = [];
let warningDismissed = false;
/** Último `uds_path` enviado en el WS (`null` = sin query). */
let lastConnectUdsParam = null;

function effectiveUdsPathForWs() {
    const sel = (portSelect && portSelect.value) ? String(portSelect.value).trim() : "";
    if (sel.startsWith("uds:")) return sel.slice(4);
    const saved = savedInstance ? String(savedInstance).trim() : "";
    if (saved.startsWith("uds:")) return saved.slice(4);
    return "";
}

function ensureWsMatchesSelection() {
    if (!hasBackendConnectionMode()) {
        setOfflineStatus();
        return;
    }
    if (isOfflineMode()) return;
    if (udsInstances.length === 0) {
        statusEl.textContent = (I18N[currentLang] || I18N.es).statusNoInstances || "No hay instancias VarMonitor (UDS)";
        statusEl.className = "status disconnected";
        const st = ws ? ws.readyState : WebSocket.CLOSED;
        if (st !== WebSocket.OPEN && st !== WebSocket.CONNECTING) {
            connect();
        }
        return;
    }
    const wantRaw = effectiveUdsPathForWs();
    const wantParam = wantRaw ? wantRaw : null;
    if (ws && wantParam === lastConnectUdsParam) {
        if (ws.readyState === WebSocket.OPEN) return;
        if (ws.readyState === WebSocket.CONNECTING) return;
    }
    connect();
}

function fetchConnectionInfo() {
    return fetch("/api/connection_info")
        .then((r) => r.ok ? r.json() : null)
        .then(async (data) => {
            connectionInfo = data;
            const user = (data && data.current_user) ? encodeURIComponent(data.current_user) : "";
            const udsUrl = user ? `/api/uds_instances?user=${user}` : "/api/uds_instances";
            try {
                const u = await fetch(udsUrl).then((r) => r.ok ? r.json() : null);
                udsInstances = (u && Array.isArray(u.instances)) ? u.instances : [];
                if (udsInstances.length === 0 && user) {
                    const u2 = await fetch("/api/uds_instances").then((r) => r.ok ? r.json() : null);
                    udsInstances = (u2 && Array.isArray(u2.instances)) ? u2.instances : [];
                }
            } catch (e) {
                udsInstances = [];
            }
            if (data && typeof data.update_ratio_max === "number" && intervalInput) {
                intervalInput.max = Math.max(1, data.update_ratio_max);
            }
            if (data && typeof data.visual_buffer_sec === "number" && timeWindowSelect) {
                const s = Math.max(1, Math.min(7200, Math.floor(data.visual_buffer_sec)));
                if (defaultVisualBufferInput) defaultVisualBufferInput.value = String(s);
                let hasSavedTimeWindow = false;
                try {
                    const raw = localStorage.getItem(STORAGE_KEY);
                    if (raw) {
                        const c = JSON.parse(raw);
                        hasSavedTimeWindow = c && (c.timeWindow != null || c.historyBuffer != null);
                    }
                } catch (e) { /* ignore */ }
                if (!hasSavedTimeWindow) {
                    let closest = timeWindowSelect.options[0]?.value || String(s);
                    let bestDiff = Infinity;
                    for (let i = 0; i < timeWindowSelect.options.length; i++) {
                        const opt = timeWindowSelect.options[i];
                        const val = Number(opt.value);
                        if (!Number.isFinite(val) || val <= 0) continue;
                        const d = Math.abs(val - s);
                        if (d < bestDiff) {
                            bestDiff = d;
                            closest = opt.value;
                        }
                    }
                    timeWindowSelect.value = closest;
                    const sec = parseInt(closest, 10);
                    localHistMaxSec = (Number.isFinite(sec) && sec > 0) ? sec : DEFAULT_LOCAL_HIST_MAX_SEC;
                    if (isLiveMode()) trimLocalHistory();
                    schedulePlotRender();
                }
            }
            updateMultiInstanceWarning();
            return data;
        })
        .catch(() => null);
}

function fillPortSelectWithUds() {
    if (!portSelect) return;
    portSelect.innerHTML = "";
    for (const inst of udsInstances) {
        const opt = document.createElement("option");
        opt.value = "uds:" + inst.uds_path;
        opt.textContent = (inst.user || "?") + " — PID " + (inst.pid != null ? inst.pid : "?");
        portSelect.appendChild(opt);
    }
    if (portSelect.options.length > 0) {
        if (savedInstance && Array.from(portSelect.options).some(o => o.value === savedInstance)) {
            portSelect.value = savedInstance;
        } else {
            portSelect.value = portSelect.options[0].value;
        }
    }
}

function updateMultiInstanceWarning() {
    if (!multiInstanceWarningEl || !multiInstanceWarningText) return;
    const tr = (I18N[currentLang] || I18N.es);
    const parts = [];
    let showSuggestedLink = false;
    let suggestedPort = null;
    let suggestedUrl = null;

    const actualWeb = connectionInfo && connectionInfo.actual_web_port != null ? connectionInfo.actual_web_port : null;
    const suggestedWeb = connectionInfo && connectionInfo.suggested_web_port != null ? connectionInfo.suggested_web_port : null;
    if (connectionInfo && actualWeb != null && suggestedWeb != null && actualWeb !== suggestedWeb) {
        const uptimeSec = connectionInfo.uptime_seconds;
        if (uptimeSec != null && uptimeSec >= 0) {
            const min = Math.floor(uptimeSec / 60);
            parts.push((tr.backendUptimeMinutes || "This backend has been running for %d min.").replace("%d", String(min)));
        }
        showSuggestedLink = true;
        suggestedPort = suggestedWeb;
        suggestedUrl = window.location.protocol + "//" + window.location.hostname + ":" + suggestedWeb;
    }

    const suggestedSuffixEl = document.getElementById("multiInstanceWarningSuggestedSuffix");
    if (suggestedSuffixEl) suggestedSuffixEl.textContent = "";

    if (parts.length === 0) {
        warningDismissed = false;
        multiInstanceWarningEl.style.display = "none";
        if (multiInstanceWarningSuggestedWrap) multiInstanceWarningSuggestedWrap.style.display = "none";
    } else if (!warningDismissed) {
        multiInstanceWarningText.textContent = parts.join(" ");
        if (multiInstanceWarningSuggestedWrap && multiInstanceWarningLink && multiInstanceWarningSuggestedPrefix) {
            if (showSuggestedLink && suggestedPort != null && suggestedUrl) {
                multiInstanceWarningSuggestedPrefix.textContent = (tr.suggestedPortPrefixBefore !== undefined ? tr.suggestedPortPrefixBefore : "En el ");
                multiInstanceWarningLink.href = suggestedUrl;
                multiInstanceWarningLink.textContent = String(suggestedPort);
                multiInstanceWarningSuggestedWrap.style.display = "inline";
                fetch(suggestedUrl + "/api/instance_info")
                    .then((r) => r.ok ? r.json() : null)
                    .then((info) => {
                        const suf = document.getElementById("multiInstanceWarningSuggestedSuffix");
                        if (suf && info && info.user) {
                            const fmt = tr.suggestedPortSuffixUser || " usuario %s.";
                            suf.textContent = fmt.replace("%s", info.user);
                        }
                    })
                    .catch(() => {});
            } else {
                multiInstanceWarningSuggestedWrap.style.display = "none";
            }
        }
        multiInstanceWarningEl.style.display = "flex";
    }
}

function hideMultiInstanceWarning() {
    warningDismissed = true;
    if (multiInstanceWarningEl) multiInstanceWarningEl.style.display = "none";
}

function formatAdvNum(v) {
    if (v == null || typeof v !== "number" || isNaN(v)) return "—";
    if (v >= 100) return v.toFixed(0);
    if (v >= 1) return v.toFixed(2);
    return v.toFixed(3);
}

async function updateAdvancedStatsStrip() {
    if (!advancedStatsStrip || advancedStatsStrip.style.display !== "flex") return;
    if (advRamHtml) {
        let htmlMb = null;
        let htmlTotalMb = null;
        let htmlLimitMb = null;
        try {
            const mem = typeof performance !== "undefined" && performance.memory;
            if (mem && typeof mem.usedJSHeapSize === "number") {
                htmlMb = mem.usedJSHeapSize / (1024 * 1024);
                if (typeof mem.totalJSHeapSize === "number") htmlTotalMb = mem.totalJSHeapSize / (1024 * 1024);
                if (typeof mem.jsHeapSizeLimit === "number") htmlLimitMb = mem.jsHeapSizeLimit / (1024 * 1024);
            }
        } catch (err) { /* performance.memory no disponible (solo Chrome/Chromium) */ }
        advRamHtml.textContent = "HTML: " + (htmlMb != null ? formatAdvNum(htmlMb) + " MB" : "—");
        if (htmlMb != null) {
            let t = `Heap JS (V8): ${formatAdvNum(htmlMb)} MB usados`;
            if (htmlTotalMb != null) t += ` · ${formatAdvNum(htmlTotalMb)} MB reservados por el motor`;
            if (htmlLimitMb != null) t += ` (límite ~${formatAdvNum(htmlLimitMb)} MB)`;
            t += ". El monitor del portátil / administrador de tareas muestra la RAM de TODO el proceso del navegador (GPU, WebGL, librerías nativas, Plotly, etc.), no esta cifra; suele ser varias veces mayor y puede no bajar aunque el heap JS se estabilice.";
            advRamHtml.title = t;
        } else {
            advRamHtml.title = "No disponible en Firefox (solo Chrome/Chromium expone performance.memory)";
        }
    }
    try {
        const r = await fetch("/api/advanced_stats?perf=1");
        if (r.ok) {
            const d = await r.json();
            if (advRamPython) advRamPython.textContent = "Py: " + formatAdvNum(d.python_ram_mb) + " MB";
            if (advRamCpp) advRamCpp.textContent = "C++: " + formatAdvNum(d.cpp_ram_mb) + " MB";
            if (advCpuPython)
                advCpuPython.textContent = (d.python_cpu_percent != null && !isNaN(d.python_cpu_percent))
                    ? "Py: " + formatAdvNum(d.python_cpu_percent) + "%"
                    : "Py: —";
            if (advCpuCpp)
                advCpuCpp.textContent = (d.cpp_cpu_percent != null && !isNaN(d.cpp_cpu_percent))
                    ? "C++: " + formatAdvNum(d.cpp_cpu_percent) + "%"
                    : "C++: —";
            if (advShmCycle) {
                advShmCycle.title =
                    "Período entre publicaciones SHM (EMA en Python). Con C++ reciente el valor viene del campo publish_period_sec en cabecera (diferencia de timestamps entre ciclos del publicador), no del ritmo al que Python procesa la cola. " +
                    "Con segmentos antiguos sin ese campo se usa el Δt entre timestamps de snapshots consecutivos procesados. No es el tiempo de CPU de write_snapshot.";
                advShmCycle.textContent =
                    d.shm_cycle_ms != null && !isNaN(d.shm_cycle_ms)
                        ? "ciclo SHM: " + formatAdvNum(d.shm_cycle_ms) + " ms"
                        : "ciclo SHM: —";
            }
            if (advMonCount) {
                const mc = d.monitored_var_count;
                advMonCount.textContent = (typeof mc === "number" && Number.isFinite(mc))
                    ? "vars: " + String(Math.max(0, Math.round(mc)))
                    : "vars: —";
            }
        }
    } catch (e) {
        if (advRamPython) advRamPython.textContent = "Py: —";
        if (advRamCpp) advRamCpp.textContent = "C++: —";
        if (advCpuPython) advCpuPython.textContent = "Py: —";
        if (advCpuCpp) advCpuCpp.textContent = "C++: —";
        if (advShmCycle) {
            advShmCycle.textContent = "ciclo SHM: —";
            advShmCycle.title = "";
        }
        if (advMonCount) advMonCount.textContent = "vars: —";
    }
    const now = Date.now();
    const cutoff = now - WS_BUFFER_MAX_AGE_MS;
    const recent = wsMessageBuffer.filter((x) => x.t >= cutoff);
    const n = recent.length;
    const totalBytes = recent.reduce((s, x) => s + x.size, 0);
    const spanSec = (recent.length ? (now - Math.min(...recent.map((x) => x.t))) / 1000 : 0) || 1;
    const msgPerS = n / spanSec;
    const mbPerS = totalBytes / (1024 * 1024) / spanSec;
    const mbPerMsg = n > 0 ? totalBytes / (1024 * 1024) / n : 0;
    if (advNetMbMsg) advNetMbMsg.textContent = "MB/msg: " + formatAdvNum(mbPerMsg);
    if (advNetMsgS) advNetMsgS.textContent = "msg/s: " + formatAdvNum(msgPerS);
    if (advNetMbS) advNetMbS.textContent = "MB/s: " + formatAdvNum(mbPerS);
}

function setAdvInfoEnabled(enabled) {
    try { localStorage.setItem(ADV_INFO_STORAGE_KEY, enabled ? "1" : "0"); } catch (e) {}
    if (advancedStatsStrip) {
        advancedStatsStrip.style.display = enabled ? "flex" : "none";
        advancedStatsStrip.setAttribute("aria-hidden", !enabled);
    }
    if (advStatsPollInterval) {
        clearInterval(advStatsPollInterval);
        advStatsPollInterval = null;
    }
    if (enabled) {
        updateAdvancedStatsStrip();
        advStatsPollInterval = setInterval(updateAdvancedStatsStrip, 5000);
    }
}

function isOfflineMode() { return appMode === "offline"; }
function isLiveMode() { return appMode === "live"; }
function isReplayMode() { return appMode === "replay"; }
/** FFT/Hist de live solo si el proveedor MAVLink está activo en runtime. */
function hasMavlinkRuntimeProvider() {
    return typeof globalThis.__VARMON_GET_MAVLINK_SCAN_RESULT__ === "function";
}
function getMavlinkScanApi() {
    const api = globalThis.__VARMON_MAVLINK_SCAN_API__;
    return api && typeof api === "object" ? api : null;
}
function hasMavlinkScanProvider() {
    const api = getMavlinkScanApi();
    return !!(api && typeof api.renderWidget === "function" && typeof api.getResult === "function");
}
function hasAnyActiveScanWidget() {
    for (const v of Object.values(graphFlightVizByGid || {})) {
        if (v === "scan_widget") return true;
    }
    return false;
}
function hasAnyUnpinnedActiveScanWidget() {
    for (const [gid, v] of Object.entries(graphFlightVizByGid || {})) {
        if (v !== "scan_widget") continue;
        if (graphScanWidgetPinnedByGid[gid]) continue;
        return true;
    }
    return false;
}
function getScanWidgetsAutoRefreshMs() {
    const vals = [];
    for (const [gid, v] of Object.entries(graphFlightVizByGid || {})) {
        if (v !== "scan_widget") continue;
        if (graphScanWidgetPinnedByGid[gid]) continue;
        vals.push(scanWidgetPresetMsForGid(gid));
    }
    if (!vals.length) return 10000;
    return Math.max(1000, Math.min(...vals));
}
function ensureMavlinkScanWidgetPolling() {
    const shouldRun = isLiveMode() && hasAnyUnpinnedActiveScanWidget() && hasMavlinkScanProvider();
    if (!shouldRun) {
        if (liveScanWidgetPollTimer) {
            clearInterval(liveScanWidgetPollTimer);
            liveScanWidgetPollTimer = null;
        }
        const apiStop = getMavlinkScanApi();
        if (apiStop && typeof apiStop.stopScan === "function") {
            apiStop.stopScan().catch(() => { /* ignore */ });
        }
        liveScanWidgetLastAutoKickMs = 0;
        liveScanWidgetNextStatusPollAtMs = 0;
        return;
    }
    if (liveScanWidgetPollTimer) return;
    liveScanWidgetPollTimer = setInterval(async () => {
        if (liveScanWidgetPollBusy) return;
        liveScanWidgetPollBusy = true;
        try {
            const api = getMavlinkScanApi();
            if (api && typeof api.refreshStatus === "function") {
                const now = Date.now();
                const everyMs = getScanWidgetsAutoRefreshMs();
                let st = typeof api.getState === "function" ? api.getState() : null;
                const phase = String(st?.phase || "");
                const needStatusPoll = now >= liveScanWidgetNextStatusPollAtMs || phase === "running";
                if (needStatusPoll) {
                    await api.refreshStatus();
                    st = typeof api.getState === "function" ? api.getState() : null;
                    const phasePolled = String(st?.phase || "");
                    const statusCadenceMs = phasePolled === "running" ? 1000 : Math.max(2000, Math.min(everyMs, 10000));
                    liveScanWidgetNextStatusPollAtMs = now + statusCadenceMs;
                }
                const nowKick = Date.now();
                const due = liveScanWidgetLastAutoKickMs <= 0 || (nowKick - liveScanWidgetLastAutoKickMs) >= everyMs;
                if (due) {
                    const durationSec = Math.max(1, Math.round(everyMs / 1000));
                    const phaseKick = String(st?.phase || "");
                    if (!st || phaseKick === "idle" || phaseKick === "ready") {
                        if (!st || !st.hasResult) {
                            if (typeof api.startScan === "function") await api.startScan({ durationSec, keepLastResult: true });
                        } else if (typeof api.rescan === "function") {
                            await api.rescan({ durationSec, keepLastResult: true });
                        }
                        liveScanWidgetLastAutoKickMs = nowKick;
                        liveScanWidgetNextStatusPollAtMs = nowKick + 1000;
                    }
                }
            }
            schedulePlotRender();
        } catch {
            /* ignore polling errors */
        } finally {
            liveScanWidgetPollBusy = false;
        }
    }, 1000);
}
function scanWidgetViewForGid(gid) {
    const v = String(graphScanWidgetViewByGid[gid] || "summary");
    if (v === "variables_table" || v === "hist" || v === "fft") return v;
    return "summary";
}
function scanWidgetPresetMsForGid(gid) {
    const ms = Number(graphScanWidgetTimePresetByGid[gid]);
    if (ms === 1000 || ms === 5000 || ms === 10000 || ms === 30000 || ms === 60000 || ms === 300000) return ms;
    return 10000;
}
function isArincRegistryMode() { return appMode === "arinc_registry"; }
function isPluginAppMode() {
    return hasRegisteredAppMode(appMode);
}
/** Modo análisis o replay: sin conexión en vivo, se usa grabación y controles de reproducción */
function isPlaybackMode() { return isOfflineMode() || isReplayMode(); }

