const _MODE_ICONS = {
    live: "◎",
    offline: "▤",
    replay: "▶",
    arinc_registry: "✈",
    file_edit: "✎",
    git_workspace: "⎇",
    terminal: "⌘",
    flight_viz: "⌖",
};

function _modeIconFor(id) {
    return _MODE_ICONS[id] || "◆";
}

function _labelForModeId(id, tr) {
    if (id === "live") return tr.modeLive || "Live";
    if (id === "offline") return tr.modeOffline || "Análisis";
    if (id === "replay") return tr.modeReplay || "Replay";
    if (id === "arinc_registry") return tr.modeArincRegistry || "BD protocolos";
    const meta = getRegisteredAppModeMeta(id);
    if (meta && meta.labelKey && tr[meta.labelKey]) return tr[meta.labelKey];
    return (meta && meta.labelFallback) || id;
}

function _modeDescFor(id, tr) {
    const keyMap = {
        live: "modeDescLive",
        offline: "modeDescOffline",
        replay: "modeDescReplay",
        arinc_registry: "modeDescArincRegistry",
        file_edit: "modeDescFileEdit",
        git_workspace: "modeDescGitWorkspace",
        terminal: "modeDescTerminal",
        flight_viz: "modeDescFlightViz",
    };
    const key = keyMap[id];
    if (key && typeof tr[key] === "string" && tr[key].length) return tr[key];
    const fb = tr.modeDescPluginFallback || "Modo «%s».";
    return fb.replace("%s", _labelForModeId(id, tr));
}

function updateModeMenuButtonTitle() {
    if (!modeMenuBtn) return;
    const tr = I18N[currentLang] || I18N.es;
    const cur = _labelForModeId(appMode, tr);
    modeMenuBtn.title = `${tr.modeMenuHint || "Modo actual"}: ${cur}`;
    modeMenuBtn.setAttribute("aria-label", `${tr.modeMenuButton || "Modo"}: ${cur}`);
    if (modeCurrentLabel) {
        modeCurrentLabel.textContent = cur;
        modeCurrentLabel.title = cur;
    }
}

function renderModePickerButtons() {
    if (!modePickerGrid) return;
    const tr = I18N[currentLang] || I18N.es;
    modePickerGrid.replaceChildren();
    const ids = ["live", "offline", ...getRegisteredAppModeIds()];
    for (const id of ids) {
        const btn = document.createElement("button");
        btn.type = "button";
        btn.className = "mode-picker-card";
        btn.dataset.modeId = id;
        if (id === appMode) btn.classList.add("mode-picker-card--active");
        const icon = document.createElement("span");
        icon.className = "mode-picker-card-icon";
        icon.setAttribute("aria-hidden", "true");
        icon.textContent = _modeIconFor(id);
        const lab = document.createElement("span");
        lab.className = "mode-picker-card-label";
        lab.textContent = _labelForModeId(id, tr);
        const desc = document.createElement("span");
        desc.className = "mode-picker-card-desc";
        desc.textContent = _modeDescFor(id, tr);
        btn.appendChild(icon);
        btn.appendChild(lab);
        btn.appendChild(desc);
        btn.addEventListener("click", () => {
            void trySwitchModeFromPicker(id);
        });
        modePickerGrid.appendChild(btn);
    }
}

function closeModePicker() {
    if (_modePickerKeyHandler) {
        document.removeEventListener("keydown", _modePickerKeyHandler);
        _modePickerKeyHandler = null;
    }
    if (modePickerOverlay) {
        modePickerOverlay.style.display = "none";
        modePickerOverlay.setAttribute("aria-hidden", "true");
    }
    if (modeMenuBtn) modeMenuBtn.focus();
    if (_welcomeFirstSessionActive) {
        _welcomeFirstSessionActive = false;
        try {
            localStorage.setItem(FIRST_RUN_MODE_KEY, "1");
        } catch (e) { /* ignore */ }
    }
}

function openModePicker() {
    renderModePickerButtons();
    if (modePickerOverlay) {
        modePickerOverlay.style.display = "flex";
        modePickerOverlay.setAttribute("aria-hidden", "false");
    }
    _modePickerKeyHandler = (e) => {
        if (e.key !== "Escape") return;
        const sens = document.getElementById("sensitiveAuthOverlay");
        const glob = document.getElementById("authOverlay");
        if (sens && window.getComputedStyle(sens).display !== "none") return;
        if (glob && window.getComputedStyle(glob).display !== "none") return;
        closeModePicker();
    };
    document.addEventListener("keydown", _modePickerKeyHandler);
    if (modePickerCloseBtn) modePickerCloseBtn.focus();
}

async function trySwitchModeFromPicker(nextMode) {
    let next;
    if (nextMode === "live") next = "live";
    else if (nextMode === "offline") next = "offline";
    else if (hasRegisteredAppMode(nextMode)) next = nextMode;
    else return;
    if (next === "arinc_registry" || next === "file_edit" || next === "git_workspace") {
        const ok = await ensureSensitiveAuth();
        if (!ok) return;
    }
    const wantLiveDrawer = _welcomeFirstSessionActive && next === "live";
    closeModePicker();
    setAppMode(next);
    if (wantLiveDrawer) {
        queueMicrotask(() => openVarDrawer());
    }
    if (next === "offline") {
        await refreshServerRecordings();
    }
}

