async function refreshAuthStatus() {
    try {
        const r = await fetch("/api/auth_status");
        if (r.ok) authStatus = await r.json();
    } catch (e) {
        /* ignore */
    }
}

async function tryValidateSensitivePassword(pwd) {
    const prev = sessionStorage.getItem("varmon_sensitive_password");
    sessionStorage.setItem("varmon_sensitive_password", String(pwd || "").trim());
    try {
        const r = await fetch("/api/browse?path=");
        if (r.status === 401) {
            if (prev) sessionStorage.setItem("varmon_sensitive_password", prev);
            else sessionStorage.removeItem("varmon_sensitive_password");
            return false;
        }
        return true;
    } catch (e) {
        if (prev) sessionStorage.setItem("varmon_sensitive_password", prev);
        else sessionStorage.removeItem("varmon_sensitive_password");
        return false;
    }
}

function showSensitiveAuthModalPromise() {
    return new Promise((resolve) => {
        const ov = document.getElementById("sensitiveAuthOverlay");
        const inp = document.getElementById("sensitivePasswordInput");
        const btn = document.getElementById("sensitiveAuthSubmitBtn");
        const cancel = document.getElementById("sensitiveAuthCancelBtn");
        if (!ov || !inp || !btn) {
            resolve(false);
            return;
        }
        inp.value = "";
        ov.style.display = "flex";
        const cleanup = () => {
            ov.style.display = "none";
            btn.removeEventListener("click", onOk);
            if (cancel) cancel.removeEventListener("click", onCancel);
            inp.removeEventListener("keydown", onKey);
        };
        const onOk = async () => {
            const ok = await tryValidateSensitivePassword(inp.value);
            if (!ok) {
                inp.select();
                return;
            }
            cleanup();
            resolve(true);
        };
        const onCancel = () => {
            cleanup();
            resolve(false);
        };
        const onKey = (e) => {
            if (e.key === "Enter") void onOk();
        };
        btn.addEventListener("click", onOk);
        if (cancel) cancel.addEventListener("click", onCancel);
        inp.addEventListener("keydown", onKey);
        inp.focus();
    });
}

async function probeBrowseAuthorized() {
    try {
        const r = await fetch("/api/browse?path=");
        return r.status !== 401;
    } catch (e) {
        return false;
    }
}

/**
 * Credenciales para rutas sensibles (/api/browse, editor, etc.):
 * contraseña de ingeniería y/o global según varmon.conf (auth-fetch añade cabeceras).
 */
async function ensureSensitiveAuth() {
    await refreshAuthStatus();
    const needSens = !!authStatus.sensitive_modes_required;
    const needGlob = !!authStatus.auth_required;
    if (!needSens && !needGlob) return true;
    for (;;) {
        if (needSens && !sessionStorage.getItem("varmon_sensitive_password")) {
            if (!(await showSensitiveAuthModalPromise())) return false;
        }
        if (needGlob && !sessionStorage.getItem("varmon_password")) {
            if (!(await showGlobalAuthModalPromise())) return false;
        }
        if (await probeBrowseAuthorized()) return true;
        if (needSens) sessionStorage.removeItem("varmon_sensitive_password");
        if (needGlob) sessionStorage.removeItem("varmon_password");
    }
}

function showGlobalAuthModalPromise() {
    return new Promise((resolve) => {
        _pendingBrowseAuthResolve = resolve;
        const authPrompt = document.getElementById("authPrompt");
        const tr = I18N[currentLang] || I18N.es;
        if (authPrompt) authPrompt.textContent = tr.authBrowsePrompt || tr.authPrompt;
        showAuthModal();
    });
}

