async function restoreLiveReplayEmbedFromConfig(cfg) {
    const rec = (cfg && cfg.liveReplayEmbedRecordingName ? String(cfg.liveReplayEmbedRecordingName) : "").trim();
    if (!rec) return;
    try {
        const ds = await fetchRecordingDatasetForLiveEmbed(rec);
        if (!ds) return;
        assignLiveReplayEmbedDataset(ds, rec);
        if (Array.isArray(cfg.liveReplayEmbedImposeNames)) {
            liveReplayEmbedImposeNames = new Set(cfg.liveReplayEmbedImposeNames);
        }
        if (typeof cfg.liveReplayEmbedLoopAtEnd === "boolean") {
            liveReplayEmbedLoopAtEnd = cfg.liveReplayEmbedLoopAtEnd;
        }
        if (cfg.liveReplayRefAlarmDefaults && typeof cfg.liveReplayRefAlarmDefaults === "object") {
            const p = cfg.liveReplayRefAlarmDefaults;
            liveReplayRefAlarmDefaults = {
                tol: Number.isFinite(Number(p.tol)) ? Number(p.tol) : 1,
                hys: Number.isFinite(Number(p.hys)) ? Math.max(0, Number(p.hys)) : 0,
                delayMs: Number.isFinite(Number(p.delayMs)) ? Math.max(0, Math.floor(Number(p.delayMs))) : 0,
            };
        }
        notifyLiveReplayEmbedUi();
        sendAlarmsToBackend();
    } catch (e) {
        console.warn("[VarMonitor] restoreLiveReplayEmbedFromConfig:", e);
    }
}

function getLiveReplayEmbedHooks() {
    return {
        getState: () => getLiveReplayEmbedUiState(),
        subscribe: (cb) => {
            liveReplayEmbedUiSubscribers.add(cb);
            return () => liveReplayEmbedUiSubscribers.delete(cb);
        },
        togglePlay: () => {
            if (!liveReplayEmbedDataset) return;
            if (liveReplayEmbedPlayback.isPlaying) {
                stopLiveReplayEmbedPlayback();
                notifyLiveReplayEmbedUi();
                return;
            }
            startLiveReplayEmbedPlayback();
            notifyLiveReplayEmbedUi();
        },
        seekRatio: (ratio01) => {
            if (!liveReplayEmbedDataset) return;
            const ds = liveReplayEmbedDataset;
            const t = ds.minTs + ratio01 * (ds.maxTs - ds.minTs);
            liveReplayEmbedPlayback.currentTs = t;
            applyLiveEmbedShmInjectionsBatch(t);
            notifyLiveReplayEmbedUi();
        },
        setSpeed: (sp) => {
            liveReplayEmbedPlayback.speed = Number.isFinite(sp) && sp > 0 ? sp : 1;
            notifyLiveReplayEmbedUi();
        },
        setLoopAtEnd: (on) => setLiveReplayEmbedLoopAtEnd(on),
        setInitConditions: () => {},
        toggleImposeName: (name, checked) => toggleLiveReplayImposeName(name, checked),
        openVarsModal: () => {},
        openSourceModal: () => openLiveReplayMonitorModal(),
        openReplayAliasModal: () => openLiveReplayAliasModal(),
        setPlotVsRef: (on) => {
            plotVsRef = !!on;
            const cb = document.getElementById("plotVsRefCheckbox");
            if (cb) cb.checked = plotVsRef;
            saveConfig();
            schedulePlotRender();
        },
        getPlotVsRef: () => !!plotVsRef,
        getReplayFileColumnForCanonical: (canonicalName) =>
            getReplayFileColumnForCanonicalInDataset(liveReplayEmbedDataset, canonicalName),
        toggleReplayRefAlarm: (name, checked) => toggleLiveReplayRefAlarm(name, checked),
        hasReplayRefAlarm: (name) => hasLiveReplayRefAlarm(name),
        setReplayRefAlarmDefaults: (partial) => setLiveReplayRefAlarmDefaults(partial),
        openReferenceDataModal: () => openLiveReplayReferenceDataModal(),
    };
}

function mountLiveReplayMonitorPanel(containerEl, options) {
    return mountLiveReplayEmbedUi(containerEl, getLiveReplayEmbedHooks(), {
        ...options,
        hideSourceButton: true,
        modalLayout: true,
    });
}

/** Nombre SHM espejo de la referencia TSV (debe coincidir con backend). */
function defaultReplayRefShmName(name) {
    const safe = String(name || "").replace(/[^a-zA-Z0-9._]/g, "_").slice(0, 100);
    return "__vm_ref__" + (safe || "x");
}

/** Valor «live» para inyección SHM (misma lógica que imposición). */
function getReplayAlarmLiveValueForShm(name, ts) {
    if (impositionNames.has(name)) {
        const dt = Number(impositionTimeOffset[name]);
        const dv = Number(impositionValueOffset[name]);
        const tImpose = ts + (Number.isFinite(dt) ? dt : 0);
        const baseVal = getReplayImposedValueAtTs(name, tImpose);
        if (baseVal == null) return null;
        return baseVal + (Number.isFinite(dv) ? dv : 0);
    }
    return getReplayImposedValueAtTs(name, ts);
}

/**
 * Un solo mensaje WS `set_vars`: escribe solo filas IMPORT en mmap (MODE_IMPORT_SNAPSHOT); libvarmonitor aplica en el siguiente ciclo.
 * Imposiciones + sombras ref; sin UDS set_var.
 */
function applyReplayShmInjectionsBatch(currentTs) {
    if (!isReplayMode() || !offlineDataset || !Number.isFinite(currentTs)) return;
    if (!offlinePlayback.isPlaying) return;
    if (!ws || ws.readyState !== WebSocket.OPEN) return;
    const rows = [];
    if (impositionNames.size > 0) {
        impositionNames.forEach((name) => {
            if (!isVarInTsv(name)) return;
            const dt = Number(impositionTimeOffset[name]);
            const dv = Number(impositionValueOffset[name]);
            const tImpose = currentTs + (Number.isFinite(dt) ? dt : 0);
            const baseVal = getReplayImposedValueAtTs(name, tImpose);
            if (baseVal == null) return;
            const vd = varsByName[name];
            const varType = vd
                ? (vd.type === "int32" ? "int32" : vd.type === "bool" ? "bool" : "double")
                : "double";
            let sendVal = baseVal + (Number.isFinite(dv) ? dv : 0);
            if (varType === "bool") sendVal = sendVal ? 1 : 0;
            else if (varType === "int32") sendVal = (Math.trunc(sendVal) | 0);
            rows.push({ name, value: sendVal, var_type: varType });
        });
    }
    for (const name of Object.keys(alarms)) {
        const a = alarms[name];
        if (!a || !a.compareToRef) continue;
        const refName = a.refName || defaultReplayRefShmName(name);
        const refVal = getReplayImposedValueAtTs(name, currentTs);
        if (refVal == null || !Number.isFinite(Number(refVal))) continue;
        rows.push({ name: refName, value: Number(refVal), var_type: "double" });
        const liveVal = getReplayAlarmLiveValueForShm(name, currentTs);
        if (liveVal == null || !Number.isFinite(Number(liveVal))) continue;
        const vd = varsByName[name];
        const varType = vd
            ? (vd.type === "int32" ? "int32" : vd.type === "bool" ? "bool" : "double")
            : "double";
        let sendVal = Number(liveVal);
        if (varType === "bool") sendVal = sendVal ? 1 : 0;
        else if (varType === "int32") sendVal = (Math.trunc(sendVal) | 0);
        rows.push({ name, value: sendVal, var_type: varType });
    }
    if (rows.length === 0) return;
    sendWsAction({ action: "set_vars", vars: rows });
}

function syncReplayTsvHistoryForName(name) {
    if (!isReplayMode() || !name || !isVarInTsv(name) || isArrayVar(name)) return;
    if (impositionNames.has(name)) {
        const series = getRefSeriesFromOfflineDataset(name);
        if (series && Array.isArray(series.timestamps) && Array.isArray(series.values)) {
            historyCache[name] = {
                timestamps: series.timestamps.slice(),
                values: series.values.slice(),
            };
            fullHistoryByName[name] = {
                timestamps: series.timestamps.slice(),
                values: series.values.slice(),
            };
        }
    } else {
        delete historyCache[name];
        delete fullHistoryByName[name];
    }
}

/** Serie de referencia desde el TSV (solo replay); para plotVsRef con etiqueta _ref. */
function getRefSeriesFromOfflineDataset(name) {
    if (!offlineDataset || !Array.isArray(offlineDataset.samples) || offlineDataset.samples.length === 0) return null;
    const isArrElem = name.includes("[") && name.endsWith("]");
    let base, idx;
    if (isArrElem) {
        const br = name.lastIndexOf("[");
        base = name.substring(0, br);
        idx = parseInt(name.substring(br + 1), 10);
        if (!Number.isFinite(idx)) return null;
    }
    const timestamps = [];
    const values = [];
    for (let i = 0; i < offlineDataset.samples.length; i++) {
        const s = offlineDataset.samples[i];
        if (!s || !Array.isArray(s.data)) continue;
        let v = null;
        if (isArrElem) {
            const e = s.data.find((it) => it && it.name === base && Array.isArray(it.value));
            if (e && idx >= 0 && idx < e.value.length) v = e.value[idx];
        } else {
            const e = s.data.find((it) => it && it.name === name);
            if (e) v = e.value;
        }
        if (v !== null && v !== undefined) {
            timestamps.push(Number(s.ts));
            values.push(typeof v === "number" ? v : Number(v));
        }
    }
    if (timestamps.length === 0) return null;
    return { timestamps, values };
}

/** Serie de referencia desde el TSV del replay en vivo (misma forma que offline). */
function getRefSeriesFromLiveReplayEmbedDataset(name) {
    const ds = liveReplayEmbedDataset;
    if (!ds || !Array.isArray(ds.samples) || ds.samples.length === 0) return null;
    const isArrElem = name.includes("[") && name.endsWith("]");
    let base;
    let idx;
    if (isArrElem) {
        const br = name.lastIndexOf("[");
        base = name.substring(0, br);
        idx = parseInt(name.substring(br + 1), 10);
        if (!Number.isFinite(idx)) return null;
    }
    const timestamps = [];
    const values = [];
    for (let i = 0; i < ds.samples.length; i++) {
        const s = ds.samples[i];
        if (!s || !Array.isArray(s.data)) continue;
        let v = null;
        if (isArrElem) {
            const e = s.data.find((it) => it && it.name === base && Array.isArray(it.value));
            if (e && idx >= 0 && idx < e.value.length) v = e.value[idx];
        } else {
            const e = s.data.find((it) => it && it.name === name);
            if (e) v = e.value;
        }
        if (v !== null && v !== undefined) {
            timestamps.push(Number(s.ts));
            values.push(typeof v === "number" ? v : Number(v));
        }
    }
    if (timestamps.length === 0) return null;
    return { timestamps, values };
}

function getReplayFileColumnForCanonicalInDataset(ds, canonicalName) {
    if (!ds || !Array.isArray(ds.samples) || ds.samples.length === 0 || !canonicalName) return canonicalName;
    const s0 = ds.samples[0];
    if (!s0 || !Array.isArray(s0.data)) return canonicalName;
    const e = s0.data.find((it) => it && it.name === canonicalName);
    if (e && typeof e._replaySourceName === "string" && e._replaySourceName) return e._replaySourceName;
    return canonicalName;
}

function getValueAtTs(hist, ts) {
    if (!hist || !hist.timestamps || hist.timestamps.length === 0 || !Number.isFinite(ts)) return null;
    const xs = hist.timestamps;
    let lo = 0, hi = xs.length - 1, ans = 0;
    while (lo <= hi) {
        const mid = (lo + hi) >> 1;
        if (xs[mid] <= ts) { ans = mid; lo = mid + 1; }
        else hi = mid - 1;
    }
    const v = hist.values[ans];
    return Number.isFinite(v) ? v : null;
}

function getOfflineScalarValueAtTs(name, ts) {
    if (!offlineDataset || !Array.isArray(offlineDataset.samples) || offlineDataset.samples.length === 0) return null;
    if (!name || !Number.isFinite(ts)) return null;
    const idx = binarySearchSampleIndex(offlineDataset.samples, ts);
    const s = offlineDataset.samples[idx];
    if (!s || !Array.isArray(s.data)) return null;
    const e = s.data.find((it) => it && it.name === name && !Array.isArray(it.value));
    if (!e) return null;
    const n = (typeof e.value === "number") ? e.value : Number(e.value);
    return Number.isFinite(n) ? n : null;
}

function recomputeDeltaByName() {
    deltaByName = {};
    if (!Number.isFinite(markerA) || !Number.isFinite(markerB)) return;
    for (const name of monitoredNames) {
        if (isArrayVar(name)) continue;
        const hist = historyCache[name];
        let vA = getValueAtTs(hist, markerA);
        let vB = getValueAtTs(hist, markerB);
        if (isPlaybackMode() && (vA == null || vB == null)) {
            if (vA == null) vA = getOfflineScalarValueAtTs(name, markerA);
            if (vB == null) vB = getOfflineScalarValueAtTs(name, markerB);
        }
        if (vA == null || vB == null) continue;
        deltaByName[name] = vB - vA;
    }
    if (monitoredOrder.length > 1) {
        monitoredOrder.sort((a, b) => {
            const da = Number.isFinite(deltaByName[a]) ? Math.abs(deltaByName[a]) : 0;
            const db = Number.isFinite(deltaByName[b]) ? Math.abs(deltaByName[b]) : 0;
            const aChanged = da > 1e-9;
            const bChanged = db > 1e-9;
            if (aChanged && !bChanged) return -1;
            if (!aChanged && bChanged) return 1;
            if (aChanged && bChanged && db !== da) return db - da;
            return 0;
        });
    }
}

function renderAnomalyList() {
    if (!anomalyListEl) return;
    anomalyListEl.innerHTML = "";
    if (!anomalyResults.length) {
        const empty = document.createElement("div");
        empty.className = "stats-empty";
        empty.textContent = "Sin anomalías detectadas";
        anomalyListEl.appendChild(empty);
        return;
    }
    const maxRows = 150;
    const rows = anomalyResults.slice(0, maxRows);
    for (let i = 0; i < rows.length; i++) {
        const a = rows[i];
        const row = document.createElement("div");
        row.className = "anomaly-item";
        const txt = document.createElement("span");
        const relTs = (offlineDataset && Number.isFinite(offlineDataset.minTs))
            ? Math.max(0, a.ts - offlineDataset.minTs)
            : a.ts;
        const typeLabel = a.type === "lo_cross"
            ? "Lo-cross"
            : a.type === "hi_cross"
                ? "Hi-cross"
                : a.type;
        txt.textContent = `${relTs.toFixed(3)}s | ${a.name} | ${typeLabel} | ${a.detail}`;
        const go = document.createElement("button");
        go.className = "btn-small";
        go.textContent = "Ir";
        go.addEventListener("click", () => {
            applyOfflineTime(a.ts);
            schedulePlotRender();
        });
        row.appendChild(txt);
        row.appendChild(go);
        anomalyListEl.appendChild(row);
    }
}

function runAnomalyScan() {
    if (!hasPlugin("anomaly")) return;
    anomalyResults = [];
    if (!offlineDataset) {
        renderAnomalyList();
        return;
    }
    const jumpThr = Math.max(0, Number(anomalyJumpInput?.value) || 1.0);
    const globalLo = anomalyLoInput && anomalyLoInput.value !== "" ? Number(anomalyLoInput.value) : null;
    const globalHi = anomalyHiInput && anomalyHiInput.value !== "" ? Number(anomalyHiInput.value) : null;
    const plottedSet = new Set();
    migratePlotPaneStateIfNeeded();
    for (const pid of getLivePlotLeafIds()) {
        const st = getPlotPaneState(pid);
        for (const gid of st.graphList) {
            const varsInGraph = getVarsForGraphInPane(gid, pid);
            for (let vi = 0; vi < varsInGraph.length; vi++) plottedSet.add(varsInGraph[vi]);
        }
    }
    const names = Array.from(plottedSet);
    if (names.length === 0) {
        renderAnomalyList();
        return;
    }
    if (window.Worker) {
        try {
            const payload = [];
            for (let i = 0; i < names.length; i++) {
                const n = names[i];
                const h = isArrayElem(n) ? arrayElemHistory[n] : historyCache[n];
                if (!h || !h.timestamps || !h.values) continue;
                payload.push({ name: n, timestamps: h.timestamps, values: h.values });
            }
            const workerSrc = `
                self.onmessage = (ev) => {
                  const { series, jumpThr, lo, hi } = ev.data;
                  const out = [];
                  for (const s of series) {
                    const xs = s.timestamps || [];
                    const ys = s.values || [];
                    for (let i = 1; i < ys.length; i++) {
                      const d = ys[i] - ys[i - 1];
                      if (Math.abs(d) >= jumpThr) out.push({ ts: xs[i], name: s.name, type: "jump", detail: "Δ=" + d.toFixed(4) });
                      if (lo != null && ys[i - 1] > lo && ys[i] <= lo) out.push({ ts: xs[i], name: s.name, type: "lo_cross", detail: "v=" + ys[i].toFixed(4) });
                      if (hi != null && ys[i - 1] < hi && ys[i] >= hi) out.push({ ts: xs[i], name: s.name, type: "hi_cross", detail: "v=" + ys[i].toFixed(4) });
                    }
                  }
                  out.sort((a,b)=>a.ts-b.ts);
                  self.postMessage(out);
                };`;
            const worker = new Worker(URL.createObjectURL(new Blob([workerSrc], { type: "application/javascript" })));
            worker.onmessage = (ev) => {
                anomalyResults = Array.isArray(ev.data) ? ev.data : [];
                eventCursorIndex = anomalyResults.length > 0 ? 0 : -1;
                renderAnomalyList();
                renderArincBusHealth();
                worker.terminate();
            };
            worker.postMessage({
                series: payload,
                jumpThr: Math.max(0, Number(anomalyJumpInput?.value) || 1.0),
                lo: anomalyLoInput && anomalyLoInput.value !== "" ? Number(anomalyLoInput.value) : null,
                hi: anomalyHiInput && anomalyHiInput.value !== "" ? Number(anomalyHiInput.value) : null,
            });
            return;
        } catch (e) {
            // Fallback a ejecución local.
        }
    }
    const plottedScalarNames = new Set();
    const plottedArrayElems = [];
    for (let i = 0; i < names.length; i++) {
        const n = names[i];
        if (isArrayElem(n)) {
            const br = n.lastIndexOf("[");
            const base = n.slice(0, br);
            const idx = parseInt(n.slice(br + 1, -1), 10);
            if (Number.isFinite(idx)) plottedArrayElems.push({ name: n, base, idx });
        } else {
            plottedScalarNames.add(n);
        }
    }
    for (let ni = 0; ni < names.length; ni++) {
        const name = names[ni];
        const hist = isArrayElem(name) ? arrayElemHistory[name] : historyCache[name];
        if (!hist || !hist.values || hist.values.length < 2) continue;
        const xs = hist.timestamps;
        const ys = hist.values;
        for (let i = 1; i < ys.length; i++) {
            const d = ys[i] - ys[i - 1];
            if (Math.abs(d) >= jumpThr) {
                anomalyResults.push({ ts: xs[i], name, type: "jump", detail: `Δ=${d.toFixed(4)}` });
            }
        }
        if ((globalLo != null && Number.isFinite(globalLo)) || (globalHi != null && Number.isFinite(globalHi))) {
            for (let i = 1; i < ys.length; i++) {
                const prev = ys[i - 1];
                const curr = ys[i];
                const crossLo = (globalLo != null && Number.isFinite(globalLo) && prev > globalLo && curr <= globalLo);
                const crossHi = (globalHi != null && Number.isFinite(globalHi) && prev < globalHi && curr >= globalHi);
                if (crossLo) anomalyResults.push({ ts: xs[i], name, type: "lo_cross", detail: `v=${curr.toFixed(4)}` });
                if (crossHi) anomalyResults.push({ ts: xs[i], name, type: "hi_cross", detail: `v=${curr.toFixed(4)}` });
            }
        }
    }
    // Detección NaN/inf directamente de muestras A (por si en history fueron filtradas).
    for (let si = 0; si < offlineDataset.samples.length; si++) {
        const s = offlineDataset.samples[si];
        for (let j = 0; j < s.data.length; j++) {
            const e = s.data[j];
            if (!Array.isArray(e.value)) {
                if (!plottedScalarNames.has(e.name)) continue;
                if (typeof e.value === "number" && !Number.isFinite(e.value)) {
                    anomalyResults.push({ ts: s.ts, name: e.name, type: "nan_inf", detail: String(e.value) });
                }
                continue;
            }
            for (let ai = 0; ai < plottedArrayElems.length; ai++) {
                const it = plottedArrayElems[ai];
                if (it.base !== e.name) continue;
                const v = e.value[it.idx];
                if (typeof v === "number" && !Number.isFinite(v)) {
                    anomalyResults.push({ ts: s.ts, name: it.name, type: "nan_inf", detail: String(v) });
                }
            }
        }
    }
    anomalyResults.sort((a, b) => a.ts - b.ts);
    eventCursorIndex = anomalyResults.length > 0 ? 0 : -1;
    renderAnomalyList();
    renderArincBusHealth();
}

function startOfflinePlayback() {
    if (!offlineDataset || offlineDataset.samples.length === 0 || !isPlaybackMode()) return;
    if (offlinePlayback.isPlaying) return;
    // Si estamos al final del tramo actual, solo entonces reiniciamos al inicio
    // de este tramo. Si no, respetamos la posición actual (por ejemplo, al
    // cambiar de tramo en análisis de grabaciones grandes).
    const minTs = Number.isFinite(offlineRecordingGlobalMinTs) ? offlineRecordingGlobalMinTs : offlineDataset.minTs;
    const maxTs = Number.isFinite(offlineRecordingGlobalMaxTs) ? offlineRecordingGlobalMaxTs : offlineDataset.maxTs;
    if (!Number.isFinite(offlinePlayback.currentTs) ||
        offlinePlayback.currentTs >= (maxTs - 1e-9)) {
        // Nuevo ciclo de play en replay: reiniciar todo el histórico runtime
        // para evitar arrastre visual entre ciclos.
        if (isReplayMode()) {
            for (const name of Object.keys(historyCache)) {
                historyCache[name] = { timestamps: [], values: [] };
            }
            for (const key of Object.keys(arrayElemHistory)) {
                arrayElemHistory[key] = { timestamps: [], values: [] };
            }
            for (const cv of computedVars) {
                if (computedHistories[cv.name]) {
                    computedHistories[cv.name] = { timestamps: [], values: [] };
                }
            }
        }
        applyOfflineTime(minTs);
        schedulePlotRender();
    }
    offlinePlayback.isPlaying = true;
    offlinePlayback.lastTickMs = Date.now();
    if (isReplayMode()) syncReplayAlarmEngagedToBackend();
    const tr = I18N[currentLang] || I18N.es;
    if (offlinePlayPauseBtn) offlinePlayPauseBtn.textContent = tr.offlinePlaybackPause || "⏸ Pause";
    offlinePlayback.timer = setInterval(() => {
        if (!offlinePlayback.isPlaying || !offlineDataset) return;
        const now = Date.now();
        const dt = (now - offlinePlayback.lastTickMs) / 1000;
        offlinePlayback.lastTickMs = now;
        const nextTs = offlinePlayback.currentTs + dt * (offlinePlayback.speed || 1);
        const maxTs = Number.isFinite(offlineRecordingGlobalMaxTs) ? offlineRecordingGlobalMaxTs : offlineDataset.maxTs;
        if (nextTs >= maxTs) {
            applyOfflineTime(maxTs);
            schedulePlotRender();
            stopOfflinePlayback();
            // Al terminar no forzamos volver al inicio automáticamente, para
            // que el usuario pueda seguir navegando entre tramos sin que el
            // eje X se reseteé.
            return;
        }
        applyOfflineTime(nextTs);
        schedulePlotRender();
    }, 40);
}

function shouldUseSafeOfflineLoad(sizeBytes) {
    const mb = Number(sizeBytes) / (1024 * 1024);
    return Number.isFinite(mb) && mb > offlineFullLoadMaxMb;
}

function shouldUseSafeParquetLoad(meta, sizeBytes) {
    const rows = Number(meta && meta.rows);
    const cols = Number(meta && meta.columns);
    if (Number.isFinite(rows) && rows > 0 && Number.isFinite(cols) && cols > 0) {
        const cells = rows * cols;
        const limitCells = Math.max(500000, (Number(offlineSafePreviewMaxRows) || 10000) * 300);
        if (!shouldUseSafeOfflineLoad(sizeBytes) && cells <= limitCells) return false;
        return true;
    }
    return shouldUseSafeOfflineLoad(sizeBytes);
}

async function loadWholeParquetFromServer(filename, meta, opts = {}) {
    const rows = Number(meta && meta.rows);
    const rc = (Number.isFinite(rows) && rows > 0) ? Math.min(Math.floor(rows), 100000) : 20000;
    const r = await fetch(`/api/recordings/${encodeURIComponent(filename)}?preview_bytes=1&row_start=0&row_count=${Math.max(100, rc)}`);
    if (!r.ok) throw new Error("No se pudo descargar Parquet");
    const payload = await r.json();
    if (!payload || !payload.offline) throw new Error("Respuesta Parquet inválida");
    const ds = offlineDatasetFromParquetPayload(payload.offline, filename);
    await loadOfflineDataset(ds, { ...opts, recordingName: filename, safeInfo: null });
}

function shouldForceFullLoadWithConfirmation(label, sizeBytes, estRamBytes) {
    if (!offlineAllowForceFullLoad) return false;
    const tr = I18N[currentLang] || I18N.es;
    return window.confirm(
        `${tr.offlineDatasetSafeMode || "Modo seguro"} recomendado para ${label}.\n` +
        `Tamaño archivo: ${formatBytes(sizeBytes)}\n` +
        `RAM estimada en carga completa: ~${formatBytes(estRamBytes)}\n\n` +
        `¿Forzar carga completa igualmente?`
    );
}

async function loadLargeLocalFileInSafeMode(file) {
    const tr = I18N[currentLang] || I18N.es;
    const sizeBytes = Number(file && file.size) || 0;
    const previewBytes = Math.max(1, Math.floor(offlinePreviewMb * 1024 * 1024));
    const previewRaw = await file.slice(0, previewBytes).text();
    const previewText = trimTextToFullLines(previewRaw);
    const risk = estimateTsvLoadRisk(previewText, sizeBytes);
    const ds = parseTsvDataset(previewText, file.name, {
        isPreview: true,
        maxRows: offlineSafePreviewMaxRows,
        maxSpanSec: offlineSafePreviewMaxSpanSec,
    });
    const safeInfo = {
        safeMode: true,
        totalBytes: sizeBytes,
        estRamBytes: risk.estRamBytes,
        columns: risk.columns,
        estRows: risk.estRows,
        reason: "size",
    };
    alert(
        `${tr.offlineDatasetSafeMode || "Modo seguro"}: ${file.name}\n` +
        `Tamaño: ${formatBytes(sizeBytes)}\n` +
        `Estimación RAM carga completa: ~${formatBytes(risk.estRamBytes)}\n` +
        `Se carga solo un tramo inicial (${offlineSafePreviewMaxRows} filas máx / ${offlineSafePreviewMaxSpanSec}s).`
    );
    return { ds, safeInfo };
}

function isRecordingParquetFilename(fn) {
    return (fn || "").toLowerCase().endsWith(".parquet");
}

function offlineDatasetFromParquetPayload(offline, filename) {
    if (!offline || !Array.isArray(offline.samples)) throw new Error("Parquet offline inválido");
    return {
        sourceName: offline.sourceName || filename,
        samples: offline.samples,
        names: offline.names || [],
        minTs: offline.minTs,
        maxTs: offline.maxTs,
        isEpoch: !!offline.isEpoch,
        isPreview: !!offline.isPreview,
        truncated: !!offline.truncated,
    };
}

async function loadLocalParquetViaUpload(file) {
    const fd = new FormData();
    fd.append("file", file, file.name || "upload.parquet");
    const mr = Math.max(100, Math.min(Number(offlineSafePreviewMaxRows) || 10000, 100000));
    const r = await fetch(`/api/recordings/parquet_preview_upload?max_rows=${mr}`, { method: "POST", body: fd });
    const j = await r.json().catch(() => ({}));
    if (!r.ok) throw new Error(j.error || r.statusText || "Parquet upload falló");
    if (!j.offline) throw new Error("Respuesta sin datos offline");
    return offlineDatasetFromParquetPayload(j.offline, file.name || "dataset.parquet");
}

async function loadLargeServerFileInSafeMode(filename, sizeBytes, byteOffset = 0) {
    const tr = I18N[currentLang] || I18N.es;
    const previewBytes = Math.max(1, Math.floor(offlinePreviewMb * 1024 * 1024));

    if (isRecordingParquetFilename(filename)) {
        const rowStart = Math.max(0, Number(byteOffset) || 0);
        const rowCount = Math.max(100, Math.min(Number(offlineSafePreviewMaxRows) || 10000, 100000));
        const url = `/api/recordings/${encodeURIComponent(filename)}?preview_bytes=1&row_start=${rowStart}&row_count=${rowCount}`;
        const r = await fetch(url);
        if (!r.ok) throw new Error("No se pudo descargar preview de la grabación Parquet");
        const payload = await r.json();
        const offline = payload && payload.offline;
        if (!offline) throw new Error("Respuesta Parquet sin offline");
        const ds = offlineDatasetFromParquetPayload(offline, filename);
        const totalBytes = Number(sizeBytes) || Number(payload && payload.size) || 0;
        const totalRows = Number(payload.total_rows) || 0;
        const nextRow = Number(payload.segment_start) || 0;
        const cols = Array.isArray(ds.names) ? ds.names.length : 1;
        const estRamBytes = Math.max(1, totalRows) * Math.max(1, cols) * 48;
        const segmentSpanSec = Math.max(0, ds.maxTs - ds.minTs);
        const safeInfo = {
            safeMode: true,
            parquetMode: true,
            totalBytes,
            parquetTotalRows: totalRows,
            parquetNextRow: nextRow,
            parquetRowStart: rowStart,
            segmentStartByte: rowStart,
            segmentEndByte: nextRow,
            segmentSpanSec,
            estRamBytes,
            columns: cols,
            estRows: totalRows,
            reason: "size",
        };
        if (rowStart === 0) {
            offlineSegmentOffsetSec = 0;
            alert(
                `${tr.offlineDatasetSafeMode || "Modo seguro"}: ${filename} (Parquet)\n` +
                `Tamaño: ${formatBytes(safeInfo.totalBytes)}\n` +
                `Filas (aprox.): ${totalRows}\n` +
                `Estimación RAM carga completa: ~${formatBytes(estRamBytes)}\n` +
                `Se carga por tramos de hasta ${rowCount} filas.`
            );
        }
        return { ds, safeInfo };
    }

    const url = byteOffset > 0
        ? `/api/recordings/${encodeURIComponent(filename)}?preview_bytes=${previewBytes}&offset=${byteOffset}`
        : `/api/recordings/${encodeURIComponent(filename)}?preview_bytes=${previewBytes}`;
    const r = await fetch(url);
    if (!r.ok) throw new Error("No se pudo descargar preview de la grabación");
    const payload = await r.json();
    const previewText = trimTextToFullLines(payload && payload.preview ? payload.preview : "");
    const totalBytes = Number(sizeBytes) || Number(payload && payload.size) || 0;
    const risk = estimateTsvLoadRisk(previewText, totalBytes);
    const ds = parseTsvDataset(previewText, filename, {
        isPreview: true,
        maxRows: offlineSafePreviewMaxRows,
        maxSpanSec: offlineSafePreviewMaxSpanSec,
    });
    const segmentStart = Number(payload.segment_start) || 0;
    const segmentEnd = segmentStart + (Number(payload.preview_bytes) || 0);
    const segmentSpanSec = Math.max(0, ds.maxTs - ds.minTs);
    const safeInfo = {
        safeMode: true,
        parquetMode: false,
        totalBytes,
        segmentStartByte: segmentStart,
        segmentEndByte: segmentEnd,
        segmentSpanSec,
        estRamBytes: risk.estRamBytes,
        columns: risk.columns,
        estRows: risk.estRows,
        reason: "size",
    };
    if (byteOffset === 0) {
        offlineSegmentOffsetSec = 0;
        alert(
            `${tr.offlineDatasetSafeMode || "Modo seguro"}: ${filename}\n` +
            `Tamaño: ${formatBytes(safeInfo.totalBytes)}\n` +
            `Estimación RAM carga completa: ~${formatBytes(risk.estRamBytes)}\n` +
            `Se carga solo un tramo inicial (${offlineSafePreviewMaxRows} filas máx / ${offlineSafePreviewMaxSpanSec}s).`
        );
    }
    return { ds, safeInfo };
}

/** Fase 1: cargar otro tramo de la misma grabación (solo servidor, modo seguro). */
async function loadRecordingChunkAtOffset(byteOffset) {
    const filename = (offlineRecordingName || "").trim();
    if (!filename || !offlineSafetyInfo || !offlineSafetyInfo.safeMode) return;
    const totalBytes = offlineSafetyInfo.totalBytes || 0;
    if (offlineSafetyInfo.parquetMode) {
        const tr = Number(offlineSafetyInfo.parquetTotalRows) || 0;
        if (byteOffset < 0 || byteOffset >= tr) return;
    } else if (byteOffset < 0 || byteOffset >= totalBytes) {
        return;
    }
    beginOfflineDatasetLoad();
    try {
        // Cargar el tramo tal cual viene en el TSV: la columna time_s ya es
        // tiempo absoluto desde 0, no hay que aplicar offsets adicionales.
        // Solo usamos offlineRecordingGlobalMinTs como referencia de origen.
        const globalBaseTs = Number.isFinite(offlineRecordingGlobalMinTs)
            ? offlineRecordingGlobalMinTs
            : null;

        const safe = await loadLargeServerFileInSafeMode(filename, totalBytes, byteOffset);
        await loadOfflineDataset(safe.ds, { recordingName: filename, safeInfo: safe.safeInfo, preserveLayout: true });

        // Mantener la referencia global del primer tramo (suele ser 0s).
        if (globalBaseTs !== null && Number.isFinite(globalBaseTs)) {
            offlineRecordingGlobalMinTs = globalBaseTs;
        }

        // Seguimos actualizando la info de tramos solo para UI de botones,
        // pero sin tocar los timestamps reales.
        if (safe.safeInfo && Number.isFinite(safe.safeInfo.segmentSpanSec)) {
            const baseOffset = Number.isFinite(offlineSegmentOffsetSec) ? offlineSegmentOffsetSec : 0;
            offlineSegmentOffsetSec = baseOffset + safe.safeInfo.segmentSpanSec;
        }
        updateOfflineChunkButtons();
    } catch (e) {
        alert("Error cargando tramo: " + (e && e.message ? e.message : String(e)));
    } finally {
        endOfflineDatasetLoad();
    }
}

function updateOfflineChunkButtons() {
    const prevBtn = document.getElementById("offlineChunkPrevBtn");
    const nextBtn = document.getElementById("offlineChunkNextBtn");
    if (!prevBtn || !nextBtn) return;
    const canChunk = !!(offlineSafetyInfo && offlineSafetyInfo.safeMode && offlineRecordingName);
    prevBtn.style.display = canChunk ? "" : "none";
    nextBtn.style.display = canChunk ? "" : "none";
    if (!canChunk) return;
    if (offlineSafetyInfo.parquetMode) {
        const tr = Number(offlineSafetyInfo.parquetTotalRows) || 0;
        const next = Number(offlineSafetyInfo.parquetNextRow) || 0;
        prevBtn.disabled = true;
        nextBtn.disabled = next >= tr;
        return;
    }
    const start = offlineSafetyInfo.segmentStartByte || 0;
    const end = offlineSafetyInfo.segmentEndByte || 0;
    const total = offlineSafetyInfo.totalBytes || 0;
    prevBtn.disabled = start <= 0;
    nextBtn.disabled = end >= total;
}

async function refreshServerRecordings() {
    if (!recordingSelect) return;
    try {
        const resp = await fetch("/api/recordings?_=" + Date.now(), { cache: "no-store" });
        if (!resp.ok) throw new Error("no recordings");
        const data = await resp.json();
        let utPkgs = [];
        try {
            const ur = await fetch("/api/unitary_test?_=" + Date.now(), { cache: "no-store" });
            if (ur.ok) {
                const ud = await ur.json();
                utPkgs = Array.isArray(ud.packages) ? ud.packages : [];
            }
        } catch {
            utPkgs = [];
        }
        const tr = I18N[currentLang] || I18N.es;
        recordingSelect.innerHTML = "";
        recordingsMetaByName = new Map();
        const rows = Array.isArray(data.recordings) ? data.recordings : [];
        if (rows.length === 0 && utPkgs.length === 0) {
            const op = document.createElement("option");
            op.value = "";
            op.textContent = tr.offlineNoRecordings || "(sin grabaciones)";
            recordingSelect.appendChild(op);
            void refreshUnitaryTestSelect();
            return;
        }
        for (let i = 0; i < rows.length; i++) {
            const r = rows[i];
            const op = document.createElement("option");
            op.value = r.filename;
            op.textContent = r.filename;
            recordingSelect.appendChild(op);
            recordingsMetaByName.set(r.filename, r);
        }
        for (let j = 0; j < utPkgs.length; j++) {
            const p = utPkgs[j];
            if (!p || !p.name || !p.reference_file) continue;
            const rel = `unitary_test/${p.name}/${p.reference_file}`;
            const op = document.createElement("option");
            op.value = rel;
            op.textContent = `[unit] ${p.name}/${p.reference_file}`;
            recordingSelect.appendChild(op);
            recordingsMetaByName.set(rel, { filename: rel, kind: "unitary_test", mtime: p.mtime });
        }
        void refreshUnitaryTestSelect();
    } catch (e) {
        recordingSelect.innerHTML = "";
        recordingsMetaByName = new Map();
        const op = document.createElement("option");
        op.value = "";
        op.textContent = "(error cargando lista)";
        recordingSelect.appendChild(op);
    }
}

function closeOfflineMultiRecordingsModal() {
    if (offlineMultiRecordingsOverlay) offlineMultiRecordingsOverlay.style.display = "none";
}

function renderOfflineMultiRecordingsList() {
    if (!offlineMultiRecordingsList) return;
    const filter = String(offlineMultiRecordingsFilter && offlineMultiRecordingsFilter.value || "").trim().toLowerCase();
    const rows = Array.from(recordingsMetaByName.values())
        .map((r) => String(r && r.filename || "").trim())
        .filter((n) => !!n)
        .sort((a, b) => a.localeCompare(b));
    offlineMultiRecordingsList.innerHTML = "";
    const frag = document.createDocumentFragment();
    let visible = 0;
    for (const name of rows) {
        if (filter && !name.toLowerCase().includes(filter)) continue;
        visible += 1;
        const row = document.createElement("label");
        row.style.cssText = "display:flex;align-items:center;gap:8px;padding:4px 2px;";
        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.value = name;
        cb.className = "offline-multi-rec-check";
        cb.checked = offlineOverlaySelectedRecordings.includes(name);
        const txt = document.createElement("span");
        txt.textContent = name;
        row.appendChild(cb);
        row.appendChild(txt);
        frag.appendChild(row);
    }
    if (!visible) {
        const empty = document.createElement("div");
        empty.className = "plot-pending-data";
        empty.textContent = "Sin coincidencias.";
        frag.appendChild(empty);
    }
    offlineMultiRecordingsList.appendChild(frag);
}

async function openOfflineMultiRecordingsModal() {
    if (!offlineMultiRecordingsOverlay) return;
    if (recordingsMetaByName.size === 0) await refreshServerRecordings();
    if (offlineMultiRecordingsFilter) offlineMultiRecordingsFilter.value = "";
    if (offlineMultiUnifyTimeCheckbox) offlineMultiUnifyTimeCheckbox.checked = !!offlineOverlayUnifyTime;
    if (offlineMultiDeltaInput) offlineMultiDeltaInput.value = String(offlineOverlayDeltaSec > 0 ? offlineOverlayDeltaSec : 0.01);
    if (offlineMultiDeltaWrap) offlineMultiDeltaWrap.style.display = offlineOverlayUnifyTime ? "inline-flex" : "none";
    renderOfflineMultiRecordingsList();
    offlineMultiRecordingsOverlay.style.display = "flex";
}

async function refreshUnitaryTestSelect() {
    if (!unitaryTestSelect) return;
    try {
        const ur = await fetch("/api/unitary_test?_=" + Date.now(), { cache: "no-store" });
        unitaryTestSelect.innerHTML = "";
        const op0 = document.createElement("option");
        op0.value = "";
        const tr = I18N[currentLang] || I18N.es;
        op0.textContent = tr.unitaryTestSelectPlaceholder || "—";
        unitaryTestSelect.appendChild(op0);
        if (!ur.ok) return;
        const ud = await ur.json();
        const pkgs = Array.isArray(ud.packages) ? ud.packages : [];
        for (let i = 0; i < pkgs.length; i++) {
            const p = pkgs[i];
            if (!p || !p.name) continue;
            const o = document.createElement("option");
            o.value = p.name;
            o.textContent = p.name;
            unitaryTestSelect.appendChild(o);
        }
    } catch {
        /* ignore */
    }
}

function getReplayAliasCanonicalNames() {
    const s = new Set();
    for (const n of baseKnownVarNames || []) if (n) s.add(n);
    for (const n of knownVarNames || []) if (n) s.add(n);
    return Array.from(s).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: "base" }));
}

function syncKnownVarNamesForPlugins() {
    try {
        window.__VARMON_KNOWN_VAR_NAMES__ = getReplayAliasCanonicalNames();
    } catch {
        /* ignore */
    }
}

function getReplayAliasBindingForKey(key) {
    return normalizeReplayAliasBindingEntry(replayAliasByRecording[key]);
}

/** Limpiezas de pickers con lupa en filas del modal alias (sustituye innerHTML). */
let replayAliasPickerDisposers = [];

/** Borrador del modal: columna fichero → destino (editado por el usuario). */
let replayAliasModalDraft = {};
let replayAliasSearchTimer = 0;
let replayAliasSelectedRows = new Set();
let replayAliasDraftUndoStack = [];
let replayAliasDraftRedoStack = [];
/** `'offline'` | `'live'` — dataset objetivo del modal de alias replay. */
let replayAliasModalContext = "offline";

function getReplayAliasModalDataset() {
    return replayAliasModalContext === "live" ? liveReplayEmbedDataset : offlineDataset;
}

function getReplayAliasModalRecordingName() {
    if (replayAliasModalContext === "live") {
        return liveReplayEmbedRecordingName || liveReplayEmbedFileLabel || "";
    }
    return offlineRecordingName || "";
}

function computeReplayAliasMetaForLiveModal() {
    const ds = liveReplayEmbedDataset;
    const key = replayAliasStorageKey(liveReplayEmbedRecordingName || "", ds && ds.sourceName);
    return {
        recordingKey: key,
        sizeBytes: 0,
        sha256: ds && ds._replayContentSha256 ? String(ds._replayContentSha256) : undefined,
    };
}

function pushReplayAliasDraftUndo() {
    syncReplayAliasDraftFromDom();
    try {
        replayAliasDraftUndoStack.push(JSON.parse(JSON.stringify(replayAliasModalDraft)));
        replayAliasDraftRedoStack = [];
        if (replayAliasDraftUndoStack.length > 48) replayAliasDraftUndoStack.shift();
    } catch {
        /* ignore */
    }
    updateReplayAliasUndoRedoButtons();
}

function updateReplayAliasUndoRedoButtons() {
    const u = document.getElementById("replayAliasUndoBtn");
    const r = document.getElementById("replayAliasRedoBtn");
    if (u) u.disabled = replayAliasDraftUndoStack.length === 0;
    if (r) r.disabled = replayAliasDraftRedoStack.length === 0;
}

function undoReplayAliasDraftEdit() {
    if (replayAliasDraftUndoStack.length === 0) return;
    syncReplayAliasDraftFromDom();
    try {
        replayAliasDraftRedoStack.push(JSON.parse(JSON.stringify(replayAliasModalDraft)));
        replayAliasModalDraft = replayAliasDraftUndoStack.pop();
    } catch {
        return;
    }
    renderReplayAliasModalTable({ skipSyncFromDom: true });
    updateReplayAliasUndoRedoButtons();
}

function redoReplayAliasDraftEdit() {
    if (replayAliasDraftRedoStack.length === 0) return;
    syncReplayAliasDraftFromDom();
    try {
        replayAliasDraftUndoStack.push(JSON.parse(JSON.stringify(replayAliasModalDraft)));
        replayAliasModalDraft = replayAliasDraftRedoStack.pop();
    } catch {
        return;
    }
    renderReplayAliasModalTable({ skipSyncFromDom: true });
    updateReplayAliasUndoRedoButtons();
}

function syncReplayAliasDraftFromDom() {
    const tbody = document.getElementById("replayAliasTableBody");
    if (!tbody) return;
    for (const row of tbody.querySelectorAll("tr[data-src]")) {
        const raw = row.getAttribute("data-src");
        let src = "";
        try {
            src = raw ? decodeURIComponent(raw) : "";
        } catch {
            src = raw || "";
        }
        const inp = row.querySelector(".replay-alias-target-input");
        if (!src || !inp) continue;
        replayAliasModalDraft[src] = String(inp.value || "").trim();
    }
}

function computeReplayAliasMetaForCurrentLoad() {
    const key = replayAliasStorageKey(offlineRecordingName || "", offlineDataset && offlineDataset.sourceName);
    let sizeBytes = 0;
    if (offlineRecordingName && recordingsMetaByName && recordingsMetaByName.get) {
        const m = recordingsMetaByName.get(offlineRecordingName);
        if (m && Number.isFinite(Number(m.size))) sizeBytes = Number(m.size);
    }
    return { recordingKey: key, sizeBytes, sha256: offlineDataset && offlineDataset._replayContentSha256
        ? String(offlineDataset._replayContentSha256)
        : undefined };
}

function updateReplayAliasLinkStatusLine() {
    const el = document.getElementById("replayAliasLinkStatus");
    const mm = document.getElementById("replayAliasMetaMismatch");
    const modalDs = getReplayAliasModalDataset();
    if (!el || !modalDs) return;
    const tr = I18N[currentLang] || I18N.es;
    const key = replayAliasStorageKey(getReplayAliasModalRecordingName() || "", modalDs.sourceName);
    const meta = replayAliasModalContext === "live"
        ? computeReplayAliasMetaForLiveModal()
        : computeReplayAliasMetaForCurrentLoad();
    const binding = getReplayAliasBindingForKey(key);
    const stored = binding.meta || {};
    const parts = [];
    parts.push(`${tr.replayAliasLinkKey || "Clave"}: ${key}`);
    if (Number.isFinite(meta.sizeBytes) && meta.sizeBytes > 0) {
        parts.push(`${tr.replayAliasMetaSize || "Tamaño"}: ${formatBytes(meta.sizeBytes)}`);
    }
    if (meta.sha256) {
        parts.push(`${tr.replayAliasMetaSha || "SHA-256"}: ${meta.sha256.slice(0, 16)}…`);
    }
    el.textContent = parts.join(" · ");
    el.style.display = "block";
    const msgs = replayAliasMetaMismatchMessage(stored, meta);
    if (mm && msgs.length > 0) {
        mm.style.display = "block";
        mm.textContent = (tr.replayAliasMetaMismatch || "Los metadatos guardados difieren del fichero actual (%s).")
            .replace("%s", msgs.map((m) => `${m.code}`).join(", "));
    } else if (mm) {
        mm.style.display = "none";
        mm.textContent = "";
    }
}

function updateReplayAliasLoadBadge() {
    if (!replayAliasLoadBadge || !hasPlugin("replay_alias")) return;
    const tr = I18N[currentLang] || I18N.es;
    if (!isPlaybackMode() || !offlineDataset) {
        replayAliasLoadBadge.style.display = "none";
        replayAliasLoadBadge.textContent = "";
        return;
    }
    const key = replayAliasStorageKey(offlineRecordingName || "", offlineDataset.sourceName);
    const b = getReplayAliasBindingForKey(key);
    const n = Object.keys(b.map || {}).length;
    const parts = [];
    if (b.disabled) {
        parts.push(tr.replayAliasBadgeOff || "Alias off");
    } else if (n > 0) {
        parts.push((tr.replayAliasBadgeOn || "Alias: %n").replace("%n", String(n)));
    } else {
        parts.push(tr.replayAliasBadgeNone || "Sin alias");
    }
    replayAliasLoadBadge.textContent = parts.join(" ");
    replayAliasLoadBadge.style.display = "inline-flex";
}

function updateReplayAliasButtonVisibility() {
    if (!replayAliasBtn) return;
    const pro = hasPlugin("replay_alias");
    const show = pro && isPlaybackMode() && !!offlineDataset;
    replayAliasBtn.style.display = show ? "inline-flex" : "none";
    if (replayAliasLoadBadge) {
        replayAliasLoadBadge.style.display = pro && isPlaybackMode() && offlineDataset ? "inline-flex" : "none";
    }
    if (pro) updateReplayAliasLoadBadge();
    else if (replayAliasLoadBadge) replayAliasLoadBadge.textContent = "";
}

function refreshReplayAliasProfileSelect() {
    const sel = document.getElementById("replayAliasProfileSelect");
    if (!sel) return;
    const names = Object.keys(replayAliasProfiles || {}).sort((a, b) => a.localeCompare(b));
    const prev = sel.value;
    sel.innerHTML = `<option value="">(${I18N[currentLang]?.replayAliasProfilePick || "— plantilla —"})</option>`;
    for (const n of names) {
        const op = document.createElement("option");
        op.value = n;
        op.textContent = n;
        sel.appendChild(op);
    }
    if (prev && names.includes(prev)) sel.value = prev;
}

function renderReplayAliasDiffPanel(allSources, draftMap, canonicalList) {
    const canonSet = new Set(canonicalList);
    const fileUl = document.getElementById("replayAliasDiffFileList");
    const canonUl = document.getElementById("replayAliasDiffCanonList");
    const t = I18N[currentLang] || I18N.es;
    const ft = document.getElementById("replayAliasDiffFileTitle");
    const ct = document.getElementById("replayAliasDiffCanonTitle");
    if (ft) ft.textContent = t.replayAliasDiffFileTitle || "Fichero";
    if (ct) ct.textContent = t.replayAliasDiffCanonTitle || "Monitor";
    if (!fileUl || !canonUl) return;
    let fHtml = "";
    let cHtml = "";
    for (const src of allSources) {
        const target = draftMap[src] != null && String(draftMap[src]).trim() !== "" ? String(draftMap[src]).trim() : src;
        const st = replayAliasRowStatus(src, draftMap, canonSet);
        const cls = st.identity ? "replay-alias-diff-li identity" : (st.inCanon ? "replay-alias-diff-li ok" : "replay-alias-diff-li warn");
        fHtml += `<li class="${cls}"><code>${escapeHtml(src)}</code></li>`;
        cHtml += `<li class="${cls}"><code>${escapeHtml(target)}</code></li>`;
    }
    fileUl.innerHTML = fHtml || `<li>${escapeHtml(t.replayAliasNoColumns || "—")}</li>`;
    canonUl.innerHTML = cHtml || `<li>${escapeHtml(t.replayAliasNoColumns || "—")}</li>`;
}

function renderReplayAliasModalTable(opts) {
    const tbody = document.getElementById("replayAliasTableBody");
    const coll = document.getElementById("replayAliasCollision");
    const hdrCb = document.getElementById("replayAliasHeaderSelectAll");
    const modalDs = getReplayAliasModalDataset();
    if (!tbody || !modalDs) return;
    if (!(opts && opts.skipSyncFromDom)) syncReplayAliasDraftFromDom();
    const tr = I18N[currentLang] || I18N.es;
    const allSources = collectUniqueReplaySourceNames(modalDs);
    const key = replayAliasStorageKey(getReplayAliasModalRecordingName() || "", modalDs.sourceName);
    const binding = getReplayAliasBindingForKey(key);
    for (const src of allSources) {
        if (replayAliasModalDraft[src] == null) {
            replayAliasModalDraft[src] = binding.map[src] != null ? binding.map[src] : src;
        }
    }
    const effectiveMap = effectiveReplayAliasMap(allSources, replayAliasModalDraft);
    const canonical = getReplayAliasCanonicalNames();
    const canonSet = new Set(canonical);
    const filtEl = document.getElementById("replayAliasFilterSelect");
    const qEl = document.getElementById("replayAliasSearchInput");
    const filterKind = (filtEl && filtEl.value) || "all";
    const q = qEl ? String(qEl.value || "") : "";
    const filtered = filterReplayAliasSources(allSources, q, filterKind, effectiveMap, canonSet);
    const { duplicateTargets } = detectReplayAliasCollisions(effectiveMap);
    if (coll) {
        if (duplicateTargets.length) {
            coll.style.display = "block";
            coll.textContent = (tr.replayAliasCollisionMsg || "Varias columnas apuntan al mismo nombre: %s")
                .replace("%s", duplicateTargets.map((d) => `${d.target} ← ${d.sources.join(", ")}`).join("; "));
        } else {
            coll.style.display = "none";
            coll.textContent = "";
        }
    }
    renderReplayAliasDiffPanel(allSources, effectiveMap, canonical);
    for (const d of replayAliasPickerDisposers) {
        try {
            d();
        } catch {
            /* ignore */
        }
    }
    replayAliasPickerDisposers = [];
    tbody.replaceChildren();
        if (filtered.length === 0) {
        const trEmpty = document.createElement("tr");
        const tdEmpty = document.createElement("td");
            tdEmpty.colSpan = 3;
        tdEmpty.textContent = tr.replayAliasNoColumns || "Sin columnas";
        trEmpty.appendChild(tdEmpty);
        tbody.appendChild(trEmpty);
    } else {
        for (const src of filtered) {
            const val = effectiveMap[src] != null ? effectiveMap[src] : src;
            const enc = encodeURIComponent(src);
            const st = replayAliasRowStatus(src, effectiveMap, canonSet);
            const rowCls = st.identity ? "replay-alias-tr-identity" : (st.inCanon ? "" : "replay-alias-tr-warn");
            const tr = document.createElement("tr");
            tr.className = rowCls;
            tr.setAttribute("data-src", enc);

            const tdCb = document.createElement("td");
            tdCb.className = "replay-alias-td-cb";
            const cb = document.createElement("input");
            cb.type = "checkbox";
            cb.className = "replay-alias-row-cb";
            if (replayAliasSelectedRows.has(src)) cb.checked = true;
            tdCb.appendChild(cb);
            tr.appendChild(tdCb);

            const tdSrc = document.createElement("td");
            const code = document.createElement("code");
            code.textContent = src;
            tdSrc.appendChild(code);
            tr.appendChild(tdSrc);

            const tdTarget = document.createElement("td");
            const { row, dispose } = createSearchableVarPickerField({
                showLabel: false,
                inputClassName: "replay-alias-target-input flight-viz-var-field-input",
                initial: val,
                extraNameSet: null,
            });
            tdTarget.appendChild(row);
            replayAliasPickerDisposers.push(dispose);
            tr.appendChild(tdTarget);

            tbody.appendChild(tr);
        }
    }
    if (hdrCb) {
        const vis = filtered.length;
        const allSel = vis > 0 && filtered.every((s) => replayAliasSelectedRows.has(s));
        hdrCb.checked = allSel;
        hdrCb.title = tr.replayAliasHeaderSelectTitle || "";
    }
    const disEl = document.getElementById("replayAliasDisabledCheckbox");
    const tableWrap = document.querySelector(".replay-alias-table-wrap");
    if (tableWrap && disEl) {
        tableWrap.style.opacity = disEl.checked ? "0.55" : "";
        tableWrap.style.pointerEvents = disEl.checked ? "none" : "";
    }
    updateReplayAliasUndoRedoButtons();
}

function closeReplayAliasModal() {
    replayAliasModalContext = "offline";
    for (const d of replayAliasPickerDisposers) {
        try {
            d();
        } catch {
            /* ignore */
        }
    }
    replayAliasPickerDisposers = [];
    const ov = document.getElementById("replayAliasOverlay");
    if (ov) ov.style.display = "none";
    if (replayAliasSearchTimer) {
        clearTimeout(replayAliasSearchTimer);
        replayAliasSearchTimer = 0;
    }
}

function openReplayAliasModal() {
    if (isLiveMode() && liveReplayEmbedDataset) {
        openLiveReplayAliasModal();
        return;
    }
    if (!hasPlugin("replay_alias") || !replayAliasApi()) {
        const tr = I18N[currentLang] || I18N.es;
        alert(tr.replayAliasModuleOnly || "Los alias de replay requieren el módulo replay_alias.");
        return;
    }
    if (!offlineDataset || !isPlaybackMode()) return;
    replayAliasModalContext = "offline";
    const ov = document.getElementById("replayAliasOverlay");
    const hint = document.getElementById("replayAliasHint");
    const tr = I18N[currentLang] || I18N.es;
    const key = replayAliasStorageKey(offlineRecordingName || "", offlineDataset.sourceName);
    const binding = getReplayAliasBindingForKey(key);
    replayAliasModalDraft = {};
    replayAliasSelectedRows = new Set();
    replayAliasDraftUndoStack = [];
    replayAliasDraftRedoStack = [];
    const allSources = collectUniqueReplaySourceNames(offlineDataset);
    for (const src of allSources) {
        replayAliasModalDraft[src] = binding.map[src] != null ? binding.map[src] : src;
    }
    const dis = document.getElementById("replayAliasDisabledCheckbox");
    if (dis) dis.checked = !!binding.disabled;
    const fs = document.getElementById("replayAliasFilterSelect");
    if (fs) fs.value = "all";
    const si = document.getElementById("replayAliasSearchInput");
    if (si) si.value = "";
    if (hint) {
        hint.textContent = (tr.replayAliasHint || "Grabación: %s — Asigne cada columna del fichero a un nombre del monitor.")
            .replace("%s", key);
    }
    updateReplayAliasLinkStatusLine();
    refreshReplayAliasProfileSelect();
    renderReplayAliasModalTable();
    if (ov) ov.style.display = "flex";
}

function openLiveReplayAliasModal() {
    if (!hasPlugin("replay_alias") || !replayAliasApi()) {
        const tr = I18N[currentLang] || I18N.es;
        alert(tr.replayAliasModuleOnly || "Los alias de replay requieren el módulo replay_alias.");
        return;
    }
    if (!liveReplayEmbedDataset || !isLiveMode()) return;
    replayAliasModalContext = "live";
    const ov = document.getElementById("replayAliasOverlay");
    const hint = document.getElementById("replayAliasHint");
    const tr = I18N[currentLang] || I18N.es;
    const key = replayAliasStorageKey(getReplayAliasModalRecordingName() || "", liveReplayEmbedDataset.sourceName);
    const binding = getReplayAliasBindingForKey(key);
    replayAliasModalDraft = {};
    replayAliasSelectedRows = new Set();
    replayAliasDraftUndoStack = [];
    replayAliasDraftRedoStack = [];
    const allSources = collectUniqueReplaySourceNames(liveReplayEmbedDataset);
    for (const src of allSources) {
        replayAliasModalDraft[src] = binding.map[src] != null ? binding.map[src] : src;
    }
    const dis = document.getElementById("replayAliasDisabledCheckbox");
    if (dis) dis.checked = !!binding.disabled;
    const fs = document.getElementById("replayAliasFilterSelect");
    if (fs) fs.value = "all";
    const si = document.getElementById("replayAliasSearchInput");
    if (si) si.value = "";
    if (hint) {
        hint.textContent = (tr.replayAliasHintLiveReplay || "Replay en vivo: %s — Asigne cada columna del fichero a un nombre del monitor.")
            .replace("%s", key);
    }
    updateReplayAliasLinkStatusLine();
    refreshReplayAliasProfileSelect();
    renderReplayAliasModalTable();
    if (ov) ov.style.display = "flex";
}

function readReplayAliasInputsFromModal() {
    syncReplayAliasDraftFromDom();
    return normalizeReplayAliasMap(replayAliasModalDraft);
}

function compactReplayAliasMap(effectiveMap) {
    const out = {};
    for (const [k, v] of Object.entries(effectiveMap || {})) {
        if (k !== v) out[k] = v;
    }
    return out;
}

function applyReplayAliasesFromModal() {
    const modalDs = getReplayAliasModalDataset();
    if (!modalDs) return;
    const tr = I18N[currentLang] || I18N.es;
    const key = replayAliasStorageKey(getReplayAliasModalRecordingName() || "", modalDs.sourceName);
    syncReplayAliasDraftFromDom();
    const allSources = collectUniqueReplaySourceNames(modalDs);
    const effectiveFull = effectiveReplayAliasMap(allSources, replayAliasModalDraft);
    const map = compactReplayAliasMap(effectiveFull);
    const disEl = document.getElementById("replayAliasDisabledCheckbox");
    const disabled = !!(disEl && disEl.checked);
    const { duplicateTargets } = detectReplayAliasCollisions(effectiveFull);
    if (!disabled && duplicateTargets.length) {
        alert(tr.replayAliasCollisionAlert || "Hay colisiones: varias columnas no pueden renombrarse al mismo nombre.");
        renderReplayAliasModalTable();
        return;
    }
    const prev = getReplayAliasBindingForKey(key);
    const metaMerge = replayAliasModalContext === "live"
        ? computeReplayAliasMetaForLiveModal()
        : computeReplayAliasMetaForCurrentLoad();
    const meta = { ...(prev.meta || {}), ...metaMerge };
    replayAliasByRecording[key] = { map: { ...map }, disabled, meta };
    saveConfig();
    resetReplayNamesToSource(modalDs);
    let res = { ok: true };
    if (!disabled && Object.keys(map).length > 0) {
        res = applyReplayAliasesInPlace(modalDs, map);
    }
    if (!res.ok) {
        alert(tr.replayAliasApplyFail || "No se pudieron aplicar los alias.");
        return;
    }
    if (replayAliasModalContext === "live") {
        liveReplayEmbedDataset = modalDs;
        notifyLiveReplayEmbedUi();
        rebuildMonitorList();
        schedulePlotRender();
        closeReplayAliasModal();
        return;
    }
    varNamesInTsv = new Set(offlineDataset.names || []);
    const merge = Array.isArray(offlineDataset._replayLiveMerge) ? offlineDataset._replayLiveMerge : [];
    rebindOfflineDatasetBindings(offlineDataset, { preserveLayout: true, liveVarNamesForMerge: merge });
    updateReplayAliasLoadBadge();
    updateOfflineDatasetStatus();
    closeReplayAliasModal();
}

function clearReplayAliasesForCurrentRecording() {
    if (!offlineDataset) return;
    const tr = I18N[currentLang] || I18N.es;
    const key = replayAliasStorageKey(offlineRecordingName || "", offlineDataset.sourceName);
    delete replayAliasByRecording[key];
    saveConfig();
    resetReplayNamesToSource(offlineDataset);
    varNamesInTsv = new Set(offlineDataset.names || []);
    const merge = Array.isArray(offlineDataset._replayLiveMerge) ? offlineDataset._replayLiveMerge : [];
    rebindOfflineDatasetBindings(offlineDataset, { preserveLayout: true, liveVarNamesForMerge: merge });
    updateReplayAliasLoadBadge();
    updateOfflineDatasetStatus();
    closeReplayAliasModal();
    alert(tr.replayAliasCleared || "Alias eliminados para esta grabación.");
}

function exportReplayAliasJson() {
    if (!offlineDataset) return;
    const key = replayAliasStorageKey(offlineRecordingName || "", offlineDataset.sourceName);
    syncReplayAliasDraftFromDom();
    const allSources = collectUniqueReplaySourceNames(offlineDataset);
    const effectiveFull = effectiveReplayAliasMap(allSources, replayAliasModalDraft);
    const map = compactReplayAliasMap(effectiveFull);
    const disEl = document.getElementById("replayAliasDisabledCheckbox");
    const binding = getReplayAliasBindingForKey(key);
    const payload = {
        version: 1,
        recordingKey: key,
        exportedAt: new Date().toISOString(),
        map,
        disabled: !!(disEl && disEl.checked),
        meta: { ...(binding.meta || {}), ...computeReplayAliasMetaForCurrentLoad() },
    };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = `replay_aliases_${key.replace(/[^a-z0-9._-]+/gi, "_").slice(0, 80) || "local"}.json`;
    a.click();
    URL.revokeObjectURL(a.href);
}

function importReplayAliasFromFile(file) {
    if (!file || !offlineDataset) return;
    const tr = I18N[currentLang] || I18N.es;
    const reader = new FileReader();
    reader.onload = () => {
        try {
            const j = JSON.parse(reader.result);
            const map = normalizeReplayAliasMap(j.map || j);
            const disabled = !!j.disabled;
            const key = replayAliasStorageKey(offlineRecordingName || "", offlineDataset.sourceName);
            replayAliasByRecording[key] = {
                map,
                disabled,
                meta: j.meta && typeof j.meta === "object" ? { ...j.meta } : computeReplayAliasMetaForCurrentLoad(),
            };
            saveConfig();
            replayAliasModalDraft = { ...map };
            for (const src of collectUniqueReplaySourceNames(offlineDataset)) {
                if (replayAliasModalDraft[src] == null) replayAliasModalDraft[src] = src;
            }
            const disEl = document.getElementById("replayAliasDisabledCheckbox");
            if (disEl) disEl.checked = disabled;
            renderReplayAliasModalTable();
            alert(tr.replayAliasImportOk || "Mapa importado. Pulse Aplicar para usarlo en el dataset.");
        } catch (e) {
            alert(tr.replayAliasImportFail || "JSON inválido.");
        }
    };
    reader.readAsText(file);
}

function saveReplayAliasProfileFromModal() {
    const inp = document.getElementById("replayAliasProfileNameInput");
    const name = sanitizeReplayAliasProfileName(inp && inp.value ? inp.value : "");
    if (!name) return;
    syncReplayAliasDraftFromDom();
    replayAliasProfiles[name] = {
        map: { ...normalizeReplayAliasMap(replayAliasModalDraft) },
        updatedAt: new Date().toISOString(),
    };
    replayAliasProfiles = clipReplayAliasProfiles(replayAliasProfiles);
    saveConfig();
    refreshReplayAliasProfileSelect();
    const sel = document.getElementById("replayAliasProfileSelect");
    if (sel) sel.value = name;
}

function applyReplayAliasProfileSelected() {
    const sel = document.getElementById("replayAliasProfileSelect");
    const name = sel && sel.value ? String(sel.value) : "";
    if (!name || !replayAliasProfiles[name]) return;
    pushReplayAliasDraftUndo();
    const m = replayAliasProfiles[name].map || {};
    const allSources = collectUniqueReplaySourceNames(offlineDataset);
    for (const src of allSources) {
        replayAliasModalDraft[src] = m[src] != null ? m[src] : src;
    }
    renderReplayAliasModalTable();
}

function deleteReplayAliasProfileSelected() {
    const sel = document.getElementById("replayAliasProfileSelect");
    const name = sel && sel.value ? String(sel.value) : "";
    if (!name || !replayAliasProfiles[name]) return;
    delete replayAliasProfiles[name];
    saveConfig();
    refreshReplayAliasProfileSelect();
}

function applyReplayAliasBatchTransforms() {
    syncReplayAliasDraftFromDom();
    const tr = I18N[currentLang] || I18N.es;
    const pfx = document.getElementById("replayAliasBatchPrefix");
    const sfx = document.getElementById("replayAliasBatchSuffix");
    const find = document.getElementById("replayAliasBatchFind");
    const rep = document.getElementById("replayAliasBatchReplace");
    const prefix = pfx ? String(pfx.value || "") : "";
    const suffix = sfx ? String(sfx.value || "") : "";
    const findStr = find ? String(find.value || "") : "";
    const repStr = rep ? String(rep.value || "") : "";
    if (replayAliasSelectedRows.size === 0) {
        alert(tr.replayAliasBatchNoSelection || "Seleccione al menos una fila.");
        return;
    }
    pushReplayAliasDraftUndo();
    for (const src of replayAliasSelectedRows) {
        let t = replayAliasModalDraft[src] != null ? String(replayAliasModalDraft[src]) : src;
        if (findStr) t = t.split(findStr).join(repStr);
        t = prefix + t + suffix;
        replayAliasModalDraft[src] = t;
    }
    renderReplayAliasModalTable({ skipSyncFromDom: true });
}

function wireReplayAliasUi() {
    if (!hasPlugin("replay_alias")) return;
    if (replayAliasBtn && !replayAliasBtn._bound) {
        replayAliasBtn._bound = true;
        replayAliasBtn.addEventListener("click", () => {
            if (isLiveMode() && liveReplayEmbedDataset) {
                openLiveReplayAliasModal();
            } else {
                openReplayAliasModal();
            }
        });
    }
    const closeBtn = document.getElementById("replayAliasCloseBtn");
    const cancelBtn = document.getElementById("replayAliasCancelBtn");
    const applyBtn = document.getElementById("replayAliasApplyBtn");
    const clearBtn = document.getElementById("replayAliasClearBtn");
    if (closeBtn && !closeBtn._replayBound) {
        closeBtn._replayBound = true;
        closeBtn.addEventListener("click", closeReplayAliasModal);
    }
    if (cancelBtn && !cancelBtn._replayBound) {
        cancelBtn._replayBound = true;
        cancelBtn.addEventListener("click", closeReplayAliasModal);
    }
    if (applyBtn && !applyBtn._replayBound) {
        applyBtn._replayBound = true;
        applyBtn.addEventListener("click", applyReplayAliasesFromModal);
    }
    if (clearBtn && !clearBtn._replayBound) {
        clearBtn._replayBound = true;
        clearBtn.addEventListener("click", clearReplayAliasesForCurrentRecording);
    }
    const fs = document.getElementById("replayAliasFilterSelect");
    if (fs && !fs._replayBound) {
        fs._replayBound = true;
        fs.addEventListener("change", () => renderReplayAliasModalTable());
    }
    const si = document.getElementById("replayAliasSearchInput");
    if (si && !si._replayBound) {
        si._replayBound = true;
        si.addEventListener("input", () => {
            if (replayAliasSearchTimer) clearTimeout(replayAliasSearchTimer);
            replayAliasSearchTimer = setTimeout(() => renderReplayAliasModalTable(), 120);
        });
    }
    const tbody = document.getElementById("replayAliasTableBody");
    if (tbody && !tbody._replayDeleg) {
        tbody._replayDeleg = true;
        tbody.addEventListener("input", (e) => {
            const t = e.target;
            if (t && t.classList && t.classList.contains("replay-alias-target-input")) {
                const row = t.closest("tr[data-src]");
                const raw = row && row.getAttribute("data-src");
                let src = "";
                try {
                    src = raw ? decodeURIComponent(raw) : "";
                } catch {
                    src = raw || "";
                }
                if (src) replayAliasModalDraft[src] = String(t.value || "").trim();
            }
        });
        tbody.addEventListener("change", (e) => {
            const t = e.target;
            if (t && t.classList && t.classList.contains("replay-alias-row-cb")) {
                const row = t.closest("tr[data-src]");
                const raw = row && row.getAttribute("data-src");
                let src = "";
                try {
                    src = raw ? decodeURIComponent(raw) : "";
                } catch {
                    src = raw || "";
                }
                if (!src) return;
                if (t.checked) replayAliasSelectedRows.add(src);
                else replayAliasSelectedRows.delete(src);
            }
        });
    }
    const hdrCb = document.getElementById("replayAliasHeaderSelectAll");
    if (hdrCb && !hdrCb._replayBound) {
        hdrCb._replayBound = true;
        hdrCb.addEventListener("change", () => {
            const filtEl = document.getElementById("replayAliasFilterSelect");
            const qEl = document.getElementById("replayAliasSearchInput");
            const allSources = offlineDataset ? collectUniqueReplaySourceNames(offlineDataset) : [];
            const canonSet = new Set(getReplayAliasCanonicalNames());
            const filterKind = (filtEl && filtEl.value) || "all";
            const q = qEl ? String(qEl.value || "") : "";
            syncReplayAliasDraftFromDom();
            const effectiveMap = effectiveReplayAliasMap(allSources, replayAliasModalDraft);
            const filtered = filterReplayAliasSources(allSources, q, filterKind, effectiveMap, canonSet);
            if (hdrCb.checked) {
                for (const s of filtered) replayAliasSelectedRows.add(s);
            } else {
                for (const s of filtered) replayAliasSelectedRows.delete(s);
            }
            renderReplayAliasModalTable();
        });
    }
    const sa = document.getElementById("replayAliasSelectAllFiltered");
    if (sa && !sa._replayBound && hdrCb) {
        sa._replayBound = true;
        sa.addEventListener("change", () => {
            hdrCb.checked = sa.checked;
            hdrCb.dispatchEvent(new Event("change"));
        });
    }
    const ps = document.getElementById("replayAliasProfileSaveBtn");
    const pa = document.getElementById("replayAliasProfileApplyBtn");
    const pd = document.getElementById("replayAliasProfileDeleteBtn");
    if (ps && !ps._replayBound) {
        ps._replayBound = true;
        ps.addEventListener("click", saveReplayAliasProfileFromModal);
    }
    if (pa && !pa._replayBound) {
        pa._replayBound = true;
        pa.addEventListener("click", applyReplayAliasProfileSelected);
    }
    if (pd && !pd._replayBound) {
        pd._replayBound = true;
        pd.addEventListener("click", deleteReplayAliasProfileSelected);
    }
    const ex = document.getElementById("replayAliasExportBtn");
    const im = document.getElementById("replayAliasImportBtn");
    const imIn = document.getElementById("replayAliasImportInput");
    if (ex && !ex._replayBound) {
        ex._replayBound = true;
        ex.addEventListener("click", exportReplayAliasJson);
    }
    if (im && imIn && !im._replayBound) {
        im._replayBound = true;
        im.addEventListener("click", () => imIn.click());
        imIn.addEventListener("change", () => {
            const f = imIn.files && imIn.files[0];
            if (f) importReplayAliasFromFile(f);
            imIn.value = "";
        });
    }
    const bat = document.getElementById("replayAliasBatchApplyBtn");
    if (bat && !bat._replayBound) {
        bat._replayBound = true;
        bat.addEventListener("click", applyReplayAliasBatchTransforms);
    }
    const raUndoBtn = document.getElementById("replayAliasUndoBtn");
    const raRedoBtn = document.getElementById("replayAliasRedoBtn");
    if (raUndoBtn && !raUndoBtn._replayBound) {
        raUndoBtn._replayBound = true;
        raUndoBtn.addEventListener("click", () => undoReplayAliasDraftEdit());
    }
    if (raRedoBtn && !raRedoBtn._replayBound) {
        raRedoBtn._replayBound = true;
        raRedoBtn.addEventListener("click", () => redoReplayAliasDraftEdit());
    }
    const dis = document.getElementById("replayAliasDisabledCheckbox");
    if (dis && !dis._replayBound) {
        dis._replayBound = true;
        dis.addEventListener("change", () => renderReplayAliasModalTable());
    }
    const ov = document.getElementById("replayAliasOverlay");
    if (ov && !ov._replayBackdrop) {
        ov._replayBackdrop = true;
        ov.addEventListener("click", (e) => {
            if (e.target === ov) closeReplayAliasModal();
        });
    }
    updateReplayAliasButtonVisibility();
}

function rebindOfflineDatasetBindings(ds, opts) {
    const preserveLayout = !!opts.preserveLayout;
    const liveVarNamesForMerge = Array.isArray(opts.liveVarNamesForMerge) ? opts.liveVarNamesForMerge : [];
    markerA = null;
    markerB = null;
    deltaByName = {};
    if (timeWindowSelect) timeWindowSelect.value = "120";
    if (isReplayMode() && liveVarNamesForMerge.length > 0) {
        const merged = [...new Set([...(ds && ds.names ? ds.names : []), ...liveVarNamesForMerge])].sort();
        onVarNames(merged);
    } else {
        onVarNames(ds.names);
    }
    rebuildHistoriesFromOffline(ds);
    if (isReplayMode() && ds && Array.isArray(ds.names)) {
        ds.names.forEach((n) => syncReplayTsvHistoryForName(n));
    }
    restoreFullHistoriesForPlottedVars();
    if (isReplayMode() && ds && Array.isArray(ds.names)) {
        ds.names.forEach((n) => syncReplayTsvHistoryForName(n));
    }
    const initialSnapshot = buildInitialOfflineSnapshot(ds);
    if (initialSnapshot.length > 0) {
        onVarsUpdate(initialSnapshot, { appendHistory: false });
    }
    offlinePlayback.currentTs = ds.minTs;
    offlinePlayback.currentIndex = 0;
    if (offlineSpeedSelect) {
        const sp = Number(offlineSpeedSelect.value);
        offlinePlayback.speed = Number.isFinite(sp) && sp > 0 ? sp : 1;
    } else {
        offlinePlayback.speed = 1;
    }
    applyOfflineTime(ds.minTs);
    recomputeDeltaByName();
    setOfflineStatus();
    if (!preserveLayout) rebuildMonitorList();
    updateOfflineDatasetStatus();
    updateMarkerInfoLabel();
    updateOfflineChunkButtons();
    renderSegmentsUi();
    renderNotesList();
    schedulePlotRender();
}

async function loadOfflineDataset(ds, opts = {}) {
    const preserveLayout = !!opts.preserveLayout;
    stopOfflinePlayback();
    const prevOfflineRecordingName = offlineRecordingName;
    // En replay (modo híbrido) conservar nombres del backend para unir con los del TSV.
    const liveVarNamesForMerge = isReplayMode() ? baseKnownVarNames.slice() : [];
    if (!preserveLayout) clearUserLayout();
    clearDataBuffers();
    // fullHistoryByName / windowMetaByName se vacían en clearDataBuffers (ver arriba).
    // Si conservamos layout (monitorizadas + asignación de gráficos),
    // hay que reconstruir los slots visuales tras limpiar buffers/DOM.
    if (preserveLayout) {
        rebuildPlotArea();
        rebuildMonitorList();
    }
    offlineDataset = ds;
    offlineOverlayDatasetsMeta = Array.isArray(ds && ds._overlayMembers) ? ds._overlayMembers.slice() : [];
    if (!(Array.isArray(ds && ds._overlayMembers) && ds._overlayMembers.length > 1)) {
        offlineOverlaySelectedRecordings = [];
        offlineOverlayUnifyTime = false;
        offlineOverlayDeltaSec = 0.01;
    }
    if (offlineDataset && typeof offlineDataset === "object") {
        offlineDataset._replayLiveMerge = liveVarNamesForMerge.slice();
    }
    offlineSafetyInfo = opts.safeInfo && opts.safeInfo.safeMode ? { ...opts.safeInfo } : null;
    if (typeof opts.recordingName === "string") {
        offlineRecordingName = opts.recordingName;
    } else if (!offlineRecordingName && ds && ds.sourceName && recordingSelect && Array.from(recordingSelect.options).some((o) => o.value === ds.sourceName)) {
        offlineRecordingName = ds.sourceName;
    }
    if (typeof opts.fileTextForHash === "string") {
        try {
            ds._replayContentSha256 = await sha256HexFromString(opts.fileTextForHash);
        } catch (e) {
            ds._replayContentSha256 = undefined;
        }
    } else {
        ds._replayContentSha256 = undefined;
    }
    stampReplaySourceNames(ds);
    const aliasKey = replayAliasStorageKey(offlineRecordingName || "", ds && ds.sourceName);
    if (ds && typeof ds === "object") ds._replayAliasBindingKey = aliasKey;
    if (hasPlugin("replay_alias") && replayAliasApi()) {
        const binding = getReplayAliasBindingForKey(aliasKey);
        if (!binding.disabled && binding.map && typeof binding.map === "object" && Object.keys(binding.map).length > 0) {
            const res = applyReplayAliasesInPlace(ds, binding.map);
            if (!res.ok) {
                console.warn("[VarMonitor] Alias replay con colisiones omitido para", aliasKey, res.duplicateTargets);
            }
        }
    }
    varNamesInTsv = new Set(ds && Array.isArray(ds.names) ? ds.names : []);
    fireHook("on_offline_dataset_loaded", ds);
    refreshAnalysisReportContext();
    // Mantener una referencia global de tiempo por grabación para que
    // los tramos sucesivos no reinicien el eje temporal a 0. Solo se
    // inicializa una vez (aunque ds.minTs pueda ser 0, que es válido).
    if (ds && Number.isFinite(ds.minTs) && !Number.isFinite(offlineRecordingGlobalMinTs)) {
        offlineRecordingGlobalMinTs = ds.minTs;
    }
    // Si el usuario cargó una grabación diferente, resetear los límites globales.
    // Esto evita que un maxTs previo (p.ej. de un tramo de modo seguro) limite el scrubber y el rango temporal.
    if (typeof offlineRecordingName === "string" && offlineRecordingName && prevOfflineRecordingName && offlineRecordingName !== prevOfflineRecordingName) {
        offlineRecordingGlobalMinTs = null;
        offlineRecordingGlobalMaxTs = null;
    }
    // Si conocemos el nombre de la grabación y aún no tenemos maxTs global,
    // pedirlo al backend para que el scrubber y el playback trabajen sobre
    // el tiempo completo en lugar de solo el primer tramo.
    if (offlineRecordingName && !Number.isFinite(offlineRecordingGlobalMaxTs)) {
        try {
            const resp = await fetch(
                `/api/recordings/${encodeURIComponent(offlineRecordingName)}/bounds`
            );
            if (resp.ok) {
                const bd = await resp.json();
                const minB = Number(bd.minTs);
                const maxB = Number(bd.maxTs);
                if (Number.isFinite(minB)) offlineRecordingGlobalMinTs = minB;
                if (Number.isFinite(maxB)) offlineRecordingGlobalMaxTs = maxB;
            }
        } catch (e) {
            // Si falla, seguimos usando los min/max del tramo actual.
        }
    }
    rebindOfflineDatasetBindings(ds, { preserveLayout, liveVarNamesForMerge });
    updateReplayAliasButtonVisibility();
    updateAnalysisOpenRefFileBtnVisibility();
}

async function loadRecordingFromServer(filename, opts = {}) {
    if (!filename) return;
    beginOfflineDatasetLoad();
    try {
        const meta = recordingsMetaByName.get(filename) || null;
        const sizeBytes = Number(meta && meta.size);
        const isPq = isRecordingParquetFilename(filename);
        const useSafe = isPq
            ? shouldUseSafeParquetLoad(meta, sizeBytes)
            : shouldUseSafeOfflineLoad(sizeBytes);
        if (useSafe) {
            let forceFull = false;
            if (!isPq) {
                try {
                    const previewBytes = Math.max(1, Math.floor(offlinePreviewMb * 1024 * 1024));
                    const rMeta = await fetch(`/api/recordings/${encodeURIComponent(filename)}?preview_bytes=${previewBytes}`);
                    if (rMeta.ok) {
                        const p = await rMeta.json();
                        const previewText = trimTextToFullLines(p && p.preview ? p.preview : "");
                        const risk = estimateTsvLoadRisk(previewText, sizeBytes || Number(p && p.size) || 0);
                        forceFull = shouldForceFullLoadWithConfirmation(filename, sizeBytes || Number(p && p.size) || 0, risk.estRamBytes);
                    }
                } catch (e) { /* si falla, seguimos en modo seguro */ }
            }
            if (forceFull && !isPq) {
                const rFull = await fetch("/api/recordings/" + encodeURIComponent(filename));
                if (!rFull.ok) throw new Error("No se pudo descargar la grabación");
                const textFull = await rFull.text();
                const dsFull = parseTsvDataset(textFull, filename);
                await loadOfflineDataset(dsFull, { ...opts, recordingName: filename, safeInfo: null, fileTextForHash: textFull });
                return;
            }
            const safe = await loadLargeServerFileInSafeMode(filename, sizeBytes);
            // Primer tramo en modo seguro: timestamps tal cual (offset 0). Después
            // de cargarlo, guardamos cuánto dura para poder desplazar los tramos
            // siguientes y que el tiempo sea continuo.
            await loadOfflineDataset(safe.ds, { ...opts, recordingName: filename, safeInfo: safe.safeInfo });
            if (safe.safeInfo && Number.isFinite(safe.safeInfo.segmentSpanSec)) {
                offlineSegmentOffsetSec = safe.safeInfo.segmentSpanSec;
                // La referencia global arranca en el primer timestamp real de la grabación.
                offlineRecordingGlobalMinTs = safe.ds.minTs;
            }
            return;
        }
        if (isPq) {
            await loadWholeParquetFromServer(filename, meta, opts);
            return;
        }
        const r = await fetch("/api/recordings/" + encodeURIComponent(filename));
        if (!r.ok) throw new Error("No se pudo descargar la grabación");
        const text = await r.text();
        const ds = parseTsvDataset(text, filename);
        await loadOfflineDataset(ds, { ...opts, recordingName: filename, safeInfo: null, fileTextForHash: text });
    } finally {
        endOfflineDatasetLoad();
    }
}

/**
 * Descarga una grabación del servidor con la misma heurística que `loadRecordingFromServer`,
 * pero devuelve solo el dataset (para el panel replay live sin cambiar modo offline).
 */
async function fetchRecordingDatasetForLiveEmbed(filename) {
    if (!filename) return null;
    beginOfflineDatasetLoad();
    try {
        const meta = recordingsMetaByName.get(filename) || null;
        const sizeBytes = Number(meta && meta.size);
        const isPq = isRecordingParquetFilename(filename);
        const useSafe = isPq
            ? shouldUseSafeParquetLoad(meta, sizeBytes)
            : shouldUseSafeOfflineLoad(sizeBytes);
        if (useSafe) {
            let forceFull = false;
            if (!isPq) {
                try {
                    const previewBytes = Math.max(1, Math.floor(offlinePreviewMb * 1024 * 1024));
                    const rMeta = await fetch(`/api/recordings/${encodeURIComponent(filename)}?preview_bytes=${previewBytes}`);
                    if (rMeta.ok) {
                        const p = await rMeta.json();
                        const previewText = trimTextToFullLines(p && p.preview ? p.preview : "");
                        const risk = estimateTsvLoadRisk(previewText, sizeBytes || Number(p && p.size) || 0);
                        forceFull = shouldForceFullLoadWithConfirmation(
                            filename,
                            sizeBytes || Number(p && p.size) || 0,
                            risk.estRamBytes,
                        );
                    }
                } catch (e) {
                    /* seguir en modo seguro */
                }
            }
            if (forceFull && !isPq) {
                const rFull = await fetch("/api/recordings/" + encodeURIComponent(filename));
                if (!rFull.ok) throw new Error("No se pudo descargar la grabación");
                const textFull = await rFull.text();
                return parseTsvDataset(textFull, filename);
            }
            const safe = await loadLargeServerFileInSafeMode(filename, sizeBytes);
            return safe.ds;
        }
        if (isPq) {
            const rows = Number(meta && meta.rows);
            const rc = (Number.isFinite(rows) && rows > 0) ? Math.min(Math.floor(rows), 100000) : 20000;
            const r = await fetch(
                `/api/recordings/${encodeURIComponent(filename)}?preview_bytes=1&row_start=0&row_count=${Math.max(100, rc)}`,
            );
            if (!r.ok) throw new Error("No se pudo descargar Parquet");
            const payload = await r.json();
            if (!payload || !payload.offline) throw new Error("Respuesta Parquet inválida");
            return offlineDatasetFromParquetPayload(payload.offline, filename);
        }
        const r = await fetch("/api/recordings/" + encodeURIComponent(filename));
        if (!r.ok) throw new Error("No se pudo descargar la grabación");
        const text = await r.text();
        return parseTsvDataset(text, filename);
    } finally {
        endOfflineDatasetLoad();
    }
}

function discardLiveVarsCoalesce() {
    if (liveVarsCoalesceRafId) {
        cancelAnimationFrame(liveVarsCoalesceRafId);
        liveVarsCoalesceRafId = 0;
    }
    liveVarsCoalesceMap = null;
}

function flushCoalescedLiveVarsFromMap() {
    if (!liveVarsCoalesceMap || liveVarsCoalesceMap.size === 0) {
        liveVarsCoalesceMap = null;
        return;
    }
    const merged = Array.from(liveVarsCoalesceMap.values());
    liveVarsCoalesceMap = null;
    injectBrowserHeapTelemetryIntoVarsUpdate(merged);
    onVarsUpdate(merged);
}

function queueLiveVarsUpdateForFrame(data) {
    if (!Array.isArray(data)) return;
    if (!liveVarsCoalesceMap) liveVarsCoalesceMap = new Map();
    for (let i = 0; i < data.length; i++) {
        const item = data[i];
        if (item && item.name) liveVarsCoalesceMap.set(item.name, item);
    }
    if (liveVarsCoalesceRafId) return;
    liveVarsCoalesceRafId = requestAnimationFrame(() => {
        liveVarsCoalesceRafId = 0;
        flushCoalescedLiveVarsFromMap();
    });
}

function notifyWsConnected(thisId) {
    if (thisId !== connectionId) return;
    clearConnectionError();
    statusEl.textContent = (I18N[currentLang] || I18N.es).statusConnected;
    statusEl.className = "status connected";
    clearReconnectPending();
    lastAlarmsPayloadSent = "";
    lastReplayAlarmEngagedSent = null;
    sendUpdateRatio();
    sendMonitored();
    sendAlarmsToBackend();
    syncReplayAlarmEngagedToBackend();
    sendSendFileOnFinish();
    restorePendingGeneratorsIfPossible();
}

function dispatchIncomingWsString(thisId, rawData) {
    if (thisId !== connectionId) return;
    const now = Date.now();
    const size = typeof rawData === "string" ? new Blob([rawData]).size : 0;
    wsMessageBuffer.push({ t: now, size });
    const cutoff = now - WS_BUFFER_MAX_AGE_MS;
    while (wsMessageBuffer.length > 0 && wsMessageBuffer[0].t < cutoff) wsMessageBuffer.shift();
    let msg;
    try {
        msg = JSON.parse(rawData);
    } catch (e) {
        return;
    }
    if (msg.type === "error") {
        if (msg.message === "auth_required") {
            sessionStorage.removeItem("varmon_password");
            showAuthModal(msg.attempts_left, msg.attempt);
            return;
        }
        setConnectionError(msg.message);
        return;
    }
    clearConnectionError();
    if (msg.type === "vars_names") {
        if (statusEl && ws && ws.readyState === WebSocket.OPEN && !statusEl.classList.contains("connected")) {
            notifyWsConnected(connectionId);
        }
        onVarNames(msg.data);
    }
    else if (msg.type === "vars_update") {
        const pm = isPluginAppMode() ? getRegisteredAppModeMeta(appMode) : null;
        const pluginWantsStream = !!(pm && pm.needsBackendConnection);
        if (isLiveMode() || isArincRegistryMode() || pluginWantsStream) {
            queueLiveVarsUpdateForFrame(msg.data);
        } else {
            onVarsUpdate(msg.data);
        }
    }
    else if (msg.type === "set_result") onSetResult(msg);
    else if (msg.type === "alarm_triggered") onAlarmTriggeredFromBackend(msg.triggered);
    else if (msg.type === "alarm_cleared") onAlarmClearedFromBackend(msg.names);
    else if (msg.type === "recording_progress") onRecordingProgress(msg);
    else if (msg.type === "record_finished") onRecordFinished(msg);
    else if (msg.type === "alarm_recording_ready") onAlarmRecordingReady(msg);
}

function attachWsHandlers(socket, thisId) {
    socket.onopen = () => notifyWsConnected(thisId);
    socket.onclose = () => {
        if (thisId !== connectionId) return;
        discardLiveVarsCoalesce();
        ws = null;
        statusEl.textContent = (I18N[currentLang] || I18N.es).statusDisconnected;
        statusEl.className = "status disconnected";
        statusEl.title = lastConnectionError || "";
        isRecording = false;
        isRecordingStopping = false;
        pendingRecordingRestart = false;
        if (recordTimerInterval) { clearInterval(recordTimerInterval); recordTimerInterval = null; }
        if (recordBtn) {
            recordBtn.disabled = false;
            recordBtn.textContent = "\u25CF REC";
            recordBtn.classList.remove("recording");
        }
        if (recordTimerEl) recordTimerEl.style.display = "none";
        recordSizeBytes = 0;
    };
    socket.onerror = () => socket.close();
    socket.onmessage = (e) => {
        const raw = typeof e.data === "string" ? e.data : "";
        dispatchIncomingWsString(thisId, raw);
    };
}

function connect() {
    if (!hasBackendConnectionMode()) {
        setOfflineStatus();
        return;
    }
    const wantPath = effectiveUdsPathForWs();
    const wantNorm = wantPath ? wantPath : null;
    const pend = globalThis.__varmonWsPendingAdopt;
    if (pend && pend.socket) {
        const pendPath = pend.udsPath != null ? pend.udsPath : null;
        let pathsMatch = wantNorm === pendPath;
        if (!pathsMatch && pendPath == null && wantNorm != null && udsInstances.length > 0) {
            const u0 = udsInstances[0];
            if (u0 && u0.uds_path === wantNorm) pathsMatch = true;
        }
        const st = pend.socket.readyState;
        if (pathsMatch && st !== WebSocket.CLOSING && st !== WebSocket.CLOSED) {
            globalThis.__varmonWsPendingAdopt = undefined;
            connectionId += 1;
            const thisId = connectionId;
            ws = pend.socket;
            lastConnectUdsParam = wantNorm;
            pend.socket.onmessage = null;
            const buf = pend.messageBuffer || [];
            attachWsHandlers(pend.socket, thisId);
            for (let i = 0; i < buf.length; i++) {
                dispatchIncomingWsString(thisId, buf[i]);
            }
            buf.length = 0;
            if (pend.socket.readyState === WebSocket.OPEN) {
                /* Síncrono: si connect() se reentra antes de una microtarea, la guardia "ya OPEN" no debe dejar la UI en desconectado. */
                notifyWsConnected(thisId);
            }
            return;
        }
        try { pend.socket.close(); } catch (e) { /* ignore */ }
        globalThis.__varmonWsPendingAdopt = undefined;
    }

    if (ws && wantNorm === lastConnectUdsParam) {
        if (ws.readyState === WebSocket.OPEN) {
            if (statusEl && !statusEl.classList.contains("connected")) {
                notifyWsConnected(connectionId);
            }
            return;
        }
        if (ws.readyState === WebSocket.CONNECTING) {
            return;
        }
    }
    if (ws) {
        try { ws.close(); } catch (e) { /* ignore */ }
        ws = null;
    }
    connectionId += 1;
    const thisId = connectionId;
    const proto = location.protocol === "https:" ? "wss:" : "ws:";
    const path = effectiveUdsPathForWs();
    const qs = new URLSearchParams();
    if (path) qs.set("uds_path", path);
    lastConnectUdsParam = path ? path : null;
    const storedPass = sessionStorage.getItem("varmon_password");
    if (storedPass) qs.set("password", storedPass);
    const qp = qs.toString();
    const url = qp ? `${proto}//${location.host}/ws?${qp}` : `${proto}//${location.host}/ws`;
    const socket = new WebSocket(url);
    ws = socket;
    attachWsHandlers(socket, thisId);
}

function showAuthModal(attemptsLeft, attempt) {
    if (authOverlay) {
        const tr = I18N[currentLang] || I18N.es;
        const promptEl = document.getElementById("authPrompt");
        if (promptEl) {
            if (attempt !== undefined && attempt > 0) {
                if (attemptsLeft === 0)
                    promptEl.textContent = tr.authServerClosed || "El servidor se ha cerrado por seguridad.";
                else if (attemptsLeft === 1)
                    promptEl.textContent = tr.authLastAttempt || "Último intento. Si falla, el servidor se cerrará.";
                else
                    promptEl.textContent = (tr.authWrongAttempts || "Intentos restantes: %d de 3.").replace("%d", attemptsLeft);
            } else {
                promptEl.textContent = tr.authPrompt;
            }
        }
        authOverlay.style.display = "flex";
        if (authPasswordInput) {
            authPasswordInput.value = "";
            authPasswordInput.focus();
        }
    }
}

function hideAuthModal() {
    if (authOverlay) authOverlay.style.display = "none";
}

function setConnectionError(message) {
    lastConnectionError = message || null;
    if (statusEl) {
        statusEl.textContent = (message && message.length <= 60) ? message : ((I18N[currentLang] || I18N.es).statusDisconnected + (message ? ": " + message.substring(0, 50) + "…" : ""));
        statusEl.title = message || "";
    }
}

function clearConnectionError() {
    lastConnectionError = null;
    if (statusEl) statusEl.title = "";
}

function sendUpdateRatio() {
    sendWsAction({
        action: "set_update_ratio",
        value: parseInt(intervalInput.value, 10) || 5,
    });
}

intervalInput.addEventListener("change", () => { sendUpdateRatio(); saveConfig(); });

function sendMonitored() {
    const realNames = monitoredOrder.filter((n) => !isComputed(n) && !isArincDerivedName(n));
    sendWsAction({
        action: "set_monitored",
        names: realNames,
    });
    if (isLiveMode() && monitoredNames.size === 0) {
        clearLiveMonitorCachesWhenEmpty();
        rebuildMonitorList();
        schedulePlotRender();
        saveConfig();
    }
}

function ensureMonitoredName(name) {
    if (!name || monitoredNames.has(name)) return;
    monitoredNames.add(name);
    monitoredOrder.push(name);
    migratePlotPaneStateIfNeeded();
    const pids = getLivePlotLeafIds();
    if (pids.length > 0) syncPlotGlobalsMirror();
    appendNameToMonitorPaneOrders(name);
}

/** Plugins (p. ej. flight_viz) sin importar app-legacy: `detail: { names: string[] }`. */
document.addEventListener("varmonEnsureMonitored", (ev) => {
    const names = ev && ev.detail && ev.detail.names;
    if (!Array.isArray(names)) return;
    let changed = false;
    for (const raw of names) {
        const n = typeof raw === "string" ? raw.trim() : "";
        if (!n || monitoredNames.has(n)) continue;
        ensureMonitoredName(n);
        changed = true;
    }
    if (changed) {
        sendMonitored();
        /* rebuildMonitorList + saveConfig pueden bloquear el hilo varios cientos de ms; difiere para no congelar el primer frame del WS/plugins. */
        requestAnimationFrame(() => {
            rebuildMonitorList();
            saveConfig();
        });
    }
});

/** Plugins: reenviar ratio WS/SHM sin tocar config (p. ej. modo vuelo baja ratio temporalmente). */
document.addEventListener("varmonSendUpdateRatio", () => {
    sendUpdateRatio();
});

/** Plugins (p. ej. flight_viz): `detail.vars` = [{ name, value, var_type? }]. */
document.addEventListener("varmonPluginSetVars", (ev) => {
    const rowsIn = ev && ev.detail && ev.detail.vars;
    if (!Array.isArray(rowsIn) || rowsIn.length === 0) return;
    const rows = [];
    for (const r of rowsIn) {
        if (!r || typeof r !== "object") continue;
        const name = String(r.name || "").trim();
        if (!name) continue;
        const vd = varsByName[name];
        const vt =
            r.var_type ||
            (vd
                ? vd.type === "int32"
                    ? "int32"
                    : vd.type === "bool"
                      ? "bool"
                      : "double"
                : "double");
        let val = Number(r.value);
        if (!Number.isFinite(val)) continue;
        if (vt === "bool") val = val ? 1 : 0;
        else if (vt === "int32") val = Math.trunc(val) | 0;
        rows.push({ name, value: val, var_type: vt });
    }
    if (rows.length) sendWsAction({ action: "set_vars", vars: rows });
});

function ensureArincBaseMonitored(name) {
    if (!isArincDerivedName(name)) return;
    const base = getArincBaseName(name);
    if (base && knownVarNames.includes(base)) ensureMonitoredName(base);
}

function enforceArincMonitoringDependencies() {
    const current = monitoredOrder.slice();
    for (let i = 0; i < current.length; i++) {
        const n = current[i];
        if (!isArincDerivedName(n)) continue;
        const base = getArincBaseName(n);
        if (!base || monitoredNames.has(base)) continue;
        monitoredNames.add(base);
        monitoredOrder.unshift(base);
    }
}

function pruneArincDerivedFromMonitored() {
    const keep = [];
    for (let i = 0; i < monitoredOrder.length; i++) {
        const n = monitoredOrder[i];
        if (isArincDerivedName(n)) {
            monitoredNames.delete(n);
            continue;
        }
        keep.push(n);
    }
    monitoredOrder = keep;
}

function sendRefreshNames() {
    sendWsAction({ action: "refresh_names" });
}

refreshNamesBtn.addEventListener("click", sendRefreshNames);

function isArrayVar(name) {
    const vd = varsByName[name];
    return vd && vd.type === "array";
}

function isVarInTsv(name) {
    if (!name) return false;
    const idx = name.indexOf("[");
    const base = idx >= 0 && name.endsWith("]") ? name.substring(0, idx) : name;
    return varNamesInTsv.has(base);
}

/** Badge «TSV»: modo análisis (varNamesInTsv) o replay en vivo con referencia cargada. */
function shouldShowTsvBadgeForVariable(name) {
    if (isVarInTsv(name)) return true;
    return isLiveMode() && isVarInLiveReplayEmbed(name);
}

function formatValue(v, type, name) {
    if (type === "array") {
        if (Array.isArray(v)) return "[" + v.length + "]";
        return "[?]";
    }
    if (type === "bool") return v ? "true" : "false";
    if (typeof v !== "number") return String(v);
    if (isArincDerivedName(name)) {
        const m = /\.arinc\.(label|sdi|ssm|parity|data|value)$/.exec(String(name || ""));
        const suffix = m ? m[1] : "";
        if (suffix === "data") {
            return `0b${(Math.trunc(v) >>> 0).toString(2)}`;
        }
        if (suffix === "label" || suffix === "sdi" || suffix === "ssm" || suffix === "parity") {
            return String(Math.trunc(v));
        }
    }
    const f = name ? ensureVarFormatEntry(name) : undefined;
    const sal = f ? f.sal || "dec" : "dec";
    if (sal === "arinc429") {
        const pluginResult = fireHookChain("format_value_arinc", null, v, name, f);
        if (pluginResult !== null && pluginResult !== undefined) return pluginResult;
        const cfg = name ? getArincConfig(name) : { lsb: 1 };
        const d = decodeArinc429(v, cfg);
        const valueTxt = Number.isFinite(d.value) ? d.value.toFixed(3) : "NaN";
        const unitsTxt = d.units ? ` ${d.units}` : "";
        const baseFmt = `${valueTxt}${unitsTxt}`;
        const extra = fireHookChain("format_value_arinc_extras", baseFmt, d, v, name, f);
        return extra != null && extra !== undefined ? extra : baseFmt;
    }
    if (sal === "m1553") {
        const pluginResult = fireHookChain("format_value_m1553", null, v, name, f);
        if (pluginResult !== null && pluginResult !== undefined) return pluginResult;
        return decodeM1553FromVarName(name, v, m1553LabelRegistry);
    }
    if (f && inferVarFormatMode(f) === "units") {
        const phys = ensurePhysicalDefaults(f.physical);
        if (phys.category !== "none" && phys.category !== "numeric") {
            return formatValueWithPhysical(v, phys, sal);
        }
    }
    if (sal === "sci") return v.toExponential(4);
    if (sal === "hex") return "0x" + (Math.round(v) >>> 0).toString(16).toUpperCase();
    if (sal === "bin") return "0b" + (Math.round(v) >>> 0).toString(2);
    return v.toFixed(4);
}

function hslToHex(h, s, l) {
    const hue = ((Number(h) % 360) + 360) % 360;
    const sat = Math.max(0, Math.min(100, Number(s))) / 100;
    const lig = Math.max(0, Math.min(100, Number(l))) / 100;
    const c = (1 - Math.abs(2 * lig - 1)) * sat;
    const hp = hue / 60;
    const x = c * (1 - Math.abs((hp % 2) - 1));
    let r = 0, g = 0, b = 0;
    if (hp >= 0 && hp < 1) { r = c; g = x; b = 0; }
    else if (hp < 2) { r = x; g = c; b = 0; }
    else if (hp < 3) { r = 0; g = c; b = x; }
    else if (hp < 4) { r = 0; g = x; b = c; }
    else if (hp < 5) { r = x; g = 0; b = c; }
    else { r = c; g = 0; b = x; }
    const m = lig - c / 2;
    const toHex = (v) => {
        const n = Math.round((v + m) * 255);
        return Math.max(0, Math.min(255, n)).toString(16).padStart(2, "0");
    };
    return "#" + toHex(r) + toHex(g) + toHex(b);
}

function ensureSeriesColor(name, forceNew = false) {
    const key = String(name || "").trim();
    if (!key) return TRACE_COLORS[0];
    if (!forceNew && seriesColorByName[key]) return seriesColorByName[key];
    if (forceNew) {
        delete seriesColorByName[key];
        delete seriesHueByName[key];
    }
    const usedHues = Object.entries(seriesHueByName)
        .filter(([n]) => n !== key)
        .map(([, h]) => Number(h))
        .filter((h) => Number.isFinite(h));
    let pickedHue = null;
    for (let i = 0; i < 80; i++) {
        const h = Math.floor(Math.random() * 360);
        const farEnough = usedHues.every((uh) => {
            const d = Math.abs(h - uh);
            return Math.min(d, 360 - d) >= 22;
        });
        if (!farEnough) continue;
        pickedHue = h;
        break;
    }
    if (!Number.isFinite(pickedHue)) {
        pickedHue = Math.floor(Math.random() * 360);
    }
    const color = hslToHex(pickedHue, 78, 58);
    seriesColorByName[key] = color;
    seriesHueByName[key] = pickedHue;
    return color;
}

function getSeriesColor(name) {
    return ensureSeriesColor(name, false);
}

// --- History polling ---

function isArrayElem(name) { return name.includes("[") && name.endsWith("]"); }

function getArrayElemValue(eName) {
    const br = eName.lastIndexOf("[");
    const arrName = eName.substring(0, br);
    const idx = parseInt(eName.substring(br + 1));
    const vd = varsByName[arrName];
    if (!vd || !Array.isArray(vd.value) || idx >= vd.value.length) return undefined;
    return vd.value[idx];
}

// --- Column 1: Variable browser (tree view) ---

let collapsedGroups = new Set();
let treeInitialized = false;
let groupVariables = false; // por defecto lista plana sin categorías
/** Lista plana virtual solo sin agrupar; con agrupar se usa árbol hasta un techo de hojas. */
const BROWSER_FLAT_VIRTUAL_MIN = 350;
const BROWSER_GROUP_MAX_LEAVES = 8000;

function buildTree(names) {
    const root = { _children: new Map(), _leaves: [] };
    for (const name of names) {
        const parts = name.split(".");
        let node = root;
        for (let i = 0; i < parts.length - 1; i++) {
            if (!node._children.has(parts[i])) {
                node._children.set(parts[i], { _children: new Map(), _leaves: [] });
            }
            node = node._children.get(parts[i]);
        }
        node._leaves.push(name);
    }
    return root;
}

function collectLeaves(node) {
    const result = [];
    for (const name of node._leaves) result.push(name);
    for (const child of node._children.values()) {
        result.push(...collectLeaves(child));
    }
    return result;
}

function collectGroupPaths(node, prefix, out) {
    for (const [key, child] of node._children) {
        const fullPath = prefix ? prefix + "." + key : key;
        out.push(fullPath);
        collectGroupPaths(child, fullPath, out);
    }
}

function collapseAll() {
    const tree = buildTree(knownVarNames);
    const paths = [];
    collectGroupPaths(tree, "", paths);
    paths.forEach(p => collapsedGroups.add(p));
    renderBrowserList();
}

function expandAll() {
    collapsedGroups.clear();
    renderBrowserList();
}

function renderBrowserList() {
    const filterText = varFilter.value;
    const filtered = knownVarNames.filter(n => nameMatchesFilter(n, filterText));
    if (groupVariables && filtered.length > BROWSER_GROUP_MAX_LEAVES) {
        if (groupVarsCheckbox) {
            groupVarsCheckbox.title = (currentLang === "en")
                ? "Too many matches: narrow the filter to use grouping."
                : "Demasiadas coincidencias: reduce el filtro para usar agrupación.";
            groupVarsCheckbox.checked = false;
        }
        groupVariables = false;
        const cAll = document.getElementById("collapseAll");
        const eAll = document.getElementById("expandAll");
        if (cAll) cAll.style.display = "none";
        if (eAll) eAll.style.display = "none";
        renderBrowserListVirtualFlat(filtered);
        browserVirtualEnabled = true;
        return;
    }
    // Sin agrupar y muchas coincidencias: lista virtual plana (evita miles de nodos DOM).
    if (filtered.length > BROWSER_FLAT_VIRTUAL_MIN && !groupVariables) {
        if (groupVarsCheckbox) groupVarsCheckbox.title = "";
        renderBrowserListVirtualFlat(filtered);
        browserVirtualEnabled = true;
        return;
    }
    if (groupVarsCheckbox) groupVarsCheckbox.title = "";
    browserVirtualEnabled = false;
    let tree = buildTree(filtered);

    if (groupVariables) {
        if (!treeInitialized && knownVarNames.length > 0) {
            treeInitialized = true;
        }
    } else {
        // Lista plana: mismo árbol pero sin grupos, solo hojas en la raíz
        tree = { _children: new Map(), _leaves: filtered.slice().sort() };
    }

    const frag = document.createDocumentFragment();
    renderTreeNode(frag, tree, "", 0);

    varBrowserList.innerHTML = "";
    varBrowserList.appendChild(frag);
    browserListDirty = false;
}

function renderBrowserListVirtualFlat(filteredOverride) {
    if (filteredOverride != null) {
        browserVirtualRows = filteredOverride.slice().sort();
    }
    const rows = browserVirtualRows;
    const rowH = browserVirtualRowPx;
    const viewH = Math.max(120, varBrowserList.clientHeight || 420);
    const scrollTop = varBrowserList.scrollTop || 0;
    const from = Math.max(0, Math.floor(scrollTop / rowH) - browserVirtualOverscan);
    const maxCount = Math.ceil(viewH / rowH) + browserVirtualOverscan * 2;
    const to = Math.min(rows.length, from + maxCount);

    const root = document.createElement("div");
    root.className = "browser-virtual-window";

    const topSpacer = document.createElement("div");
    topSpacer.className = "browser-virtual-spacer";
    topSpacer.style.height = `${from * rowH}px`;
    root.appendChild(topSpacer);

    for (let i = from; i < to; i++) {
        const name = rows[i];
        const inMonitor = monitoredNames.has(name);
        const selected = browserSelection.has(name);
        const el = document.createElement("div");
        el.className = "var-list-item" + (selected ? " selected" : "") + (inMonitor ? " in-monitor" : "");
        el.style.paddingLeft = "8px";
        el.style.height = `${rowH}px`;
        el.style.display = "flex";
        el.style.alignItems = "center";
        el.draggable = true;
        el.addEventListener("dragstart", (e) => {
            noteMonitorDragStart(name);
            e.dataTransfer.setData("text/plain", name);
            e.dataTransfer.setData("application/x-var-name", name);
            e.dataTransfer.effectAllowed = "copy";
            ensureNewGraphDropTarget();
        });
        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.checked = selected;
        cb.disabled = inMonitor;
        el.appendChild(cb);
        if (shouldShowTsvBadgeForVariable(name)) {
            const tsvBadge = document.createElement("span");
            tsvBadge.className = "var-tsv-badge";
            tsvBadge.textContent = "TSV";
            const trB = I18N[currentLang] || I18N.es;
            tsvBadge.title = isVarInTsv(name)
                ? (trB.varTsvBadgeTitleRecording || "Variable en la grabación TSV cargada")
                : (trB.varTsvBadgeTitleLiveReplay || "Variable presente en la grabación de referencia (replay en vivo)");
            el.appendChild(tsvBadge);
        }
        const label = document.createElement("span");
        label.className = "tree-leaf-name";
        label.textContent = name;
        label.title = name;
        el.appendChild(label);
        if (varsByName[name] && varsByName[name].type === "array") {
            const arrBdg = document.createElement("span");
            arrBdg.className = "array-badge-browser";
            const vv = varsByName[name].value;
            arrBdg.textContent = Array.isArray(vv) ? "[" + vv.length + "]" : "[ ]";
            el.appendChild(arrBdg);
        } else if (isArincDerivedName(name)) {
            const arincBdg = document.createElement("span");
            arincBdg.className = "arinc-badge-browser";
            arincBdg.textContent = "ARINC";
            el.appendChild(arincBdg);
        }
        if (!inMonitor) {
            el.addEventListener("click", (e) => {
                if (e.target === cb) {
                    if (cb.checked) browserSelection.add(name); else browserSelection.delete(name);
                } else {
                    if (browserSelection.has(name)) browserSelection.delete(name); else browserSelection.add(name);
                }
                renderBrowserListVirtualFlat();
            });
        }
        root.appendChild(el);
    }

    const bottomSpacer = document.createElement("div");
    bottomSpacer.className = "browser-virtual-spacer";
    bottomSpacer.style.height = `${Math.max(0, (rows.length - to) * rowH)}px`;
    root.appendChild(bottomSpacer);

    varBrowserList.innerHTML = "";
    varBrowserList.appendChild(root);
    if (!varBrowserList._virtualScrollHooked) {
        varBrowserList._virtualScrollHooked = true;
        varBrowserList.addEventListener("scroll", () => {
            if (!browserVirtualEnabled) return;
            if (!browserVirtualScrollPending) {
                browserVirtualScrollPending = true;
                requestAnimationFrame(() => {
                    browserVirtualScrollPending = false;
                    if (browserVirtualEnabled) renderBrowserListVirtualFlat();
                });
            }
        }, { passive: true });
    }
    browserListDirty = false;
}

function renderTreeNode(parent, node, prefix, depth) {
    if (!groupVariables && depth > 0) return; // en modo plano solo pintamos las hojas de la raíz
    const sortedGroups = Array.from(node._children.keys()).sort();
    for (const key of sortedGroups) {
        const child = node._children.get(key);
        const fullPath = prefix ? prefix + "." + key : key;
        const allLeaves = collectLeaves(child);
        const leafCount = allLeaves.length;
        const isCollapsed = collapsedGroups.has(fullPath);

        const allSelected = allLeaves.every(n => browserSelection.has(n) || monitoredNames.has(n));
        const someSelected = allLeaves.some(n => browserSelection.has(n));

        const groupEl = document.createElement("div");
        groupEl.className = "var-tree-group";
        groupEl.style.paddingLeft = (depth * 16 + 8) + "px";

        const arrow = document.createElement("span");
        arrow.className = "tree-arrow" + (isCollapsed ? " collapsed" : "");
        arrow.textContent = isCollapsed ? "\u25B6" : "\u25BC";
        arrow.addEventListener("click", (e) => {
            e.stopPropagation();
            if (collapsedGroups.has(fullPath)) collapsedGroups.delete(fullPath);
            else collapsedGroups.add(fullPath);
            renderBrowserList();
        });

        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.checked = allSelected;
        cb.indeterminate = !allSelected && someSelected;
        cb.addEventListener("click", (e) => {
            e.stopPropagation();
            if (cb.checked) {
                allLeaves.forEach(n => { if (!monitoredNames.has(n)) browserSelection.add(n); });
            } else {
                allLeaves.forEach(n => browserSelection.delete(n));
            }
            renderBrowserList();
        });

        const label = document.createElement("span");
        label.className = "tree-group-label";
        label.textContent = key;

        const count = document.createElement("span");
        count.className = "tree-group-count";
        count.textContent = leafCount;

        groupEl.appendChild(arrow);
        groupEl.appendChild(cb);
        groupEl.appendChild(label);
        groupEl.appendChild(count);

        groupEl.addEventListener("click", () => {
            if (collapsedGroups.has(fullPath)) collapsedGroups.delete(fullPath);
            else collapsedGroups.add(fullPath);
            renderBrowserList();
        });

        parent.appendChild(groupEl);

        if (!isCollapsed) {
            renderTreeNode(parent, child, fullPath, depth + 1);
        }
    }

    const sortedLeaves = node._leaves.slice().sort();
    for (const name of sortedLeaves) {
        const inMonitor = monitoredNames.has(name);
        const selected = browserSelection.has(name);
        const leafName = groupVariables ? name.split(".").pop() : name;

        const el = document.createElement("div");
        el.className = "var-list-item" +
            (selected ? " selected" : "") +
            (inMonitor ? " in-monitor" : "");
        el.style.paddingLeft = (depth * 16 + 8) + "px";

        // Drag & drop: permitir arrastrar variables desde Columna 1 a Columna 2
        el.draggable = true;
        el.addEventListener("dragstart", (e) => {
            noteMonitorDragStart(name);
            e.dataTransfer.setData("text/plain", name);
            e.dataTransfer.setData("application/x-var-name", name);
            e.dataTransfer.effectAllowed = "copy";
            ensureNewGraphDropTarget();
        });

        const cb = document.createElement("input");
        cb.type = "checkbox";
        cb.checked = selected;
        cb.disabled = inMonitor;

        el.appendChild(cb);
        if (shouldShowTsvBadgeForVariable(name)) {
            const tsvBadge = document.createElement("span");
            tsvBadge.className = "var-tsv-badge";
            tsvBadge.textContent = "TSV";
            const trB = I18N[currentLang] || I18N.es;
            tsvBadge.title = isVarInTsv(name)
                ? (trB.varTsvBadgeTitleRecording || "Variable en la grabación TSV cargada")
                : (trB.varTsvBadgeTitleLiveReplay || "Variable presente en la grabación de referencia (replay en vivo)");
            el.appendChild(tsvBadge);
        }
        const label = document.createElement("span");
        label.className = "tree-leaf-name";
        label.textContent = leafName;
        label.title = name;

        el.appendChild(label);

        if (varsByName[name] && varsByName[name].type === "array") {
            const arrBdg = document.createElement("span");
            arrBdg.className = "array-badge-browser";
            const vv = varsByName[name].value;
            arrBdg.textContent = Array.isArray(vv) ? "[" + vv.length + "]" : "[ ]";
            el.appendChild(arrBdg);
        } else if (isArincDerivedName(name)) {
            const arincBdg = document.createElement("span");
            arincBdg.className = "arinc-badge-browser";
            arincBdg.textContent = "ARINC";
            el.appendChild(arincBdg);
        }

        if (!inMonitor) {
            el.addEventListener("click", (e) => {
                if (e.target === cb) {
                    if (cb.checked) browserSelection.add(name);
                    else browserSelection.delete(name);
                } else {
                    if (browserSelection.has(name)) browserSelection.delete(name);
                    else browserSelection.add(name);
                }
                renderBrowserList();
            });
        }
        parent.appendChild(el);
    }
}

varFilter.addEventListener("input", renderBrowserList);

const groupVarsCheckbox = document.getElementById("groupVarsCheckbox");
const collapseAllBtn = document.getElementById("collapseAll");
const expandAllBtn = document.getElementById("expandAll");
groupVarsCheckbox.addEventListener("change", () => {
    groupVariables = groupVarsCheckbox.checked;
    collapseAllBtn.style.display = groupVariables ? "" : "none";
    expandAllBtn.style.display = groupVariables ? "" : "none";
    if (groupVariables) {
        collapseAll();
        return;
    }
    collapsedGroups.clear();
    renderBrowserList();
});
groupVarsCheckbox.checked = groupVariables;
collapseAllBtn.style.display = groupVariables ? "" : "none";
expandAllBtn.style.display = groupVariables ? "" : "none";

collapseAllBtn.addEventListener("click", collapseAll);
expandAllBtn.addEventListener("click", expandAll);

selectAllBtn.addEventListener("click", () => {
    knownVarNames.forEach(name => {
        if (!monitoredNames.has(name) && nameMatchesFilter(name, varFilter.value))
            browserSelection.add(name);
    });
    renderBrowserList();
});

selectNoneBtn.addEventListener("click", () => {
    browserSelection.clear();
    renderBrowserList();
});

addToMonitorBtn.addEventListener("click", () => {
    browserSelection.forEach(name => {
        ensureArincBaseMonitored(name);
        ensureMonitoredName(name);
    });
    browserSelection.clear();
    sendMonitored();
    saveConfig();
    renderBrowserList();
    rebuildMonitorList();
    if (isPlaybackMode() && offlineDataset) {
        const tNow = Number.isFinite(offlinePlayback.currentTs) ? offlinePlayback.currentTs : offlineDataset.minTs;
        applyOfflineTime(tNow);
    }
    updateMonitorValues();
});

// --- Column 2: Monitored variables ---

function computeStats(name) {
    const hist = historyCache[name];
    if (!hist || !hist.values || hist.values.length < 2) return null;
    const vals = hist.values;
    const n = vals.length;
    let min = Infinity, max = -Infinity;
    for (let i = 0; i < n; i++) {
        const v = vals[i];
        if (v < min) min = v;
        if (v > max) max = v;
    }
    return { min, max, count: n };
}

function nameMatchesFilter(name, filterText) {
    const t = (filterText || "").trim().toLowerCase();
    if (!t) return true;
    const parts = t.split(/\s+/).filter(Boolean);
    const requireTsv = parts.includes("tsv");
    const nameParts = parts.filter(p => p !== "tsv");
    if (requireTsv && !isVarInTsv(name)) return false;
    const nameLower = (name || "").toLowerCase();
    if (nameParts.length === 0) return true;
    return nameParts.every(p => nameLower.includes(p));
}

function getVisibleMonitorNames() {
    return monitoredOrder.filter(n => nameMatchesFilter(n, monitorFilterText));
}

function hasActiveDeltaMarkers() {
    return Number.isFinite(markerA) && Number.isFinite(markerB);
}

function isDeltaChangedForName(name) {
    const d = deltaByName[name];
    return Number.isFinite(d) && Math.abs(d) > 1e-9;
}

function getMonitorRenderOrder() {
    const order = monitoredOrder.slice();
    if (!hasActiveDeltaMarkers()) return order;
    order.sort((a, b) => {
        const aChanged = isDeltaChangedForName(a);
        const bChanged = isDeltaChangedForName(b);
        if (aChanged && !bChanged) return -1;
        if (!aChanged && bChanged) return 1;
        if (aChanged && bChanged) {
            const da = Math.abs(deltaByName[a] || 0);
            const db = Math.abs(deltaByName[b] || 0);
            if (db !== da) return db - da;
        }
        return 0;
    });
    return order;
}

function getVisibleMonitorRenderOrder() {
    return getMonitorRenderOrder().filter(n => nameMatchesFilter(n, monitorFilterText));
}

function buildGraphSelectOptions() {
    let html = '<option value="">—</option>';
    graphList.forEach((gid, idx) => {
        html += `<option value="${gid}">G${idx + 1}</option>`;
    });
    if (graphList.length < MAX_GRAPHS) {
        html += '<option value="__new__">+ Nuevo</option>';
    }
    return html;
}

function syncMonitorImpositionVisual(wrap, name) {
    if (!wrap) return;
    const isReplayImposing = isReplayMode() && isVarInTsv(name) && impositionNames.has(name);
    const isLiveEmbedImposing = isLiveMode() && liveReplayEmbedImposeNames.has(name);
    const isImposing = isReplayImposing || isLiveEmbedImposing;
    wrap.classList.toggle("monitor-item-imposing", isImposing);
    const rowEl = wrap.querySelector(".monitor-item");
    if (!rowEl) return;
    let badge = rowEl.querySelector(".mon-impose-badge");
    if (!badge) {
        badge = document.createElement("span");
        badge.className = "mon-impose-badge";
        badge.textContent = "IMP";
        const nameNode = rowEl.querySelector(".mon-name");
        if (nameNode) rowEl.insertBefore(badge, nameNode);
        else rowEl.appendChild(badge);
    }
    badge.title = isLiveEmbedImposing && !isReplayImposing
        ? "Imposición desde replay en vivo (referencia TSV → SHM)"
        : "Imponiendo valor desde TSV a SHM";
    badge.style.display = isImposing ? "inline-flex" : "none";
}

function shouldUseMonitorVirtualList() {
    if (countLiveWidget("monitor") > 1) return false;
    return getVisibleMonitorNames().length >= MONITOR_VM_THRESHOLD;
}

/**
 * Panel de detalle (stats/ARINC): en 1 columna sin lista virtual va al dock junto a gráficos.
 * Con 2+ columnas el detalle va inline en cada fila — salvo en lista virtual, donde las filas
 * no son estables en el DOM y el detalle debe seguir en el dock (updateStatsPanel(null, …)).
 */
function monitorDetailPanelUsesDock() {
    if (shouldUseMonitorVirtualList()) return true;
    return monitorColumnsCount <= 1;
}

function getMonitorDetailDockEl() {
    return document.getElementById("monitorDetailDock");
}

function hideMonitorDetailDock() {
    const dock = getMonitorDetailDockEl();
    if (!dock) return;
    dock.style.display = "none";
    dock.innerHTML = "";
    delete dock.dataset.detailFor;
}

/** Con lista virtual solo puede haber un detalle abierto (panel en zona de gráficos). */
function getDockedExpandedVarName() {
    if (expandedStats.size === 0) return null;
    return expandedStats.values().next().value;
}

function refreshDockedStatsAfterVirtualSync() {
    if (!monitorListEl || !monitorListEl.classList.contains("monitor-list--virtual")) return;
    const nm = getDockedExpandedVarName();
    if (nm) updateStatsPanel(null, nm);
}

function destroyMonitorVirtualShell() {
    if (!monitorListEl.classList.contains("monitor-list--virtual")) return;
    if (monitorVmScrollRaf) {
        cancelAnimationFrame(monitorVmScrollRaf);
        monitorVmScrollRaf = 0;
    }
    monitorListEl.innerHTML = "";
    monitorListEl.classList.remove("monitor-list--virtual");
    monitorListEl.style.removeProperty("--monitor-vm-row-h");
    delete monitorListEl._vmRowFrozen;
    monitorVmTopSpacer = null;
    monitorVmRows = null;
    monitorVmBottomSpacer = null;
}

function ensureMonitorVirtualShell() {
    if (monitorListEl.classList.contains("monitor-list--virtual") && monitorVmRows && monitorVmRows.parentNode === monitorListEl) {
        return;
    }
    monitorListEl._vmRowFrozen = false;
    monitorListEl.innerHTML = "";
    monitorListEl.classList.add("monitor-list--virtual");
    monitorVmTopSpacer = document.createElement("div");
    monitorVmTopSpacer.className = "monitor-vm-spacer monitor-vm-spacer-top";
    monitorVmRows = document.createElement("div");
    monitorVmRows.className = "monitor-vm-rows";
    monitorVmBottomSpacer = document.createElement("div");
    monitorVmBottomSpacer.className = "monitor-vm-spacer monitor-vm-spacer-bottom";
    monitorListEl.appendChild(monitorVmTopSpacer);
    monitorListEl.appendChild(monitorVmRows);
    monitorListEl.appendChild(monitorVmBottomSpacer);
}

/**
 * Altura de fila para la VM: debe ser estable entre ticks de scroll; si cambia en cada sync
 * (primera fila distinta, ResizeObserver, etc.) el scroll se vuelve “acelerado” o asimétrico.
 */
function measureMonitorVmRowHeightFromSlice(force) {
    if (!monitorVmRows || !monitorListEl) return;
    if (!force && monitorListEl._vmRowFrozen) return;
    /*
     * Medir solo .monitor-item (contenido natural). El .monitor-item-wrap estira al alto del grid
     * (--monitor-vm-row-h), así que su offsetHeight era casi el stride anterior + bucle +2px hasta 80.
     */
    let maxH = 0;
    monitorVmRows.querySelectorAll(".monitor-item").forEach((el) => {
        const h = el.offsetHeight;
        if (h > maxH) maxH = h;
    });
    if (maxH > 0) {
        /* stride = contenido + hueco entre filas; scrollTop/spacers usan el mismo valor que height de fila. */
        monitorVmRowPx = Math.max(28, Math.min(56, Math.ceil(maxH) + MONITOR_VM_ROW_GAP));
        monitorListEl._vmRowFrozen = true;
        monitorListEl.style.setProperty("--monitor-vm-row-h", monitorVmRowPx + "px");
    }
}

function updateMonitorRowWrap(wrap, name) {
    wrap.classList.toggle("monitor-item-selected", monitorSelectedNames.has(name));
    const hasMarkers = hasActiveDeltaMarkers();
    const changed = hasMarkers && isDeltaChangedForName(name);
    wrap.classList.toggle("monitor-item-delta-changed", changed);
    wrap.classList.toggle("monitor-item-delta-unchanged", hasMarkers && !changed);
    if (!wrap._selectionClickAttached) {
        wrap._selectionClickAttached = true;
        wrap.addEventListener("click", (e) => {
            if (e.target.closest(".btn-mon-remove") || e.target.closest(".monitor-impose-wrap")) return;
            if (e.target.closest(".mon-value") || e.target.closest(".mon-edit-input") || e.target.closest(".mon-edit-actions")) return;
            if (monitorSelectedNames.has(name)) monitorSelectedNames.delete(name);
            else monitorSelectedNames.add(name);
            rebuildMonitorList();
        });
    }
    const nameSpan = wrap.querySelector(".mon-name");
    if (nameSpan) {
        nameSpan.textContent = formatNameWithHiddenLevels(name, hideLevels);
    }
    syncMonitorImpositionVisual(wrap, name);
    if (isReplayMode() && !isArrayVar(name) && isVarInTsv(name)) {
        const rowEl = wrap.querySelector(".monitor-item");
        let imposeWrap = wrap.querySelector(".monitor-impose-wrap");
        if (!imposeWrap && rowEl) {
            imposeWrap = document.createElement("span");
            imposeWrap.className = "monitor-impose-wrap";
            const lab = document.createElement("label");
            const cb = document.createElement("input");
            cb.type = "checkbox";
            cb.className = "monitor-impose-cb";
            cb.title = "Imponer a SHM (replay)";
            cb.addEventListener("change", (e) => {
                e.stopPropagation();
                const checked = cb.checked;
                const toApply = monitorSelectedNames.size && monitorSelectedNames.has(name) ? [...monitorSelectedNames] : [name];
                toApply.forEach(n => {
                    if (checked) impositionNames.add(n);
                    else impositionNames.delete(n);
                    syncReplayTsvHistoryForName(n);
                });
                saveConfig();
                rebuildMonitorList();
            });
            lab.appendChild(cb);
            imposeWrap.appendChild(lab);
            rowEl.insertBefore(imposeWrap, rowEl.querySelector(".mon-name"));
        }
        const cb = imposeWrap && imposeWrap.querySelector(".monitor-impose-cb");
        if (cb) cb.checked = impositionNames.has(name);
    } else {
        const imposeWrap = wrap.querySelector(".monitor-impose-wrap");
        if (imposeWrap) imposeWrap.remove();
    }
    const rowForTags = wrap.querySelector(".monitor-item");
    if (rowForTags && name !== editingName) syncMonitorRowStatusTags(rowForTags, name);
    if (rowForTags) refreshMonitorItemDisplayedValue(rowForTags, name);
}

/** Refresca .mon-value (y badge de array) según cfg actual; necesario al reutilizar filas DOM sin nuevo dato SHM. */
function refreshMonitorItemDisplayedValue(monitorItemEl, name) {
    if (!monitorItemEl || name === editingName) return;
    const monVal = monitorItemEl.querySelector(".mon-value");
    if (!monVal) return;
    const vd = varsByName[name];
    let usedHistory = false;
    if (isPlaybackMode() && offlineRecordingName && isVarInTsv(name) && impositionNames.has(name)) {
        const tNow = Number.isFinite(offlinePlayback.currentTs) ? offlinePlayback.currentTs : null;
        if (tNow != null) {
            const vHist = getReplayImposedValueAtTs(name, tNow);
            if (vHist != null) {
                monVal.textContent = formatValue(vHist, "double", name);
                usedHistory = true;
            }
        }
    }
    // En modo seguro (offline): el tramo inicial cargado puede no cubrir currentTs.
    // Si tenemos histórico reciente en historyCache, preferimos ese valor para actualizar el monitor.
    if (!usedHistory
        && isPlaybackMode()
        && offlineNeedsServerWindowFetch()
        && offlineRecordingName
        && vd
        && vd.type !== "bool"
        && !Array.isArray(vd.value)
    ) {
        const tNow = Number.isFinite(offlinePlayback.currentTs) ? offlinePlayback.currentTs : null;
        if (tNow != null) {
            const hist = historyCache[name];
            const vHist = getValueAtTs(hist, tNow);
            if (vHist != null) {
                monVal.textContent = formatValue(vHist, vd.type, name);
                usedHistory = true;
            }
        }
    }
    if (vd && !usedHistory) {
        monVal.textContent = formatValue(vd.value, vd.type, name);
        const arrBadge = monitorItemEl.querySelector(".array-badge");
        if (arrBadge && Array.isArray(vd.value)) {
            arrBadge.textContent = "[" + vd.value.length + "]";
        }
    }
}

function hasScalarFormatConversion(name) {
    const vf = varFormat[name];
    if (!vf || typeof vf !== "object") return false;
    if (inferVarFormatMode(vf) !== "units") return false;
    const o = vf.ori || "dec";
    const s = vf.sal || "dec";
    return o !== s;
}

function hasPhysicalUnitConversion(name) {
    const vf = varFormat[name];
    if (!vf || typeof vf !== "object") return false;
    if (inferVarFormatMode(vf) !== "units") return false;
    const p = ensurePhysicalDefaults(vf.physical);
    return p.category !== "none" && p.category !== "numeric";
}

function syncMonitorRowStatusTags(rowEl, name) {
    if (!rowEl || !name) return;
    let box = rowEl.querySelector(".mon-status-tags");
    if (!box) {
        box = document.createElement("span");
        box.className = "mon-status-tags";
        const nameEl = rowEl.querySelector(".mon-name");
        if (nameEl) rowEl.insertBefore(box, nameEl);
        else rowEl.appendChild(box);
    }
    box.innerHTML = "";
    function addTag(suffix, text, title) {
        const s = document.createElement("span");
        s.className = "mon-tag mon-tag--" + suffix;
        s.textContent = text;
        if (title) s.title = title;
        box.appendChild(s);
    }
    if (hasScalarFormatConversion(name) && !isArincEnabled(name) && !isArincDerivedName(name) && !isM1553Enabled(name)) {
        addTag("units", "units", currentLang === "en" ? "Ori/sal display conversion" : "Conversión de formato ori→sal");
    }
    if (hasPhysicalUnitConversion(name) && !isArincDerivedName(name) && !isM1553Enabled(name)) {
        addTag("phys", "u", currentLang === "en" ? "Physical unit conversion on display" : "Conversión de unidades físicas (monitor)");
    }
    if (activeGenerators[name]) {
        addTag("gen", "gen", currentLang === "en" ? "Signal generator active" : "Generador activo");
    }
    if (alarms[name]) {
        addTag("alarm", "alarm", currentLang === "en" ? "Alarm configured" : "Alarma configurada");
    }
    if (isArincDerivedName(name)) {
        addTag("arinc-virt", "ARINC", currentLang === "en" ? "Derived ARINC subchannel" : "Subcanal ARINC derivado (virtual)");
    } else if (isArincEnabled(name)) {
        addTag("arinc", "ARINC", currentLang === "en" ? "ARINC 429 word" : "Palabra ARINC 429");
        const vd = varsByName[name];
        const cfg = getArincConfig(name);
        if (vd && typeof vd.value === "number" && Number.isFinite(Number(vd.value)) && !(cfg.encodingOverride || "").trim()) {
            try {
                const dec = decodeArinc429(vd.value, cfg);
                if (dec && dec.userRegistryHit) {
                    const tr = I18N[currentLang] || I18N.es;
                    addTag(
                        "reg-avionica",
                        "BD",
                        tr.arincRegMatchTagTitle || "Enc: auto; definición tomada del reg. aviónica importado"
                    );
                }
            } catch (e) { /* ignore */ }
        }
    } else if (isM1553Enabled(name)) {
        const tr = I18N[currentLang] || I18N.es;
        addTag("m1553", "1553", tr.m1553TagTitle || "Palabra MIL-STD-1553");
        const parsed = parseM1553VarName(name);
        if (parsed && findM1553Definition(m1553LabelRegistry, parsed.rt, parsed.wordKind, parsed.suffix)) {
            addTag(
                "reg-avionica",
                "BD",
                tr.m1553RegMatchTagTitle || "Definición en el registro MIL-STD-1553 activo"
            );
        }
    }
    if (shouldShowTsvBadgeForVariable(name)) {
        const tr = I18N[currentLang] || I18N.es;
        addTag(
            "tsv",
            "TSV",
            isVarInTsv(name)
                ? (tr.varTsvBadgeTitleRecording || "Variable en la grabación TSV cargada")
                : (tr.varTsvBadgeTitleLiveReplay || "Variable presente en la grabación de referencia (replay en vivo)"),
        );
    }
    box.style.display = box.childElementCount ? "inline-flex" : "none";
}

function openReplayAlarmConfigurator(name) {
    if (!name || !isReplayMode()) return;
    if (!expandedStats.has(name)) {
        expandedStats.add(name);
        rebuildMonitorList();
    }
    const useDock = monitorListEl && monitorDetailPanelUsesDock();
    requestAnimationFrame(() => {
        if (useDock) {
            updateStatsPanel(null, name);
        } else {
            const w = monitorListEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(name)}"]`);
            if (!w) return;
            updateStatsPanel(w, name);
        }
        requestAnimationFrame(() => {
            const root = useDock ? getMonitorDetailDockEl() : monitorListEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(name)}"]`);
            const addBtn = root && root.querySelector ? root.querySelector(".alarm-row .btn-alarm-add") : null;
            if (addBtn) addBtn.click();
        });
    });
}

function createMonitorRowWrap(name) {
    const wrap = document.createElement("div");
    wrap.className = "monitor-item-wrap";
    wrap.dataset.name = name;
    if (monitorSelectedNames.has(name)) wrap.classList.add("monitor-item-selected");
    if (hasActiveDeltaMarkers()) {
        if (isDeltaChangedForName(name)) wrap.classList.add("monitor-item-delta-changed");
        else wrap.classList.add("monitor-item-delta-unchanged");
    }
    wrap.addEventListener("click", (e) => {
        if (e.target.closest(".btn-mon-remove") || e.target.closest(".monitor-impose-wrap")) return;
        if (e.target.closest(".mon-value") || e.target.closest(".mon-edit-input") || e.target.closest(".mon-edit-actions")) return;
        if (monitorSelectedNames.has(name)) monitorSelectedNames.delete(name);
        else monitorSelectedNames.add(name);
        rebuildMonitorList();
    });

    const el = document.createElement("div");
    el.className = "monitor-item";
    el.dataset.name = name;

    el.draggable = true;
    el.addEventListener("dragstart", (e) => {
        if (!e.dataTransfer) return;
        noteMonitorDragStart(name);
        e.dataTransfer.setData("text/plain", name);
        e.dataTransfer.setData("application/x-var-name", name);
        e.dataTransfer.setData("application/x-monitor-reorder", name);
        e.dataTransfer.effectAllowed = "copyMove";
        ensureNewGraphDropTarget();
    });
    el.addEventListener("dragend", () => {
        document.querySelectorAll(".live-pane--plot .plot-area, #plotArea").forEach((pa) => {
            pa.querySelectorAll(".plot-add-slot").forEach((slot) => {
                slot.classList.remove("plot-add-over");
                slot.style.display = "none";
            });
        });
        if (graphList.length === 0) {
            document.querySelectorAll(".live-pane--plot .plot-empty, #plotEmpty").forEach((pe) => {
                pe.classList.remove("plot-add-over");
                if (pe.dataset.defaultText) pe.textContent = pe.dataset.defaultText;
            });
        }
        document.querySelectorAll(".live-pane--monitor .monitor-list, #monitorList").forEach((ml) => {
            ml.querySelectorAll(".monitor-item-wrap").forEach((w) => {
                w.classList.remove("monitor-drop-before", "monitor-drop-after");
                delete w.dataset.dropPosition;
            });
        });
    });

    if (isReplayMode() && !isArrayVar(name) && isVarInTsv(name)) {
        const imposeWrap = document.createElement("span");
        imposeWrap.className = "monitor-impose-wrap";
        const lab = document.createElement("label");
        const imposeCb = document.createElement("input");
        imposeCb.type = "checkbox";
        imposeCb.className = "monitor-impose-cb";
        imposeCb.title = "Imponer a SHM (replay)";
        imposeCb.checked = impositionNames.has(name);
        imposeCb.addEventListener("change", (e) => {
            e.stopPropagation();
            const checked = imposeCb.checked;
            const toApply = monitorSelectedNames.size && monitorSelectedNames.has(name) ? [...monitorSelectedNames] : [name];
            toApply.forEach(n => {
                if (checked) impositionNames.add(n);
                else impositionNames.delete(n);
                syncReplayTsvHistoryForName(n);
            });
            saveConfig();
            rebuildMonitorList();
        });
        lab.appendChild(imposeCb);
        imposeWrap.appendChild(lab);
        el.appendChild(imposeWrap);
    }

    const nameEl = document.createElement("span");
    nameEl.className = "mon-name";
    nameEl.textContent = formatNameWithHiddenLevels(name, hideLevels);
    nameEl.title = name;
    nameEl.addEventListener("click", (e) => {
        e.stopPropagation();
        const useDock = monitorDetailPanelUsesDock();
        if (expandedStats.has(name)) expandedStats.delete(name);
        else {
            if (useDock) expandedStats.clear();
            expandedStats.add(name);
        }
        updateStatsPanel(wrap, name);
        rebuildMonitorList();
    });

    let valEl = null;
    if (!isArrayVar(name)) {
        valEl = document.createElement("span");
        valEl.className = "mon-value";
        const vdInit = varsByName[name];
        if (vdInit) {
            valEl.textContent = formatValue(vdInit.value, vdInit.type, name);
        } else if (isPlaybackMode() && offlineDataset && isVarInTsv(name)) {
            const tNow = Number.isFinite(offlinePlayback.currentTs) ? offlinePlayback.currentTs : offlineDataset.minTs;
            const vAtT = getOfflineScalarValueAtTs(name, tNow);
            valEl.textContent = (vAtT == null) ? "--" : formatValue(vAtT, "double", name);
        } else {
            valEl.textContent = "--";
        }
        valEl.addEventListener("dblclick", (ev) => {
            ev.stopPropagation();
            startInlineEdit(el, name);
        });
    }

    if (isArrayVar(name)) {
        const badge = document.createElement("span");
        badge.className = "array-badge";
        const vd = varsByName[name];
        badge.textContent = vd && Array.isArray(vd.value) ? "[" + vd.value.length + "]" : "[ ]";
        badge.title = "Variable tipo array";
        el.appendChild(badge);
    } else if (isComputed(name)) {
        const badge = document.createElement("span");
        badge.className = "comp-badge";
        badge.textContent = "fx";
        badge.title = computedVars.find(c => c.name === name)?.expr || "";
        el.appendChild(badge);
    }

    const statusTags = document.createElement("span");
    statusTags.className = "mon-status-tags";
    el.appendChild(statusTags);

    const imposeBadge = document.createElement("span");
    imposeBadge.className = "mon-impose-badge";
    imposeBadge.textContent = "IMP";
    imposeBadge.title = "Imponiendo valor desde TSV a SHM";
    imposeBadge.style.display = "none";

    el.appendChild(imposeBadge);
    el.appendChild(nameEl);
    if (valEl) el.appendChild(valEl);

    syncMonitorRowStatusTags(el, name);

    if (isReplayMode() && !isArrayVar(name) && !isComputed(name)) {
        const tr = I18N[currentLang] || I18N.es;
        const alarmQuick = document.createElement("button");
        alarmQuick.type = "button";
        alarmQuick.className = "btn-mon-alarm-quick" + (alarms[name] ? " arr-alarm-active" : "");
        if (activeAlarms.has(name)) alarmQuick.classList.add("alarm-firing");
        alarmQuick.textContent = "\u26A0";
        alarmQuick.title = tr.alarmQuickReplayTitle || "Configurar alarma (vs referencia o Lo/Hi)";
        alarmQuick.addEventListener("click", (e) => {
            e.stopPropagation();
            openReplayAlarmConfigurator(name);
        });
        el.appendChild(alarmQuick);
    }

    const removeBtn = document.createElement("button");
    removeBtn.className = "btn-mon-remove";
    removeBtn.textContent = "\u00D7";
    removeBtn.title = "Quitar de monitorizacion";
    removeBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const toRemove = monitorSelectedNames.has(name) ? [...monitorSelectedNames] : [name];
        for (const n of toRemove) {
            if (isComputed(n)) removeComputedVar(n);
            else {
                monitoredNames.delete(n);
                monitoredOrder = monitoredOrder.filter(o => o !== n);
                delete varGraphAssignment[n];
                delete historyCache[n];
                expandedStats.delete(n);
                monitorSelectedNames.delete(n);
                if (!isArincDerivedName(n) && isArincEnabled(n)) {
                    removeArincDerivedForBase(n);
                }
                if (isArrayVar(n)) {
                    for (const key of Object.keys(arrayElemAssignment)) {
                        if (key.startsWith(n + "[")) {
                            delete arrayElemAssignment[key];
                            delete arrayElemHistory[key];
                        }
                    }
                }
                pruneMonitorAuxMapsForName(n);
            }
        }
        saveConfig();
        sendMonitored();
        const pruned = pruneEmptyGraphs();
        renderBrowserList();
        if (!pruned) {
            rebuildMonitorList();
        }
        renderPlots();
    });
    el.appendChild(removeBtn);
    wrap.appendChild(el);
    return wrap;
}

function syncMonitorVirtualWindow() {
    if (!monitorVmRows || !monitorVmTopSpacer || !monitorVmBottomSpacer) return;
    const renderOrder = getVisibleMonitorRenderOrder();
    const N = renderOrder.length;
    const cols = Math.max(1, monitorColumnsCount | 0);
    const rowsPerCol = Math.max(1, Math.ceil(N / cols));
    const totalRows = rowsPerCol;
    const rowH = monitorVmRowPx;

    const statusEl = document.getElementById("monitorFilterStatus");
    if (statusEl) {
        const total = monitoredOrder.length;
        if ((monitorFilterText || "").trim()) {
            statusEl.textContent = "Mostrando " + N + " de " + total;
            statusEl.style.display = "";
        } else {
            statusEl.textContent = "";
            statusEl.style.display = "none";
        }
    }

    if (N === 0) {
        monitorVmTopSpacer.style.height = "0px";
        monitorVmBottomSpacer.style.height = "0px";
        monitorVmRows.innerHTML = "";
        hideMonitorDetailDock();
        updateMonitorItemStyles();
        return;
    }

    const viewportH = monitorListScrollPort.clientHeight || 400;
    const scrollTop = monitorListScrollPort.scrollTop;
    let startRow = Math.floor(scrollTop / rowH) - MONITOR_VM_BUFFER;
    let endRow = Math.ceil((scrollTop + viewportH) / rowH) + MONITOR_VM_BUFFER;
    if (startRow < 0) startRow = 0;
    if (endRow > totalRows) endRow = totalRows;
    if (endRow <= startRow) {
        endRow = Math.min(totalRows, startRow + 1);
    }
    // Edición inline: la fila debe seguir en DOM aunque el scroll la saque del viewport.
    if (editingName && monitoredNames.has(editingName)) {
        const ep = renderOrder.indexOf(editingName);
        if (ep >= 0) {
            const editRow = ep % rowsPerCol;
            const buf = MONITOR_VM_BUFFER;
            if (editRow < startRow) startRow = Math.max(0, editRow - buf);
            if (editRow >= endRow) endRow = Math.min(totalRows, editRow + buf + 1);
        }
    }
    const visibleRows = [];
    for (let r = startRow; r < endRow; r++) visibleRows.push(r);
    const sliceByRow = new Map();
    visibleRows.forEach((r) => {
        const rowNames = [];
        for (let c = 0; c < cols; c++) {
            const idx = c * rowsPerCol + r;
            if (idx >= N) continue;
            rowNames.push(renderOrder[idx]);
        }
        sliceByRow.set(r, rowNames);
    });
    const sliceSet = new Set();
    sliceByRow.forEach((rowNames) => rowNames.forEach((n) => sliceSet.add(n)));

    monitorVmRows.querySelectorAll(".monitor-item-wrap").forEach((el) => {
        const nm = el.dataset.name;
        if (nm === editingName) return;
        if (!sliceSet.has(nm)) el.remove();
    });

    monitorVmRows.querySelectorAll(".stats-panel").forEach((p) => p.remove());

    const rowElsOrdered = [];
    visibleRows.forEach((rowIdx) => {
        let rowEl = monitorVmRows.querySelector(`.monitor-vm-row[data-row="${rowIdx}"]`);
        if (!rowEl) {
            rowEl = document.createElement("div");
            rowEl.className = "monitor-vm-row";
            rowEl.dataset.row = String(rowIdx);
        }
        const rowNames = sliceByRow.get(rowIdx) || [];
        const rowSet = new Set(rowNames);
        rowEl.querySelectorAll(".monitor-item-wrap").forEach((el) => {
            if (!rowSet.has(el.dataset.name)) el.remove();
        });
        rowNames.forEach((name) => {
            let wrap = rowEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(name)}"]`);
            if (wrap) {
                updateMonitorRowWrap(wrap, name);
            } else {
                wrap = createMonitorRowWrap(name);
                rowEl.appendChild(wrap);
            }
            syncMonitorImpositionVisual(wrap, name);
        });
        rowNames.forEach((name) => {
            const w = rowEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(name)}"]`);
            if (w) rowEl.appendChild(w);
        });
        rowElsOrdered.push(rowEl);
    });
    const curKids = monitorVmRows.children;
    const nOrd = rowElsOrdered.length;
    let needReplace = nOrd !== curKids.length;
    if (!needReplace) {
        for (let i = 0; i < nOrd; i++) {
            if (curKids[i] !== rowElsOrdered[i]) {
                needReplace = true;
                break;
            }
        }
    }
    if (needReplace) monitorVmRows.replaceChildren(...rowElsOrdered);

    monitorVmRows.style.setProperty("--monitor-vm-columns", String(cols));
    monitorVmTopSpacer.style.height = (startRow * rowH) + "px";
    monitorVmBottomSpacer.style.height = ((totalRows - endRow) * rowH) + "px";

    updateMonitorItemStyles();
}

function rebuildMonitorListVirtual() {
    ensureMonitorVirtualShell();
    syncMonitoredNamesForPlugins();
    if (expandedStats.size > 1) {
        let keep = null;
        for (const n of monitoredOrder) {
            if (expandedStats.has(n)) {
                keep = n;
                break;
            }
        }
        expandedStats.clear();
        if (keep) expandedStats.add(keep);
    }
    syncMonitorVirtualWindow();
    measureMonitorVmRowHeightFromSlice(true);
    syncMonitorVirtualWindow();
    refreshDockedStatsAfterVirtualSync();
    requestAnimationFrame(() => {
        if (!monitorListEl.classList.contains("monitor-list--virtual")) return;
        syncMonitorVirtualWindow();
        measureMonitorVmRowHeightFromSlice(true);
        syncMonitorVirtualWindow();
        refreshDockedStatsAfterVirtualSync();
    });
}

function rebuildMonitorList() {
    if (shouldUseMonitorVirtualList()) {
        rebuildMonitorListVirtual();
        return;
    }
    if (!monitorDetailPanelUsesDock()) {
        hideMonitorDetailDock();
    }
    const listTargets = (() => {
        const nl = document.querySelectorAll(".live-pane--monitor .monitor-list");
        if (nl.length > 0) return Array.from(nl);
        return monitorListEl ? [monitorListEl] : [];
    })();
    if (listTargets.length === 0) return;
    const primaryList = listTargets[0];
    destroyMonitorVirtualShell();
    delete primaryList._vmRowFrozen;

    const primaryPane = primaryList.closest(".live-pane--monitor");
    const primaryLeafId = primaryPane && primaryPane.dataset.leafId ? primaryPane.dataset.leafId : null;
    const renderOrderPrimary = primaryLeafId ? getMonitorRenderOrderForPane(primaryLeafId) : getMonitorRenderOrder();
    let visibleCount = 0;
    for (const name of renderOrderPrimary) {
        if (!nameMatchesFilter(name, monitorFilterText)) continue;
        visibleCount++;
    }

    for (const listEl of listTargets) {
        const pane = listEl.closest(".live-pane--monitor");
        const leafId = pane && pane.dataset.leafId ? pane.dataset.leafId : null;
        const renderOrder = leafId ? getMonitorRenderOrderForPane(leafId) : getMonitorRenderOrder();
        const existing = listEl.querySelectorAll(".monitor-item-wrap");
        const existingMap = {};
        existing.forEach((el) => { existingMap[el.dataset.name] = el; });

        for (const name of renderOrder) {
            if (!nameMatchesFilter(name, monitorFilterText)) {
                if (existingMap[name]) {
                    existingMap[name].remove();
                }
                delete existingMap[name];
                continue;
            }

            if (existingMap[name]) {
                updateMonitorRowWrap(existingMap[name], name);
                delete existingMap[name];
                continue;
            }

            const wrap = createMonitorRowWrap(name);
            listEl.appendChild(wrap);
            syncMonitorImpositionVisual(wrap, name);
        }

        Object.values(existingMap).forEach((el) => el.remove());
        renderOrder.forEach((n) => {
            const w = listEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(n)}"]`);
            if (w) listEl.appendChild(w);
        });
    }

    const statusEl = document.getElementById("monitorFilterStatus");
    if (statusEl) {
        const total = monitoredOrder.length;
        if ((monitorFilterText || "").trim()) {
            statusEl.textContent = "Mostrando " + visibleCount + " de " + total;
            statusEl.style.display = "";
        } else {
            statusEl.textContent = "";
            statusEl.style.display = "none";
        }
    }

    if (monitorDetailPanelUsesDock() && expandedStats.size > 1) {
        let keep = null;
        for (const n of monitoredOrder) {
            if (expandedStats.has(n)) {
                keep = n;
                break;
            }
        }
        expandedStats.clear();
        if (keep) expandedStats.add(keep);
    }
    if (monitorDetailPanelUsesDock()) {
        const nm = getDockedExpandedVarName();
        if (nm) updateStatsPanel(null, nm);
    } else {
        for (const n of expandedStats) {
            const w = primaryList.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(n)}"]`);
            if (w) updateStatsPanel(w, n);
        }
    }
    updateMonitorItemStyles();
    syncMonitoredNamesForPlugins();
}

if (monitorListEl && monitorListScrollPort && !monitorListScrollPort._vmScrollBound) {
    monitorListScrollPort._vmScrollBound = true;
    /* Un sync por frame (rAF deduplicado): muchos scroll/evento bloqueaban el hilo y la rueda parecía ir a pasos fijos. */
    monitorListScrollPort.addEventListener("scroll", () => {
        if (!monitorListEl.classList.contains("monitor-list--virtual")) return;
        if (monitorVmScrollRaf) return;
        monitorVmScrollRaf = requestAnimationFrame(() => {
            monitorVmScrollRaf = 0;
            if (!monitorListEl.classList.contains("monitor-list--virtual")) return;
            syncMonitorVirtualWindow();
        });
    }, { passive: true });
    let monitorVmResizeDebounce = null;
    if (typeof ResizeObserver !== "undefined") {
        const ro = new ResizeObserver(() => {
            if (!monitorListEl.classList.contains("monitor-list--virtual")) return;
            clearTimeout(monitorVmResizeDebounce);
            monitorVmResizeDebounce = setTimeout(() => {
                monitorVmResizeDebounce = null;
                if (!monitorListEl.classList.contains("monitor-list--virtual")) return;
                monitorListEl._vmRowFrozen = false;
                measureMonitorVmRowHeightFromSlice(true);
                syncMonitorVirtualWindow();
            }, 120);
        });
        ro.observe(monitorListScrollPort);
    }
    /* Scroll con rueda/trackpad nativo: el listener custom con preventDefault provocaba sensación
       de scroll “atascado” al usar la lista virtual. La sincronización va solo por el evento scroll. */
}

function arrayElemName(arrName, idx) { return arrName + "[" + idx + "]"; }

function updateArrayStatsPanel(panel, name) {
    const vd = varsByName[name];
    const arr = vd && Array.isArray(vd.value) ? vd.value : [];

    let statsRow = panel.querySelector(".stats-row");
    if (!statsRow) {
        statsRow = document.createElement("div");
        statsRow.className = "stats-row";
        panel.appendChild(statsRow);
    }

    if (arr.length === 0) {
        statsRow.innerHTML = '<span class="stats-empty">Array vacio</span>';
    } else {
        let min = Infinity, max = -Infinity;
        for (let i = 0; i < arr.length; i++) {
            if (arr[i] < min) min = arr[i];
            if (arr[i] > max) max = arr[i];
        }
        statsRow.innerHTML =
            `<span class="stat-item">Len <b>${arr.length}</b></span>` +
            `<span class="stat-item">Min <b>${min.toFixed(3)}</b></span>` +
            `<span class="stat-item">Max <b>${max.toFixed(3)}</b></span>`;
    }

    let tableWrap = panel.querySelector(".array-table-wrap");
    if (!tableWrap) {
        tableWrap = document.createElement("div");
        tableWrap.className = "array-table-wrap";
        panel.appendChild(tableWrap);
    }
    updateArrayTable(tableWrap, name, arr);
}

function updateArrayTable(wrap, name, arr) {
    const editing = wrap.querySelector(".arr-cell-edit");
    const editingIdx = editing ? parseInt(editing.dataset.idx) : -1;

    let table = wrap.querySelector(".array-table");
    if (!table) {
        table = document.createElement("div");
        table.className = "array-table";
        wrap.appendChild(table);
    }

    let rows = table.querySelectorAll(".arr-row");
    const needRebuild = rows.length !== arr.length;

    function attachArrayElemDrag(row, eName) {
        row.draggable = true;
        const onDragStart = (e) => {
            if (!e.dataTransfer) return;
            noteMonitorDragStart(eName);
            e.dataTransfer.setData("text/plain", eName);
            e.dataTransfer.setData("application/x-var-name", eName);
            e.dataTransfer.effectAllowed = "copy";
            ensureNewGraphDropTarget();
        };
        const onDragEnd = () => {
            plotArea.querySelectorAll(".plot-add-slot").forEach((slot) => {
                slot.classList.remove("plot-add-over");
                slot.style.display = "none";
            });
            if (graphList.length === 0 && plotEmpty) {
                plotEmpty.classList.remove("plot-add-over");
                if (plotEmpty.dataset.defaultText) plotEmpty.textContent = plotEmpty.dataset.defaultText;
            }
        };
        if (row._arrDragStart) row.removeEventListener("dragstart", row._arrDragStart);
        if (row._arrDragEnd) row.removeEventListener("dragend", row._arrDragEnd);
        row._arrDragStart = onDragStart;
        row._arrDragEnd = onDragEnd;
        row.addEventListener("dragstart", onDragStart);
        row.addEventListener("dragend", onDragEnd);
    }

    if (needRebuild) {
        table.innerHTML = "";
        for (let i = 0; i < arr.length; i++) {
            const eName = arrayElemName(name, i);
            const row = document.createElement("div");
            row.className = "arr-row";
            row.dataset.idx = i;
            attachArrayElemDrag(row, eName);

            const idx = document.createElement("span");
            idx.className = "arr-idx-label";
            idx.textContent = "[" + i + "]";

            const val = document.createElement("span");
            val.className = "arr-val";
            val.textContent = arr[i].toFixed(4);
            val.title = "Doble-clic para editar";
            val.addEventListener("dblclick", (e) => {
                e.stopPropagation();
                startArrayCellEdit(wrap, name, i, val);
            });

            const alarmBtn = document.createElement("span");
            alarmBtn.className = "arr-alarm-btn" + (alarms[eName] ? " arr-alarm-active" : "");
            alarmBtn.textContent = "\u26A0";
            alarmBtn.title = alarms[eName]
                ? `Alarma: Lo:${alarms[eName].lo ?? "-"} Hi:${alarms[eName].hi ?? "-"} (clic para quitar)`
                : "Configurar alarma";
            alarmBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                if (alarms[eName]) {
                    delete alarms[eName];
                    delete prevAlarmState[eName];
                    alarmBtn.className = "arr-alarm-btn";
                    alarmBtn.title = "Configurar alarma";
                } else {
                    showArrayElemAlarmForm(row, eName, alarmBtn);
                }
                saveConfig();
                sendAlarmsToBackend();
            });

            const genBtn = document.createElement("span");
            genBtn.className = "arr-gen-btn" + (activeGenerators[eName] ? " arr-gen-active" : "");
            genBtn.textContent = "fx";
            genBtn.title = activeGenerators[eName] ? "Generador activo (clic para parar)" : "Generador de señal";
            genBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                if (activeGenerators[eName]) {
                    stopGenerator(eName);
                    genBtn.className = "arr-gen-btn";
                    genBtn.title = "Generador de señal";
                } else {
                    showArrayElemGenForm(row, eName, genBtn);
                }
            });

            row.appendChild(idx);
            row.appendChild(val);
            if (isLiveMode() || isPlaybackMode()) {
                row.appendChild(alarmBtn);
                row.appendChild(genBtn);
            }
            table.appendChild(row);
        }
    } else {
        rows.forEach(row => {
            const i = parseInt(row.dataset.idx);
            if (i === editingIdx) return;
            const eName = arrayElemName(name, i);
            attachArrayElemDrag(row, eName);
            const valEl = row.querySelector(".arr-val");
            if (valEl && i < arr.length) valEl.textContent = arr[i].toFixed(4);
            const ab = row.querySelector(".arr-alarm-btn");
            if (ab) {
                const hasAlarm = !!alarms[eName];
                ab.className = "arr-alarm-btn" + (hasAlarm ? " arr-alarm-active" : "");
                if (activeAlarms.has(eName)) ab.classList.add("arr-alarm-firing");
            }
            const gb = row.querySelector(".arr-gen-btn");
            if (gb) {
                gb.className = "arr-gen-btn" + (activeGenerators[eName] ? " arr-gen-active" : "");
            }
        });
    }
}

function startArrayCellEdit(wrap, name, index, cell) {
    if (!isLiveMode()) return;
    if (cell.querySelector(".arr-cell-edit")) return;
    const oldText = cell.textContent;
    const tr = I18N[currentLang] || I18N.es;
    cell.textContent = "";
    cell.classList.add("arr-val--editing");

    const input = document.createElement("input");
    input.className = "arr-cell-edit";
    input.type = "text";
    input.value = oldText;
    input.dataset.idx = index;

    const actions = document.createElement("span");
    actions.className = "arr-edit-actions";
    const okBtn = document.createElement("button");
    okBtn.type = "button";
    okBtn.className = "btn-arr-edit-ok";
    okBtn.textContent = "\u2713";
    okBtn.title = tr.inlineEditConfirm || "Confirmar";
    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button";
    cancelBtn.className = "btn-arr-edit-cancel";
    cancelBtn.textContent = "\u2715";
    cancelBtn.title = tr.inlineEditCancel || "Cancelar";
    okBtn.addEventListener("mousedown", (e) => e.preventDefault());
    cancelBtn.addEventListener("mousedown", (e) => e.preventDefault());

    let done = false;

    function teardown() {
        cell.classList.remove("arr-val--editing");
        cell.replaceChildren();
    }

    function commit() {
        if (done) return;
        done = true;
        const val = parseFloat(input.value);
        if (!isNaN(val)) {
            sendWsAction({
                action: "set_array_element",
                name: name,
                index: index,
                value: val,
            });
        }
        teardown();
        cell.textContent = isNaN(val) ? oldText : val.toFixed(3);
    }

    function cancel() {
        if (done) return;
        done = true;
        teardown();
        cell.textContent = oldText;
    }

    okBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        commit();
    });
    cancelBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        cancel();
    });

    input.addEventListener("keydown", (e) => {
        e.stopPropagation();
        if (e.key === "Enter") commit();
        else if (e.key === "Escape") cancel();
    });
    input.addEventListener("click", (e) => e.stopPropagation());

    cell.addEventListener("focusout", (e) => {
        if (done) return;
        const rt = e.relatedTarget;
        if (rt && cell.contains(rt)) return;
        window.setTimeout(() => {
            if (done) return;
            if (document.activeElement && cell.contains(document.activeElement)) return;
            cancel();
        }, 0);
    });

    actions.appendChild(okBtn);
    actions.appendChild(cancelBtn);
    cell.appendChild(input);
    cell.appendChild(actions);
    input.focus();
    input.select();
}

function showArrayElemAlarmForm(row, eName, alarmBtn) {
    if (row.querySelector(".arr-alarm-form")) return;
    const form = document.createElement("span");
    form.className = "arr-alarm-form";

    const loIn = document.createElement("input");
    loIn.type = "text";
    loIn.placeholder = "Lo";
    loIn.className = "arr-alarm-input";
    const hiIn = document.createElement("input");
    hiIn.type = "text";
    hiIn.placeholder = "Hi";
    hiIn.className = "arr-alarm-input";

    const ok = document.createElement("button");
    ok.className = "arr-alarm-ok";
    ok.textContent = "\u2713";
    ok.addEventListener("click", (e) => {
        e.stopPropagation();
        const lo = loIn.value.trim() ? parseFloat(loIn.value) : null;
        const hi = hiIn.value.trim() ? parseFloat(hiIn.value) : null;
        if (lo === null && hi === null) {
            delete alarms[eName];
        } else {
            alarms[eName] = { lo, hi };
        }
        form.remove();
        alarmBtn.className = "arr-alarm-btn" + (alarms[eName] ? " arr-alarm-active" : "");
        alarmBtn.title = alarms[eName]
            ? `Alarma: Lo:${alarms[eName].lo ?? "-"} Hi:${alarms[eName].hi ?? "-"} (clic para quitar)`
            : "Configurar alarma";
        saveConfig();
        sendAlarmsToBackend();
    });

    const cancel = document.createElement("button");
    cancel.className = "arr-alarm-cancel";
    cancel.textContent = "\u00D7";
    cancel.addEventListener("click", (e) => { e.stopPropagation(); form.remove(); });

    [loIn, hiIn, ok, cancel].forEach(el => el.addEventListener("click", (e) => e.stopPropagation()));
    loIn.addEventListener("keydown", (e) => { e.stopPropagation(); if (e.key === "Enter") ok.click(); if (e.key === "Escape") cancel.click(); });
    hiIn.addEventListener("keydown", (e) => { e.stopPropagation(); if (e.key === "Enter") ok.click(); if (e.key === "Escape") cancel.click(); });

    form.appendChild(loIn);
    form.appendChild(hiIn);
    form.appendChild(ok);
    form.appendChild(cancel);
    row.appendChild(form);
    loIn.focus();
}

function showArrayElemGenForm(row, eName, genBtn) {
    const next = row.nextSibling;
    if (next && next.classList && next.classList.contains("arr-gen-form")) return;
    const form = document.createElement("div");
    form.className = "arr-gen-form";

    const sel = document.createElement("select");
    sel.className = "arr-gen-type-select";
    const optNone = document.createElement("option");
    optNone.value = "";
    optNone.textContent = "Tipo...";
    sel.appendChild(optNone);
    for (const [key, def] of Object.entries(GEN_TYPES)) {
        const o = document.createElement("option");
        o.value = key;
        o.textContent = def.label;
        sel.appendChild(o);
    }

    const paramsDiv = document.createElement("div");
    paramsDiv.className = "arr-gen-params";

    sel.addEventListener("change", () => {
        paramsDiv.innerHTML = "";
        const def = GEN_TYPES[sel.value];
        if (!def) return;
        for (const f of def.fields) {
            const wrap = document.createElement("span");
            wrap.className = "arr-gen-field";
            const lbl = document.createElement("span");
            lbl.className = "arr-gen-field-label";
            lbl.textContent = f.l;
            const inp = document.createElement("input");
            inp.type = "text";
            inp.className = "arr-gen-input";
            inp.value = f.d;
            inp.dataset.key = f.k;
            inp.addEventListener("click", (e) => e.stopPropagation());
            inp.addEventListener("keydown", (e) => e.stopPropagation());
            wrap.appendChild(lbl);
            wrap.appendChild(inp);
            paramsDiv.appendChild(wrap);
        }
    });
    sel.addEventListener("click", (e) => e.stopPropagation());

    const okBtn = document.createElement("button");
    okBtn.className = "arr-alarm-ok";
    okBtn.textContent = "\u25B6";
    okBtn.title = "Iniciar generador";
    okBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const type = sel.value;
        if (!type) return;
        const params = {};
        paramsDiv.querySelectorAll(".arr-gen-input").forEach(inp => {
            params[inp.dataset.key] = parseFloat(inp.value) || 0;
        });
        startGenerator(eName, type, params);
        genBtn.className = "arr-gen-btn arr-gen-active";
        genBtn.title = "Generador activo (clic para parar)";
        form.remove();
    });

    const cancelBtn = document.createElement("button");
    cancelBtn.className = "arr-alarm-cancel";
    cancelBtn.textContent = "\u00D7";
    cancelBtn.addEventListener("click", (e) => { e.stopPropagation(); form.remove(); });

    form.addEventListener("click", (e) => e.stopPropagation());

    const topRow = document.createElement("div");
    topRow.className = "arr-gen-top";
    topRow.appendChild(sel);
    topRow.appendChild(okBtn);
    topRow.appendChild(cancelBtn);
    form.appendChild(topRow);
    form.appendChild(paramsDiv);
    row.parentNode.insertBefore(form, row.nextSibling);
}

function trackArrayElementHistories(appendHistory = true) {
    if (!appendHistory) return false;
    let tracked = false;
    for (const name of monitoredNames) {
        if (!isArrayVar(name)) continue;
        const vd = varsByName[name];
        if (!vd || !Array.isArray(vd.value)) continue;
        const arr = vd.value;
        const now = isReplayMode()
            ? getReplayCurrentTs()
            : (vd.timestamp || (Date.now() / 1000));
        for (let i = 0; i < arr.length; i++) {
            const eName = arrayElemName(name, i);
            if (!arrayElemAssignment[eName]) continue;
            tracked = true;
            if (!arrayElemHistory[eName]) arrayElemHistory[eName] = { timestamps: [], values: [] };
            const h = arrayElemHistory[eName];
            h.timestamps.push(now);
            h.values.push(arr[i]);
            if (h.timestamps.length > ARRAY_HIST_MAX) {
                const trim = Math.floor(ARRAY_HIST_MAX * 0.75);
                h.timestamps = h.timestamps.slice(-trim);
                h.values = h.values.slice(-trim);
            }
        }
    }
    return tracked;
}

function syncConversionDetailPanel(panel, name, wrap, tr) {
    const fmtOptsUnits =
        '<option value="dec">Dec</option><option value="sci">Sci</option><option value="hex">Hex</option><option value="bin">Bin</option>' +
        (hasPlugin("m1553") ? '<option value="m1553">1553</option>' : "");
    let block = panel.querySelector(".fmt-conversion-block");
    const mode = inferVarFormatMode(ensureVarFormatEntry(name));
    const show = mode === "units";
    if (!block) {
        block = document.createElement("div");
        block.className = "fmt-conversion-block";
        const title = document.createElement("div");
        title.className = "fmt-physical-title";
        title.textContent = tr.convBlockTitle || tr.physBlockTitle || "Conversión";
        const row1 = document.createElement("div");
        row1.className = "fmt-row fmt-conv-type-row";
        const catLbl = document.createElement("span");
        catLbl.className = "fmt-label";
        catLbl.textContent = tr.convTypeLabel || "Tipo:";
        const catSel = document.createElement("select");
        catSel.className = "fmt-select fmt-conv-type";
        const cats = [
            [PHYS_NUMERIC, tr.convTypeNumeric || "Base"],
            [PHYS_LENGTH, tr.physCatLength],
            [PHYS_MASS, tr.physCatMass],
            [PHYS_SPEED, tr.physCatSpeed],
            [PHYS_DMS, tr.physCatDms],
            [PHYS_ANGLE, tr.physCatAngle],
        ];
        for (let i = 0; i < cats.length; i++) {
            const o = document.createElement("option");
            o.value = cats[i][0];
            o.textContent = cats[i][1];
            catSel.appendChild(o);
        }
        catSel.addEventListener("change", (e) => {
            e.stopPropagation();
            const v = ensureVarFormatEntry(name);
            v.physical = defaultPhysicalForCategory(catSel.value);
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
            syncConversionDetailPanel(panel, name, wrap, tr);
        });
        catSel.addEventListener("click", (e) => e.stopPropagation());
        row1.appendChild(catLbl);
        row1.appendChild(catSel);
        const dyn = document.createElement("div");
        dyn.className = "fmt-conv-dynamic";
        block.appendChild(title);
        block.appendChild(row1);
        block.appendChild(dyn);
        panel.appendChild(block);
    }
    block.style.display = show ? "" : "none";
    if (!show) return;
    const v = ensureVarFormatEntry(name);
    const phys = ensurePhysicalDefaults(v.physical);
    v.physical = phys;
    const catSel = block.querySelector(".fmt-conv-type");
    if (catSel) catSel.value = phys.category;
    const dyn = block.querySelector(".fmt-conv-dynamic");
    if (!dyn) return;
    dyn.innerHTML = "";

    function rowFromTo(fromSel, toSel) {
        const r1 = document.createElement("div");
        r1.className = "fmt-row";
        const l1 = document.createElement("span");
        l1.className = "fmt-label";
        l1.textContent = tr.physFromLabel || "Origen:";
        r1.appendChild(l1);
        r1.appendChild(fromSel);
        const r2 = document.createElement("div");
        r2.className = "fmt-row";
        const l2 = document.createElement("span");
        l2.className = "fmt-label";
        l2.textContent = tr.physToLabel || "Destino:";
        r2.appendChild(l2);
        r2.appendChild(toSel);
        dyn.appendChild(r1);
        dyn.appendChild(r2);
    }

    if (phys.category === PHYS_NUMERIC) {
        const rowN = document.createElement("div");
        rowN.className = "fmt-row";
        const oriLbl = document.createElement("span");
        oriLbl.className = "fmt-label";
        oriLbl.textContent = tr.fmtOriShort || "Ori:";
        const oriSel = document.createElement("select");
        oriSel.className = "fmt-select fmt-select-ori";
        oriSel.innerHTML = fmtOptsUnits;
        oriSel.value = v.ori || "dec";
        oriSel.addEventListener("change", (e) => {
            e.stopPropagation();
            const vf = ensureVarFormatEntry(name);
            vf.ori = oriSel.value;
            if (vf.sal !== "m1553" && vf.sal !== "arinc429") vf.fmtMode = "units";
            saveConfig();
            updateMonitorItemStyles();
        });
        oriSel.addEventListener("click", (e) => e.stopPropagation());
        const salLbl = document.createElement("span");
        salLbl.className = "fmt-label";
        salLbl.textContent = tr.fmtSalShort || "Sal:";
        const salSel = document.createElement("select");
        salSel.className = "fmt-select fmt-select-sal";
        salSel.innerHTML = fmtOptsUnits;
        salSel.value = v.sal === "arinc429" ? "dec" : (v.sal === "m1553" ? "m1553" : (v.sal || "dec"));
        salSel.addEventListener("change", (e) => {
            e.stopPropagation();
            const vf = ensureVarFormatEntry(name);
            vf.sal = salSel.value;
            if (salSel.value === "m1553") vf.fmtMode = "m1553";
            else if (salSel.value === "arinc429") vf.fmtMode = "arinc";
            else vf.fmtMode = "units";
            saveConfig();
            updateMonitorItemStyles();
        });
        salSel.addEventListener("click", (e) => e.stopPropagation());
        rowN.appendChild(oriLbl);
        rowN.appendChild(oriSel);
        rowN.appendChild(salLbl);
        rowN.appendChild(salSel);
        dyn.appendChild(rowN);
        return;
    }

    if (phys.category === PHYS_LENGTH) {
        const fromSel = document.createElement("select");
        fromSel.className = "fmt-select";
        [["m", "m"], ["ft", "ft"], ["nmi", "nm"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            if (val === "nmi") o.title = tr.physHintNm || "";
            fromSel.appendChild(o);
        });
        fromSel.value = phys.from;
        const toSel = document.createElement("select");
        toSel.className = "fmt-select";
        [["m", "m"], ["ft", "ft"], ["nmi", "nm"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            if (val === "nmi") o.title = tr.physHintNm || "";
            toSel.appendChild(o);
        });
        toSel.value = phys.to;
        fromSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.from = fromSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        toSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.to = toSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        fromSel.addEventListener("click", (e) => e.stopPropagation());
        toSel.addEventListener("click", (e) => e.stopPropagation());
        rowFromTo(fromSel, toSel);
    } else if (phys.category === PHYS_MASS) {
        const fromSel = document.createElement("select");
        fromSel.className = "fmt-select";
        [["kg", "kg"], ["lb", "lb"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            fromSel.appendChild(o);
        });
        fromSel.value = phys.from;
        const toSel = document.createElement("select");
        toSel.className = "fmt-select";
        [["kg", "kg"], ["lb", "lb"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            toSel.appendChild(o);
        });
        toSel.value = phys.to;
        fromSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.from = fromSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        toSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.to = toSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        fromSel.addEventListener("click", (e) => e.stopPropagation());
        toSel.addEventListener("click", (e) => e.stopPropagation());
        rowFromTo(fromSel, toSel);
    } else if (phys.category === PHYS_SPEED) {
        const fromSel = document.createElement("select");
        fromSel.className = "fmt-select";
        [["ms", "m/s"], ["kmh", "km/h"], ["knot", "kn"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            fromSel.appendChild(o);
        });
        fromSel.value = phys.from;
        const toSel = document.createElement("select");
        toSel.className = "fmt-select";
        [["ms", "m/s"], ["kmh", "km/h"], ["knot", "kn"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            toSel.appendChild(o);
        });
        toSel.value = phys.to;
        fromSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.from = fromSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        toSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.to = toSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        fromSel.addEventListener("click", (e) => e.stopPropagation());
        toSel.addEventListener("click", (e) => e.stopPropagation());
        rowFromTo(fromSel, toSel);
    } else if (phys.category === PHYS_ANGLE) {
        const fromSel = document.createElement("select");
        fromSel.className = "fmt-select";
        [["rad", "rad"], ["deg", "\u00B0"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            fromSel.appendChild(o);
        });
        fromSel.value = phys.from;
        const toSel = document.createElement("select");
        toSel.className = "fmt-select";
        [["rad", "rad"], ["deg", "\u00B0"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            toSel.appendChild(o);
        });
        toSel.value = phys.to;
        fromSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.from = fromSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        toSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.to = toSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        fromSel.addEventListener("click", (e) => e.stopPropagation());
        toSel.addEventListener("click", (e) => e.stopPropagation());
        rowFromTo(fromSel, toSel);
    } else if (phys.category === PHYS_DMS) {
        const fromSel = document.createElement("select");
        fromSel.className = "fmt-select";
        [["deg", "\u00B0 (decimal)"], ["min", "\u2032 (min)"], ["sec", "\u2033 (seg)"]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            fromSel.appendChild(o);
        });
        fromSel.value = phys.from;
        const toSel = document.createElement("select");
        toSel.className = "fmt-select";
        [["deg", "\u00B0"], ["min", "\u2032"], ["sec", "\u2033"], ["dms", "\u00B0\u2032\u2033 conj."]].forEach(([val, lab]) => {
            const o = document.createElement("option");
            o.value = val;
            o.textContent = lab;
            toSel.appendChild(o);
        });
        toSel.value = phys.to;
        fromSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.from = fromSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        toSel.addEventListener("change", (e) => {
            e.stopPropagation();
            ensureVarFormatEntry(name).physical.to = toSel.value;
            saveConfig();
            updateMonitorItemStyles();
            updateMonitorValues();
        });
        fromSel.addEventListener("click", (e) => e.stopPropagation());
        toSel.addEventListener("click", (e) => e.stopPropagation());
        rowFromTo(fromSel, toSel);
    }
}

function updateStatsPanel(wrap, name) {
    const useDock = monitorListEl && monitorDetailPanelUsesDock();

    if (!expandedStats.has(name)) {
        if (useDock) {
            const dock = getMonitorDetailDockEl();
            if (dock && dock.dataset.detailFor === name) {
                hideMonitorDetailDock();
            }
            if (monitorVmRows) {
                monitorVmRows.querySelectorAll(".stats-panel").forEach((p) => p.remove());
            }
        } else if (wrap) {
            const oldPanel = wrap.querySelector(".stats-panel");
            if (oldPanel) oldPanel.remove();
        }
        return;
    }

    let panel;
    if (useDock) {
        const dock = getMonitorDetailDockEl();
        if (!dock) return;
        dock.style.display = "";
        panel = dock.querySelector(".stats-panel");
        if (dock.dataset.detailFor !== name || !panel) {
            dock.dataset.detailFor = name;
            dock.innerHTML = "";
            const hdr = document.createElement("div");
            hdr.className = "monitor-detail-dock-header";
            const titleSpan = document.createElement("span");
            titleSpan.className = "monitor-detail-dock-title";
            titleSpan.textContent = name;
            const closeBtn = document.createElement("button");
            closeBtn.type = "button";
            closeBtn.className = "btn-monitor-detail-close";
            closeBtn.textContent = "\u00D7";
            closeBtn.title = currentLang === "en" ? "Close panel" : "Cerrar panel";
            closeBtn.setAttribute("aria-label", closeBtn.title);
            closeBtn.addEventListener("click", (ev) => {
                ev.stopPropagation();
                const cur = dock.dataset.detailFor;
                if (cur) expandedStats.delete(cur);
                hideMonitorDetailDock();
                rebuildMonitorList();
            });
            hdr.appendChild(titleSpan);
            hdr.appendChild(closeBtn);
            panel = document.createElement("div");
            panel.className = "stats-panel stats-panel--docked";
            dock.appendChild(hdr);
            dock.appendChild(panel);
        } else {
            const titleSpan = dock.querySelector(".monitor-detail-dock-title");
            if (titleSpan) titleSpan.textContent = name;
        }
    } else {
        if (!wrap) return;
        panel = wrap.querySelector(".stats-panel");
        if (!panel) {
            panel = document.createElement("div");
            panel.className = "stats-panel";
            wrap.appendChild(panel);
        }
    }
    panel.classList.remove("stats-panel--arinc");

    if (isArrayVar(name)) {
        updateArrayStatsPanel(panel, name);
        return;
    }

    let exprRow = panel.querySelector(".expr-row");
    const cv = computedVars.find(c => c.name === name);
    if (cv && !exprRow) {
        exprRow = document.createElement("div");
        exprRow.className = "expr-row";

        const eqSign = document.createElement("span");
        eqSign.className = "expr-eq";
        eqSign.textContent = "= ";

        const exprInput = document.createElement("input");
        exprInput.className = "expr-input";
        exprInput.type = "text";
        exprInput.value = cv.expr;
        exprInput.title = "Editar expresion (Enter para confirmar)";

        const exprOk = document.createElement("button");
        exprOk.className = "btn-expr-ok";
        exprOk.textContent = "\u2713";
        exprOk.title = "Aplicar cambio";

        const exprErr = document.createElement("span");
        exprErr.className = "expr-err";

        function applyExpr() {
            const newExpr = exprInput.value.trim();
            if (!newExpr) return;
            let fn;
            try {
                fn = new Function("$", `with($){return (${newExpr});}`);
            } catch (e) {
                exprErr.textContent = e.message;
                exprErr.style.display = "inline";
                setTimeout(() => { exprErr.style.display = "none"; }, 3000);
                return;
            }
            cv.expr = newExpr;
            cv.fn = fn;
            computedHistories[name] = { timestamps: [], values: [] };
            historyCache[name] = computedHistories[name];
            exprErr.style.display = "none";
            saveConfig();
        }

        exprOk.addEventListener("click", (e) => { e.stopPropagation(); applyExpr(); });
        exprInput.addEventListener("keydown", (e) => {
            if (e.key === "Enter") { e.stopPropagation(); applyExpr(); }
        });
        exprInput.addEventListener("click", (e) => e.stopPropagation());

        exprRow.appendChild(eqSign);
        exprRow.appendChild(exprInput);
        exprRow.appendChild(exprOk);
        exprRow.appendChild(exprErr);
        panel.appendChild(exprRow);
    } else if (!cv && exprRow) {
        exprRow.remove();
    }

    const statsRow = panel.querySelector(".stats-row") || document.createElement("div");
    statsRow.className = "stats-row";
    const s = computeStats(name);
    if (!s) {
        statsRow.innerHTML = '<span class="stats-empty">Sin datos suficientes</span>';
    } else {
        statsRow.innerHTML =
            `<span class="stat-item">Min <b>${s.min.toFixed(3)}</b></span>` +
            `<span class="stat-item">Max <b>${s.max.toFixed(3)}</b></span>`;
    }
    if (!statsRow.parentNode) panel.appendChild(statsRow);

    const deltaRow = panel.querySelector(".delta-row") || document.createElement("div");
    deltaRow.className = "delta-row";
    const dVal = deltaByName[name];
    const hasMarkers = Number.isFinite(markerA) && Number.isFinite(markerB);
    if (Number.isFinite(dVal) || hasMarkers) {
        deltaRow.innerHTML = "";
        if (Number.isFinite(dVal)) {
            const span = document.createElement("span");
            span.className = "stat-item";
            span.innerHTML = `Δ valor <b>${dVal >= 0 ? "+" : ""}${dVal.toFixed(4)}</b>`;
            deltaRow.appendChild(span);
        }
        if (hasMarkers) {
            const dt = markerB - markerA;
            const tSpan = document.createElement("span");
            tSpan.className = "stat-item";
            tSpan.innerHTML = `Δt <b>${dt.toFixed(3)}</b> s`;
            deltaRow.appendChild(tSpan);
        }
        if (!deltaRow.parentNode) panel.appendChild(deltaRow);
    } else {
        if (deltaRow.parentNode) deltaRow.remove();
    }

    if (isArincDerivedName(name)) {
        let hint = panel.querySelector(".arinc-derived-hint");
        if (!hint) {
            hint = document.createElement("div");
            hint.className = "arinc-derived-hint";
            panel.appendChild(hint);
        }
        hint.textContent = "Subcanal ARINC derivado: no requiere reinterpretación ARINC.";
        panel.querySelectorAll(".fmt-mode-row, .fmt-units-row, .fmt-conversion-block, .fmt-physical-block").forEach((el) => el.remove());
        panel.querySelectorAll(":scope > .fmt-row:not(.fmt-units-row):not(.fmt-mode-row)").forEach((el) => el.remove());
        const alarmOld = panel.querySelector(".alarm-row");
        if (alarmOld) alarmOld.remove();
        const genOld = panel.querySelector(".gen-row");
        if (genOld) genOld.remove();
        const arincOld = panel.querySelector(".arinc-row");
        if (arincOld) arincOld.remove();
        const arincSubs = panel.querySelector(".arinc-subvars");
        if (arincSubs) arincSubs.remove();
        const m1553FichaOld = panel.querySelector(".m1553-ficha-row");
        if (m1553FichaOld) m1553FichaOld.remove();
        return;
    }

    const replayImposed = isReplayMode() && impositionNames.has(name) && isVarInTsv(name);
    if (replayImposed) {
        panel.querySelectorAll(".fmt-mode-row, .fmt-units-row, .fmt-conversion-block, .fmt-physical-block").forEach((el) => el.remove());
        panel.querySelectorAll(":scope > .fmt-row:not(.fmt-units-row):not(.fmt-mode-row)").forEach((el) => el.remove());
        const genOld = panel.querySelector(".gen-row");
        if (genOld) genOld.remove();
    }

    const vf = ensureVarFormatEntry(name);
    const canUseArincMode = hasPlugin("arinc") && !isArincDerivedName(name) && !isComputed(name);
    const canUseM1553Mode = hasPlugin("m1553") && parseM1553VarName(name) && !isComputed(name);
    panel.classList.toggle("stats-panel--arinc", canUseArincMode && vf.sal === "arinc429");
    panel.classList.toggle("stats-panel--m1553", canUseM1553Mode && vf.sal === "m1553");
    if (!canUseArincMode && vf.sal === "arinc429") vf.sal = "dec";
    if (!canUseArincMode && vf.fmtMode === "arinc") vf.fmtMode = "units";
    if (!canUseM1553Mode && vf.sal === "m1553") vf.sal = "dec";
    if (!canUseM1553Mode && vf.fmtMode === "m1553") vf.fmtMode = "units";
    const tr = I18N[currentLang] || I18N.es;

    let fmtModeRow = panel.querySelector(".fmt-mode-row");
    if (!replayImposed) {
        panel.querySelectorAll(":scope > .fmt-row:not(.fmt-units-row):not(.fmt-mode-row)").forEach((el) => el.remove());
    }

    function fmtModeOptionsHtml() {
        let h = `<option value="off">${tr.fmtModeOff}</option><option value="units">${tr.fmtModeUnits}</option>`;
        if (canUseArincMode) h += `<option value="arinc">${tr.fmtModeArinc}</option>`;
        if (canUseM1553Mode) h += `<option value="m1553">${tr.fmtModeM1553 || "MIL-STD-1553"}</option>`;
        return h;
    }

    function syncFmtModeUi() {
        const v = ensureVarFormatEntry(name);
        let mode = inferVarFormatMode(v);
        if (!canUseArincMode && mode === "arinc") mode = "units";
        if (!canUseM1553Mode && mode === "m1553") mode = "units";
        const modeSel = panel.querySelector(".fmt-mode-select");
        if (modeSel) {
            modeSel.innerHTML = fmtModeOptionsHtml();
            modeSel.value = mode;
            if (modeSel.value !== mode) modeSel.value = "units";
        }
        const convBlock = panel.querySelector(".fmt-conversion-block");
        if (convBlock) convBlock.style.display = mode === "units" ? "" : "none";
    }

    if (!replayImposed && !fmtModeRow) {
        fmtModeRow = document.createElement("div");
        fmtModeRow.className = "fmt-mode-row fmt-row";
        const modeLbl = document.createElement("span");
        modeLbl.className = "fmt-label";
        modeLbl.textContent = tr.fmtModeLabel || "Formato:";
        const modeSel = document.createElement("select");
        modeSel.className = "fmt-select fmt-mode-select";
        modeSel.innerHTML = fmtModeOptionsHtml();
        modeSel.addEventListener("change", (e) => {
            e.stopPropagation();
            applyVarFormatMode(name, modeSel.value, wrap);
        });
        modeSel.addEventListener("click", (e) => e.stopPropagation());
        fmtModeRow.appendChild(modeLbl);
        fmtModeRow.appendChild(modeSel);
        panel.appendChild(fmtModeRow);
        syncFmtModeUi();
    } else if (!replayImposed && fmtModeRow) {
        syncFmtModeUi();
    }
    if (!replayImposed) {
        syncConversionDetailPanel(panel, name, wrap, tr);
    }
    let imposeOffsetsRow = panel.querySelector(".impose-offsets-row");
    if (isReplayMode() && !isArrayVar(name) && isVarInTsv(name)) {
        if (!imposeOffsetsRow) {
            imposeOffsetsRow = document.createElement("div");
            imposeOffsetsRow.className = "impose-offsets-row";
            panel.appendChild(imposeOffsetsRow);
        }
        imposeOffsetsRow.innerHTML = "";
        const dtLabel = document.createElement("label");
        dtLabel.className = "monitor-offset-label";
        dtLabel.textContent = "Δt:";
        const dtInput = document.createElement("input");
        dtInput.type = "number";
        dtInput.className = "monitor-offset-input";
        dtInput.step = "any";
        dtInput.placeholder = "0";
        dtInput.title = "Offset temporal (s)";
        dtInput.value = impositionTimeOffset[name] != null ? String(impositionTimeOffset[name]) : "";
        dtInput.addEventListener("click", (e) => e.stopPropagation());
        dtInput.addEventListener("change", (e) => {
            e.stopPropagation();
            const v = parseFloat(dtInput.value);
            impositionTimeOffset[name] = Number.isFinite(v) ? v : 0;
            saveConfig();
        });
        dtLabel.appendChild(dtInput);
        const dvLabel = document.createElement("label");
        dvLabel.className = "monitor-offset-label";
        dvLabel.textContent = "Δv:";
        const dvInput = document.createElement("input");
        dvInput.type = "number";
        dvInput.className = "monitor-offset-input";
        dvInput.step = "any";
        dvInput.placeholder = "0";
        dvInput.title = "Offset numérico";
        dvInput.value = impositionValueOffset[name] != null ? String(impositionValueOffset[name]) : "";
        dvInput.addEventListener("click", (e) => e.stopPropagation());
        dvInput.addEventListener("change", (e) => {
            e.stopPropagation();
            const v = parseFloat(dvInput.value);
            impositionValueOffset[name] = Number.isFinite(v) ? v : 0;
            saveConfig();
        });
        dvLabel.appendChild(dvInput);
        imposeOffsetsRow.appendChild(dtLabel);
        imposeOffsetsRow.appendChild(dvLabel);
    } else if (imposeOffsetsRow) {
        imposeOffsetsRow.remove();
    }

    let arincRow = panel.querySelector(".arinc-row");
    if (canUseArincMode && vf.sal === "arinc429") {
        if (!arincRow) {
            arincRow = document.createElement("div");
            arincRow.className = "arinc-row";
            panel.appendChild(arincRow);
        }
        const cfg = getArincConfig(name);
        const vd = varsByName[name];
        const num = vd && typeof vd.value === "number" ? vd.value : Number(vd?.value);
        const d = Number.isFinite(num) ? decodeArinc429(num, cfg) : null;
        arincRow.innerHTML = "";
        const lsbLbl = document.createElement("span");
        lsbLbl.className = "fmt-label";
        lsbLbl.textContent = "LSB:";
        const lsbIn = document.createElement("input");
        lsbIn.className = "arinc-lsb-input";
        lsbIn.type = "number";
        lsbIn.step = "any";
        lsbIn.value = String(cfg.lsb ?? 1);
        lsbIn.addEventListener("click", (e) => e.stopPropagation());
        lsbIn.addEventListener("change", (e) => {
            e.stopPropagation();
            const nv = Number(lsbIn.value);
            getArincConfig(name).lsb = Number.isFinite(nv) && nv !== 0 ? nv : 1;
            rebuildArincDerivedHistoryForBase(name);
            if (varsByName[name] && Number.isFinite(Number(varsByName[name].value))) {
                const ts = varsByName[name].timestamp || (Date.now() / 1000);
                pushArincDerivedSample(name, ts, Number(varsByName[name].value), false);
            }
            saveConfig();
            updateMonitorValues();
            schedulePlotRender();
            updateStatsPanel(wrap, name);
        });
        const encLbl = document.createElement("span");
        encLbl.className = "fmt-label";
        encLbl.textContent = "Enc:";
        const encSel = document.createElement("select");
        encSel.className = "fmt-select";
        encSel.innerHTML = '<option value="">auto</option><option value="bnr">BNR</option><option value="bcd">BCD</option><option value="discrete">DIS</option>';
        encSel.value = cfg.encodingOverride || "";
        encSel.addEventListener("click", (e) => e.stopPropagation());
        encSel.addEventListener("change", (e) => {
            e.stopPropagation();
            getArincConfig(name).encodingOverride = encSel.value || "";
            rebuildArincDerivedHistoryForBase(name);
            if (varsByName[name] && Number.isFinite(Number(varsByName[name].value))) {
                const ts = varsByName[name].timestamp || (Date.now() / 1000);
                pushArincDerivedSample(name, ts, Number(varsByName[name].value), false);
            }
            saveConfig();
            updateMonitorValues();
            schedulePlotRender();
            updateStatsPanel(wrap, name);
        });
        const grpLbl = document.createElement("span");
        grpLbl.className = "fmt-label";
        grpLbl.textContent = currentLang === "en" ? "Group:" : "Grupo:";
        const grpSel = document.createElement("select");
        grpSel.className = "fmt-select";
        const groups = arincRegistryGroups(arincLabelRegistry);
        grpSel.innerHTML = [
            `<option value="">${currentLang === "en" ? "auto" : "auto"}</option>`,
            ...groups.map((g) => `<option value="${escapeHtml(g)}">${escapeHtml(g)}</option>`),
        ].join("");
        grpSel.value = cfg.autoGroup || "";
        if (cfg.autoGroup && !groups.includes(cfg.autoGroup)) {
            grpSel.innerHTML += `<option value="${escapeHtml(cfg.autoGroup)}">${escapeHtml(cfg.autoGroup)}</option>`;
            grpSel.value = cfg.autoGroup;
        }
        grpSel.disabled = !(arincDbStatus && arincDbStatus.loaded);
        grpSel.addEventListener("click", (e) => e.stopPropagation());
        grpSel.addEventListener("change", (e) => {
            e.stopPropagation();
            getArincConfig(name).autoGroup = grpSel.value || "";
            rebuildArincDerivedHistoryForBase(name);
            if (varsByName[name] && Number.isFinite(Number(varsByName[name].value))) {
                const ts = varsByName[name].timestamp || (Date.now() / 1000);
                pushArincDerivedSample(name, ts, Number(varsByName[name].value), false);
            }
            saveConfig();
            updateMonitorValues();
            schedulePlotRender();
            updateStatsPanel(wrap, name);
        });
        const autoMode = !(cfg.encodingOverride || "").trim();
        const autoDbDecode = !!(
            d
            && d.userRegistryHit
            && autoMode
        );
        const info = document.createElement("span");
        info.className = "arinc-info";
        info.textContent = d
            ? `Label ${d.labelOct} (${d.labelName}) | PAR:${d.parityOk ? "OK" : "ERR"} SSM:${d.ssmOk ? "OK" : "WARN"} RNG:${d.rangeOk ? "OK" : "WARN"}`
            : "ARINC: sin dato numérico";
        arincRow.appendChild(info);
        if (autoDbDecode) {
            const autoBd = document.createElement("span");
            autoBd.className = "arinc-auto-badge";
            autoBd.textContent = "BD";
            autoBd.title = currentLang === "en"
                ? "Automatic decoding from active database"
                : "Decodificación automática desde la base de datos activa";
            arincRow.appendChild(autoBd);
        }
        if (!autoMode) {
            arincRow.appendChild(lsbLbl);
            arincRow.appendChild(lsbIn);
        }
        arincRow.appendChild(encLbl);
        arincRow.appendChild(encSel);
        arincRow.appendChild(grpLbl);
        arincRow.appendChild(grpSel);

        let arincDisPanel = panel.querySelector(".arinc-dis-bits-panel");
        const disEnc = String((d && (d.encodingCanonical || d.encoding)) || "").toLowerCase();
        if (
            d
            && disEnc === "discrete"
            && Array.isArray(d.discreteBits)
            && d.discreteBits.length > 0
        ) {
            if (!arincDisPanel) {
                arincDisPanel = document.createElement("div");
                arincDisPanel.className = "arinc-dis-bits-panel";
                arincRow.insertAdjacentElement("afterend", arincDisPanel);
            }
            let raw = null;
            if (Number.isFinite(d.valueRaw)) {
                raw = Math.floor(Number(d.valueRaw)) >>> 0;
            } else if (d.data != null && Number.isFinite(Number(d.data))) {
                const nb = Math.max(1, Math.min(19, Number(d.bits) || 19));
                const mask = (1 << nb) - 1;
                raw = (Math.floor(Number(d.data)) & mask) >>> 0;
            }
            const titleT = tr.arincDisBitsTitle || "DIS bits";
            let html = `<div class="arinc-dis-bits-title">${escapeHtml(titleT)}</div>`;
            for (const bit of [...d.discreteBits].sort((a, b) => a.index - b.index)) {
                const v = raw != null ? ((raw >> bit.index) & 1) : "—";
                const accent = arincDiscreteBitAccentColor(bit.name);
                html += `<div class="arinc-dis-bit-row" style="--bit-accent: ${accent}">` +
                    `<span class="arinc-dis-bit-idx">bit ${escapeHtml(String(bit.index))}</span>` +
                    `<span>${escapeHtml(bit.name)}</span><span>${escapeHtml(String(v))}</span></div>`;
            }
            arincDisPanel.innerHTML = html;
        } else if (arincDisPanel) {
            arincDisPanel.remove();
        }

        let arincSubvars = panel.querySelector(".arinc-subvars");
        if (!arincSubvars) {
            arincSubvars = document.createElement("div");
            arincSubvars.className = "arinc-subvars";
            panel.appendChild(arincSubvars);
        }
        arincSubvars.innerHTML = "";
        const subHeader = document.createElement("div");
        subHeader.className = "arinc-subvars-header";
        const subTitle = document.createElement("div");
        subTitle.className = "arinc-subvars-title";
        subTitle.textContent = "Subcanales ploteables ARINC";
        const addAllBtn = document.createElement("button");
        addAllBtn.type = "button";
        addAllBtn.className = "btn-arinc-add-all";
        addAllBtn.textContent = currentLang === "en" ? "+ all" : "+ todos";
        addAllBtn.title = currentLang === "en"
            ? "Add all ARINC subchannels to monitoring list"
            : "Agregar todos los subcanales ARINC a monitorización";
        addAllBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            insertAllArincDerivedMonitoredAfterBase(name);
            updateStatsPanel(null, name);
        });
        subHeader.appendChild(subTitle);
        subHeader.appendChild(addAllBtn);
        arincSubvars.appendChild(subHeader);
        const subSpecs = [
            { suffix: "label", label: "Label", value: d ? Number.parseInt(d.labelOct, 10) : null },
            { suffix: "sdi", label: "SDI", value: d ? d.sdi : null },
            { suffix: "data", label: "Data", value: d ? d.data : null },
            { suffix: "ssm", label: "SSM", value: d ? d.ssm : null },
            { suffix: "parity", label: "Parity", value: d ? d.parity : null },
            { suffix: "value", label: "Value", value: d ? d.value : null },
        ];
        for (let i = 0; i < subSpecs.length; i++) {
            const spec = subSpecs[i];
            const dName = `${name}.arinc.${spec.suffix}`;

            const row = document.createElement("div");
            row.className = "arinc-subvar-row";
            row.draggable = true;
            row.addEventListener("dragstart", (e) => {
                if (!e.dataTransfer) return;
                noteMonitorDragStart(dName);
                e.dataTransfer.setData("text/plain", dName);
                e.dataTransfer.setData("application/x-var-name", dName);
                e.dataTransfer.effectAllowed = "copy";
                ensureNewGraphDropTarget();
            });
            row.addEventListener("dragend", () => {
                plotArea.querySelectorAll(".plot-add-slot").forEach((slot) => {
                    slot.classList.remove("plot-add-over");
                    slot.style.display = "none";
                });
                if (graphList.length === 0 && plotEmpty) {
                    plotEmpty.classList.remove("plot-add-over");
                    if (plotEmpty.dataset.defaultText) plotEmpty.textContent = plotEmpty.dataset.defaultText;
                }
            });

            const lbl = document.createElement("span");
            lbl.className = "arinc-subvar-name";
            lbl.textContent = spec.label;
            lbl.title = dName;

            const val = document.createElement("span");
            val.className = "arinc-subvar-value";
            val.textContent = Number.isFinite(spec.value)
                ? (
                    spec.suffix === "value"
                        ? spec.value.toFixed(4)
                        : (
                            spec.suffix === "data"
                                ? `0b${(Math.trunc(spec.value) >>> 0).toString(2).padStart(Math.max(1, Number(d?.bits) || 19), "0")}`
                                : String(spec.value)
                        )
                )
                : "--";

            let alarmBtn = null;
            if (isLiveMode()) {
                alarmBtn = document.createElement("span");
                alarmBtn.className = "arr-alarm-btn" + (alarms[dName] ? " arr-alarm-active" : "");
                if (activeAlarms.has(dName)) alarmBtn.classList.add("alarm-firing");
                alarmBtn.textContent = "⚠";
                alarmBtn.dataset.elemName = dName;
                alarmBtn.title = alarms[dName]
                    ? `Alarma: Lo:${alarms[dName].lo ?? "-"} Hi:${alarms[dName].hi ?? "-"} (clic para quitar)`
                    : "Configurar alarma";
                alarmBtn.addEventListener("click", (e) => {
                    e.stopPropagation();
                    if (alarms[dName]) {
                        delete alarms[dName];
                        delete prevAlarmState[dName];
                        alarmBtn.className = "arr-alarm-btn";
                        alarmBtn.textContent = "⚠";
                        alarmBtn.title = "Configurar alarma";
                        saveConfig();
                        sendAlarmsToBackend();
                        updateMonitorItemStyles();
                        refreshAllStats();
                    } else {
                        showArrayElemAlarmForm(row, dName, alarmBtn);
                    }
                });
            }

            row.appendChild(lbl);
            row.appendChild(val);
            if (alarmBtn) row.appendChild(alarmBtn);
            arincSubvars.appendChild(row);
        }
    } else if (arincRow) {
        arincRow.remove();
        const arincSubvars = panel.querySelector(".arinc-subvars");
        if (arincSubvars) arincSubvars.remove();
        const arincDisR = panel.querySelector(".arinc-dis-bits-panel");
        if (arincDisR) arincDisR.remove();
    }

    let m1553FichaRow = panel.querySelector(".m1553-ficha-row");
    if (canUseM1553Mode && vf.sal === "m1553") {
        const vd = varsByName[name];
        const num = vd && typeof vd.value === "number" ? vd.value : Number(vd?.value);
        const det = m1553DetailedDecode(name, num, m1553LabelRegistry);
        if (!m1553FichaRow) {
            m1553FichaRow = document.createElement("div");
            m1553FichaRow.className = "m1553-ficha-row";
            panel.appendChild(m1553FichaRow);
        }
        m1553FichaRow.innerHTML = "";
        const titleEl = document.createElement("div");
        titleEl.className = "m1553-ficha-title";
        titleEl.textContent = tr.m1553FichaTitle || "MIL-STD-1553";
        m1553FichaRow.appendChild(titleEl);

        const grid = document.createElement("div");
        grid.className = "m1553-ficha-grid";
        const addKV = (k, v) => {
            const lk = document.createElement("span");
            lk.className = "m1553-ficha-k";
            lk.textContent = k;
            const vv = document.createElement("span");
            vv.className = "m1553-ficha-v";
            vv.textContent = v;
            grid.appendChild(lk);
            grid.appendChild(vv);
        };
        if (det.ok && det.parsed) {
            addKV(tr.m1553FichaRt || "RT", String(det.parsed.rt));
            addKV(tr.m1553FichaWordKind || "Palabra (tipo)", String(det.parsed.wordKind));
            addKV(tr.m1553FichaSuffix || "Sufijo", det.parsed.suffix);
        }
        const binLine = det.binary16 ? `${det.rawHex} · 0b${det.binary16}` : det.rawHex;
        addKV(tr.m1553FichaRaw || "Carga (16b)", binLine);
        if (det.fromDb && det.def) {
            addKV(tr.m1553FichaIcdName || "Nombre ICD", String(det.def.name || ""));
            addKV(tr.m1553FichaEnc || "Codificación", String(det.encoding || det.def.encoding || ""));
            addKV(tr.m1553FichaBits || "Bits datos", String(det.bits));
        }
        m1553FichaRow.appendChild(grid);

        if (det.discreteRows && det.discreteRows.length) {
            const disPanel = document.createElement("div");
            disPanel.className = "arinc-dis-bits-panel";
            const titleT = tr.m1553FichaDiscreteTitle || "Bits DIS";
            let inner = `<div class="arinc-dis-bits-title">${escapeHtml(titleT)}</div>`;
            for (const r of det.discreteRows) {
                const accent = arincDiscreteBitAccentColor(r.name);
                inner += `<div class="arinc-dis-bit-row" style="--bit-accent: ${accent}">` +
                    `<span class="arinc-dis-bit-idx">bit ${escapeHtml(String(r.index))}</span>` +
                    `<span>${escapeHtml(r.name)}</span>` +
                    `<span>${escapeHtml(String(r.value))}</span></div>`;
            }
            disPanel.innerHTML = inner;
            m1553FichaRow.appendChild(disPanel);
        } else if (det.packedRows && det.packedRows.length) {
            const pkPanel = document.createElement("div");
            pkPanel.className = "arinc-dis-bits-panel";
            const titleT = tr.m1553FichaPackedTitle || "Subcampos (MSB)";
            let inner = `<div class="arinc-dis-bits-title">${escapeHtml(titleT)}</div>`;
            for (const r of det.packedRows) {
                const accent = arincDiscreteBitAccentColor(r.name);
                const rng = r.bitStartMsb === r.bitEndMsb
                    ? String(r.bitStartMsb)
                    : `${r.bitStartMsb}–${r.bitEndMsb}`;
                const valStr = r.units ? `${r.valueStr} ${r.units}` : String(r.valueStr);
                inner += `<div class="arinc-dis-bit-row" style="--bit-accent: ${accent}">` +
                    `<span class="arinc-dis-bit-idx">MSB ${escapeHtml(rng)}</span>` +
                    `<span>${escapeHtml(r.name)} (${escapeHtml(r.encoding)})</span>` +
                    `<span>${escapeHtml(valStr)}</span></div>`;
            }
            pkPanel.innerHTML = inner;
            m1553FichaRow.appendChild(pkPanel);
        } else if (det.engineeringStr) {
            const eng = document.createElement("div");
            eng.className = "m1553-ficha-eng";
            const u = det.def && det.def.units ? `${det.engineeringStr} ${det.def.units}` : det.engineeringStr;
            eng.textContent = `${tr.m1553FichaEngineering || "Ingeniería"}: ${u}`;
            m1553FichaRow.appendChild(eng);
        }
        if (det.summaryLine) {
            const sum = document.createElement("div");
            sum.className = "m1553-ficha-summary";
            sum.textContent = det.summaryLine;
            m1553FichaRow.appendChild(sum);
        }
        if (!det.ok) {
            const badge = document.createElement("div");
            badge.className = "m1553-ficha-nodb";
            badge.textContent = tr.m1553FichaBadName || "Nombre sin convención RT_W_";
            m1553FichaRow.appendChild(badge);
        } else if (!det.fromDb) {
            const badge = document.createElement("div");
            badge.className = "m1553-ficha-nodb";
            badge.textContent = tr.m1553FichaNoDef || "Sin definición en registro activo";
            m1553FichaRow.appendChild(badge);
        }
    } else if (m1553FichaRow) {
        m1553FichaRow.remove();
    }

    // En modo no-live ocultamos alarmas salvo replay con módulo replay_alias (vs referencia). Generadores sí en replay/offline.
    const showReplayAlarmUi = isReplayMode();
    if (!isLiveMode()) {
        if (!showReplayAlarmUi) {
            const alarmRowOffline = panel.querySelector(".alarm-row");
            if (alarmRowOffline) alarmRowOffline.remove();
        }
        if (!isPlaybackMode()) {
            const genRowOffline = panel.querySelector(".gen-row");
            if (genRowOffline) genRowOffline.remove();
            return;
        }
    }

    let alarmRow = panel.querySelector(".alarm-row");
    const a = alarms[name];

    if (a) {
        if (!alarmRow) {
            alarmRow = document.createElement("div");
            alarmRow.className = "alarm-row alarm-row-active";
            panel.appendChild(alarmRow);
        }
        alarmRow.innerHTML = "";
        alarmRow.className = "alarm-row alarm-row-active";

        const label = document.createElement("span");
        label.className = "alarm-label-active";
        let txt = "\u26A0 ";
        if (a.compareToRef) {
            const tr = I18N[currentLang] || I18N.es;
            txt += (tr.alarmReplayRefLabel || "vs ref") + " tol:" + (a.tol ?? "—");
        } else {
            if (a.lo !== null) txt += "Lo:" + a.lo + " ";
            if (a.hi !== null) txt += "Hi:" + a.hi;
        }
        if (a.hys) txt += " Hys:" + a.hys;
        if (a.delayMs) txt += " Dly:" + a.delayMs + "ms";
        label.textContent = txt;

        const removeBtn = document.createElement("button");
        removeBtn.className = "btn-alarm-remove";
        removeBtn.textContent = "\u00D7";
        removeBtn.title = "Eliminar alarma";
        removeBtn.addEventListener("click", (e) => {
            e.stopPropagation();
            delete alarms[name];
            delete prevAlarmState[name];
            saveConfig();
            sendAlarmsToBackend();
            updateMonitorItemStyles();
            updateStatsPanel(wrap, name);
        });

        alarmRow.appendChild(label);
        alarmRow.appendChild(removeBtn);
    } else {
        if (!alarmRow) {
            alarmRow = document.createElement("div");
            alarmRow.className = "alarm-row";
            panel.appendChild(alarmRow);
        }

        if (!alarmRow.querySelector(".alarm-form")) {
            alarmRow.innerHTML = "";
            alarmRow.className = "alarm-row";

            const addBtn = document.createElement("button");
            addBtn.className = "btn-alarm-add";
            addBtn.textContent = "+ Alarma";
            addBtn.addEventListener("click", (e) => {
                e.stopPropagation();
                showAlarmForm(alarmRow, name, wrap);
            });
            alarmRow.appendChild(addBtn);
        }
    }

    if (!replayImposed) {
        let genRow = panel.querySelector(".gen-row");
        const gen = activeGenerators[name];

        if (gen) {
            if (!genRow) {
                genRow = document.createElement("div");
                genRow.className = "gen-row gen-row-active";
                panel.appendChild(genRow);
            }
            if (!genRow.classList.contains("gen-row-active") || !genRow.querySelector(".btn-gen-stop")) {
                genRow.innerHTML = "";
                genRow.className = "gen-row gen-row-active";

                const label = document.createElement("span");
                label.className = "gen-label-active";
                label.textContent = "\u25B6 " + (GEN_TYPES[gen.type] ? GEN_TYPES[gen.type].label : gen.type);
                genRow.appendChild(label);

                const stopBtn = document.createElement("button");
                stopBtn.className = "btn-gen-stop";
                stopBtn.textContent = "\u25A0 Stop";
                stopBtn.addEventListener("click", (e) => {
                    e.stopPropagation();
                    stopGenerator(name);
                    updateStatsPanel(wrap, name);
                });
                genRow.appendChild(stopBtn);
            }
        } else {
            if (!genRow) {
                genRow = document.createElement("div");
                genRow.className = "gen-row";
                panel.appendChild(genRow);
            }

            if (!genRow.querySelector(".gen-form") && !genRow.querySelector(".gen-select")) {
                genRow.innerHTML = "";
                genRow.className = "gen-row";
                buildGenSelector(genRow, name, wrap);
            }
        }
    } else {
        const genRow = panel.querySelector(".gen-row");
        if (genRow) genRow.remove();
    }
}

function buildGenSelector(genRow, name, wrap) {
    const sel = document.createElement("select");
    sel.className = "gen-select";
    const optNone = document.createElement("option");
    optNone.value = "";
    optNone.textContent = "Generador...";
    sel.appendChild(optNone);

    for (const [key, def] of Object.entries(GEN_TYPES)) {
        const o = document.createElement("option");
        o.value = key;
        o.textContent = def.label;
        sel.appendChild(o);
    }

    sel.addEventListener("change", (e) => {
        e.stopPropagation();
        const type = sel.value;
        const formArea = genRow.querySelector(".gen-form");
        if (formArea) formArea.remove();
        if (type) showGenForm(genRow, name, wrap, type);
    });

    genRow.appendChild(sel);
}

function showGenForm(genRow, name, wrap, type) {
    const def = GEN_TYPES[type];
    if (!def) return;
    const form = document.createElement("div");
    form.className = "gen-form";

    const inputs = {};
    for (const f of def.fields) {
        const group = document.createElement("div");
        group.className = "gen-field";
        const lbl = document.createElement("span");
        lbl.className = "gen-field-label";
        lbl.textContent = f.l;
        const inp = document.createElement("input");
        inp.type = "number";
        inp.step = "any";
        inp.className = "gen-input";
        inp.value = f.d;
        inputs[f.k] = inp;
        group.appendChild(lbl);
        group.appendChild(inp);
        form.appendChild(group);
    }

    const playBtn = document.createElement("button");
    playBtn.className = "btn-gen-play";
    playBtn.textContent = "\u25B6";
    playBtn.title = "Iniciar generador";
    playBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        const params = {};
        for (const f of def.fields) {
            params[f.k] = parseFloat(inputs[f.k].value) || f.d;
        }
        startGenerator(name, type, params);
        updateStatsPanel(wrap, name);
    });
    form.appendChild(playBtn);

    genRow.appendChild(form);
}

function showAlarmForm(alarmRow, name, wrap) {
    alarmRow.innerHTML = "";
    const tr = I18N[currentLang] || I18N.es;
    const form = document.createElement("div");
    form.className = "alarm-form";
    const replayRefUi = isReplayMode();
    const existing = alarms[name];

    const loInput = document.createElement("input");
    loInput.type = "number";
    loInput.step = "any";
    loInput.placeholder = "Lo";
    loInput.className = "alarm-input";
    loInput.title = tr.alarmLoTitle || "Umbral bajo";

    const hiInput = document.createElement("input");
    hiInput.type = "number";
    hiInput.step = "any";
    hiInput.placeholder = "Hi";
    hiInput.className = "alarm-input";
    hiInput.title = tr.alarmHiTitle || "Umbral alto";

    const hysInput = document.createElement("input");
    hysInput.type = "number";
    hysInput.step = "any";
    hysInput.placeholder = "Hys";
    hysInput.className = "alarm-input";
    hysInput.title = tr.alarmHysTitle || "Histéresis";

    const delayInput = document.createElement("input");
    delayInput.type = "number";
    delayInput.step = "1";
    delayInput.placeholder = "Delay ms";
    delayInput.className = "alarm-input";
    delayInput.title = tr.alarmDelayTitle || "Retardo de disparo (ms)";

    const tolInput = document.createElement("input");
    tolInput.type = "number";
    tolInput.step = "any";
    tolInput.placeholder = tr.alarmTolPlaceholder || "tol";
    tolInput.className = "alarm-input";
    tolInput.title = tr.alarmTolTitle || "|live − ref| máx. sin disparar";

    const hysRefInput = document.createElement("input");
    hysRefInput.type = "number";
    hysRefInput.step = "any";
    hysRefInput.placeholder = "Hys";
    hysRefInput.className = "alarm-input";
    hysRefInput.title = tr.alarmHysTitle || "Histéresis";

    const delayRefInput = document.createElement("input");
    delayRefInput.type = "number";
    delayRefInput.step = "1";
    delayRefInput.placeholder = "Delay ms";
    delayRefInput.className = "alarm-input";
    delayRefInput.title = tr.alarmDelayTitle || "Retardo de disparo (ms)";

    if (existing && !existing.compareToRef) {
        if (existing.lo != null) loInput.value = String(existing.lo);
        if (existing.hi != null) hiInput.value = String(existing.hi);
        if (existing.hys) hysInput.value = String(existing.hys);
        if (existing.delayMs) delayInput.value = String(existing.delayMs);
    }
    if (existing && existing.compareToRef) {
        if (Number.isFinite(Number(existing.tol))) tolInput.value = String(existing.tol);
        if (existing.hys) hysRefInput.value = String(existing.hys);
        if (existing.delayMs) delayRefInput.value = String(existing.delayMs);
    }

    const okBtn = document.createElement("button");
    okBtn.className = "btn-alarm-ok";
    okBtn.textContent = "\u2713";
    okBtn.title = tr.alarmOkTitle || "Confirmar alarma";
    okBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        if (replayRefUi && modeSel && modeSel.value === "ref") {
            const tol = tolInput.value.trim() !== "" ? parseFloat(tolInput.value) : NaN;
            const hys = hysRefInput.value.trim() !== "" ? Math.max(0, parseFloat(hysRefInput.value)) : 0;
            const delayMs = delayRefInput.value.trim() !== "" ? Math.max(0, parseInt(delayRefInput.value, 10) || 0) : 0;
            if (!Number.isFinite(tol)) {
                delete alarms[name];
            } else {
                alarms[name] = {
                    compareToRef: true,
                    tol,
                    hys,
                    delayMs,
                    lo: null,
                    hi: null,
                    refName: defaultReplayRefShmName(name),
                };
            }
        } else {
            const lo = loInput.value.trim() !== "" ? parseFloat(loInput.value) : null;
            const hi = hiInput.value.trim() !== "" ? parseFloat(hiInput.value) : null;
            const hys = hysInput.value.trim() !== "" ? Math.max(0, parseFloat(hysInput.value)) : 0;
            const delayMs = delayInput.value.trim() !== "" ? Math.max(0, parseInt(delayInput.value, 10) || 0) : 0;
            if (lo === null && hi === null) {
                delete alarms[name];
            } else {
                alarms[name] = { lo, hi, hys, delayMs };
            }
        }
        saveConfig();
        sendAlarmsToBackend();
        updateMonitorItemStyles();
        updateStatsPanel(wrap, name);
        refreshAlarmListPanel();
    });

    const cancelBtn = document.createElement("button");
    cancelBtn.className = "btn-alarm-cancel";
    cancelBtn.textContent = "\u00D7";
    cancelBtn.title = tr.alarmCancelTitle || "Cancelar";
    cancelBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        updateStatsPanel(wrap, name);
    });

    let modeSel = null;
    const absWrap = document.createElement("span");
    absWrap.className = "alarm-abs-wrap";
    absWrap.appendChild(loInput);
    absWrap.appendChild(hiInput);
    absWrap.appendChild(hysInput);
    absWrap.appendChild(delayInput);

    const refWrap = document.createElement("span");
    refWrap.className = "alarm-ref-wrap";
    refWrap.appendChild(tolInput);
    refWrap.appendChild(hysRefInput);
    refWrap.appendChild(delayRefInput);

    if (replayRefUi) {
        modeSel = document.createElement("select");
        modeSel.className = "alarm-mode-select";
        const oAbs = document.createElement("option");
        oAbs.value = "abs";
        oAbs.textContent = tr.alarmModeAbsolute || "Umbral absoluto";
        const oRef = document.createElement("option");
        oRef.value = "ref";
        oRef.textContent = tr.alarmModeVsRef || "vs referencia";
        modeSel.appendChild(oAbs);
        modeSel.appendChild(oRef);
        if (existing && existing.compareToRef) modeSel.value = "ref";
        const syncMode = () => {
            const ref = modeSel.value === "ref";
            absWrap.style.display = ref ? "none" : "";
            refWrap.style.display = ref ? "" : "none";
        };
        modeSel.addEventListener("change", syncMode);
        form.appendChild(modeSel);
        syncMode();
    } else {
        absWrap.style.display = "";
        refWrap.style.display = "none";
    }

    form.appendChild(absWrap);
    form.appendChild(refWrap);
    form.appendChild(okBtn);
    form.appendChild(cancelBtn);
    alarmRow.appendChild(form);

    if (replayRefUi && modeSel && modeSel.value === "ref") tolInput.focus();
    else loInput.focus();
}

function refreshAllStats() {
    const active = document.activeElement;
    const useDock = monitorDetailPanelUsesDock();
    if (useDock) {
        const nm = getDockedExpandedVarName();
        if (!nm) return;
        const dock = getMonitorDetailDockEl();
        if (active && dock && dock.contains(active)) return;
        updateStatsPanel(null, nm);
        return;
    }
    for (const name of expandedStats) {
        const wrap = monitorListEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(name)}"]`);
        if (!wrap) continue;
        // Evita reconstruir el panel mientras se interactua con sus controles
        // (selects/inputs ARINC, alarmas, etc.) para que no se cierre el desplegable activo.
        if (active && wrap.contains(active)) continue;
        updateStatsPanel(wrap, name);
    }
}

function checkAlarmEntry(name, value, newActive, triggered) {
    const a = alarms[name];
    if (!a || a.compareToRef || typeof value !== "number") return;
    const hys = Number.isFinite(Number(a.hys)) ? Math.max(0, Number(a.hys)) : 0;
    const delayMs = Number.isFinite(Number(a.delayMs)) ? Math.max(0, Number(a.delayMs)) : 0;
    const prev = !!prevAlarmState[name];
    let overHi = (a.hi !== null && value > a.hi);
    let underLo = (a.lo !== null && value < a.lo);
    if (prev) {
        const clearHi = (a.hi === null) || value <= ((a.hi ?? value) - hys);
        const clearLo = (a.lo === null) || value >= ((a.lo ?? value) + hys);
        if (clearHi && clearLo) {
            delete alarmPendingSince[name];
            return;
        }
        overHi = a.hi !== null && value > (a.hi - hys);
        underLo = a.lo !== null && value < (a.lo + hys);
    }
    const alarming = overHi || underLo;
    if (!alarming) {
        delete alarmPendingSince[name];
        return;
    }
    const nowMs = Date.now();
    if (!alarmPendingSince[name]) alarmPendingSince[name] = nowMs;
    const elapsed = nowMs - alarmPendingSince[name];
    if (elapsed < delayMs) return;
    let reason = "";
    if (overHi && a.hi !== null) reason = `${name} = ${value.toFixed(4)} > Hi:${a.hi}`;
    if (underLo && a.lo !== null) reason = `${name} = ${value.toFixed(4)} < Lo:${a.lo}`;
    newActive.add(name);
    if (!prev) triggered.push({ name, reason, value });
}

function getNumericValueForAlarmName(name) {
    if (!name) return null;
    if (isArrayElem(name)) {
        const br = name.lastIndexOf("[");
        const base = name.substring(0, br);
        const idx = parseInt(name.substring(br + 1), 10);
        const vd = varsByName[base];
        if (!vd || !Array.isArray(vd.value) || !Number.isFinite(idx) || idx < 0 || idx >= vd.value.length) return null;
        const v = vd.value[idx];
        return typeof v === "number" ? v : Number(v);
    }
    const vd = varsByName[name];
    if (!vd) return null;
    if (Array.isArray(vd.value)) return null;
    return typeof vd.value === "number" ? vd.value : (vd.value === true ? 1 : vd.value === false ? 0 : Number(vd.value));
}

function evaluateLocalAlarmsNow() {
    if (!isLiveMode()) return;
    const newActive = new Set();
    const triggered = [];
    for (const name of Object.keys(alarms || {})) {
        // Backend evalua alarmas de variables reales por ciclo.
        // Frontend solo mantiene temporalmente las virtuales (array elem / ARINC derivadas).
        if (alarms[name] && alarms[name].compareToRef) continue;
        if (!isArrayElem(name) && !isArincDerivedName(name)) continue;
        const val = getNumericValueForAlarmName(name);
        if (!Number.isFinite(val)) continue;
        checkAlarmEntry(name, val, newActive, triggered);
    }
    // Conserva alarmas activas notificadas por backend y añade las virtuales locales.
    const merged = new Set(Array.from(activeAlarms).filter((n) => !isArrayElem(n) && !isArincDerivedName(n)));
    newActive.forEach((n) => merged.add(n));
    activeAlarms = merged;
    const nextPrev = {};
    for (const name of Object.keys(alarms || {})) {
        if (isArrayElem(name) || isArincDerivedName(name)) nextPrev[name] = newActive.has(name);
    }
    // Mantener estado previo de reales controlado por backend.
    for (const [k, v] of Object.entries(prevAlarmState)) {
        if (!isArrayElem(k) && !isArincDerivedName(k)) nextPrev[k] = !!v;
    }
    prevAlarmState = nextPrev;
    updateAlarmActiveDOM();
    if (triggered.length > 0) {
        const reasons = triggered.map(t => `[LOCAL] ${t.reason}`).join(" | ");
        sendAlarmNotification(reasons);
        showAlarmBanner(reasons);
    }
}

let lastAlarmsPayloadSent = "";
/** Último valor enviado a set_replay_alarm_engaged (evita martillar el WS en setModeUi). */
let lastReplayAlarmEngagedSent = null;

function syncReplayAlarmEngagedToBackend() {
    if (!hasBackendConnectionMode()) return;
    const engaged = !isReplayMode() || !!offlinePlayback.isPlaying;
    if (lastReplayAlarmEngagedSent === engaged) return;
    lastReplayAlarmEngagedSent = engaged;
    sendWsAction({ action: "set_replay_alarm_engaged", value: engaged });
}

/** Limpia estado visual de alarmas |live−ref| al pausar replay (no SHM). */
function clearReplayRefAlarmActiveState() {
    if (!isReplayMode()) return;
    const refNames = new Set(Object.keys(alarms).filter((n) => alarms[n] && alarms[n].compareToRef));
    if (refNames.size === 0) return;
    activeAlarms = new Set([...activeAlarms].filter((n) => !refNames.has(n)));
    for (const n of refNames) {
        delete prevAlarmState[n];
        delete alarmPendingSince[n];
    }
    updateAlarmActiveDOM();
    refreshAlarmListPanel();
}

function sendAlarmsToBackend() {
    const payload = {};
    for (const [name, cfg] of Object.entries(alarms)) {
        if (cfg && cfg.compareToRef) {
            const tol = Number(cfg.tol);
            if (!Number.isFinite(tol)) continue;
            payload[name] = {
                compareToRef: true,
                tol,
                hys: Number.isFinite(Number(cfg.hys)) ? Number(cfg.hys) : 0,
                delayMs: Number.isFinite(Number(cfg.delayMs)) ? Number(cfg.delayMs) : 0,
                refName: cfg.refName || defaultReplayRefShmName(name),
            };
            continue;
        }
        if (cfg && (cfg.lo != null || cfg.hi != null)) {
            payload[name] = {
                lo: cfg.lo ?? null,
                hi: cfg.hi ?? null,
                hys: Number.isFinite(Number(cfg.hys)) ? Number(cfg.hys) : 0,
                delayMs: Number.isFinite(Number(cfg.delayMs)) ? Number(cfg.delayMs) : 0,
            };
        }
    }
    const key = JSON.stringify(payload);
    if (key === lastAlarmsPayloadSent) return;
    lastAlarmsPayloadSent = key;
    sendWsAction({ action: "set_alarms", alarms: payload });
}

function sendSendFileOnFinish() {
    const val = sendFileOnFinishCheckbox ? sendFileOnFinishCheckbox.checked : false;
    sendWsAction({ action: "set_send_file_on_finish", value: val });
}

function sendAlarmNotification(reasons) {
    if (!("Notification" in window) || Notification.permission !== "granted") return;
    if (document.hasFocus()) return;
    const n = new Notification("VarMonitor — Alarma", {
        body: reasons,
        icon: "data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>⚠</text></svg>",
        tag: "varmon-alarm",
    });
    n.addEventListener("click", () => { window.focus(); n.close(); });
    setTimeout(() => n.close(), 8000);
}

function updateAlarmActiveDOM() {
    if (!monitorListEl) return;
    monitorListEl.querySelectorAll(".monitor-item[data-name]").forEach(el => {
        el.classList.toggle("alarm-active", activeAlarms.has(el.dataset.name));
    });
    monitorListEl.querySelectorAll(".arr-alarm-btn").forEach(el => {
        const eName = el.closest("[data-name]")?.dataset?.name || el.dataset?.elemName;
        if (eName) el.classList.toggle("alarm-firing", activeAlarms.has(eName));
    });
    monitorListEl.querySelectorAll(".btn-mon-alarm-quick").forEach(el => {
        const row = el.closest(".monitor-item");
        const n = row && row.dataset ? row.dataset.name : null;
        if (n) el.classList.toggle("alarm-firing", activeAlarms.has(n));
    });
}

function onAlarmTriggeredFromBackend(triggered) {
    if (!Array.isArray(triggered)) return;
    triggered.forEach(t => activeAlarms.add(t.name));
    updateAlarmActiveDOM();
    const reasons = triggered.map(t => t.reason).join(" | ");
    sendAlarmNotification(reasons);
    showAlarmBanner(reasons);
}

function onAlarmClearedFromBackend(names) {
    if (!Array.isArray(names)) return;
    names.forEach(n => {
        activeAlarms.delete(n);
        delete alarmPendingSince[n];
    });
    updateAlarmActiveDOM();
}

function basenameFromPath(path) {
    const p = String(path || "").trim();
    if (!p) return "";
    const norm = p.replace(/\\/g, "/");
    const i = norm.lastIndexOf("/");
    return i >= 0 ? norm.slice(i + 1) : norm;
}

async function enterAnalysisForRecordedFile(path, filename) {
    const fn = (filename || basenameFromPath(path)).trim();
    if (!fn) return;
    try {
        if (!isPlaybackMode()) setAppMode("offline", { keepData: true });
        await refreshServerRecordings();
        if (recordingSelect) {
            const has = Array.from(recordingSelect.options).some(o => o.value === fn);
            if (has) recordingSelect.value = fn;
        }
        // En el flujo desde toast mantenemos monitorizadas y asignaciones de gráficos.
        await loadRecordingFromServer(fn, { preserveLayout: true });
    } catch (e) {
        alert("No se pudo abrir el archivo en modo análisis: " + (e && e.message ? e.message : String(e)));
    }
}

function showRecordPathToast(path, opts = {}) {
    const el = document.getElementById("recordPathToast");
    const textEl = document.getElementById("recordPathText");
    if (el && textEl) {
        textEl.textContent = path || "";
        el.style.display = path ? "block" : "none";
        if (recordPathAnalyzeBtn) {
            const fn = (opts.filename || basenameFromPath(path)).trim();
            const showAnalyze = !!(fn && (fn.toLowerCase().endsWith(".tsv") || fn.toLowerCase().endsWith(".parquet")));
            recordPathAnalyzeBtn.style.display = showAnalyze ? "" : "none";
            if (showAnalyze) {
                recordPathAnalyzeBtn.onclick = () => { enterAnalysisForRecordedFile(path, fn); };
            } else {
                recordPathAnalyzeBtn.onclick = null;
            }
        }
        if (path) setTimeout(() => { el.style.display = "none"; }, 12000);
    }
}

function onRecordFinished(msg) {
    if (isReplayClientRecording) return;
    const path = (msg.path || msg.filename || "").trim();
    const text = path ? path : (msg.message || "Grabación finalizada.");
    showRecordPathToast(text, { filename: msg.filename || "" });
    void refreshServerRecordings();
    if (msg.file_base64) {
        try {
            const bin = atob(msg.file_base64);
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
            const low = (msg.filename || "").toLowerCase();
            const isTsv = low.endsWith(".tsv");
            const isPq = low.endsWith(".parquet");
            const blob = new Blob([bytes], {
                type: isPq ? "application/vnd.apache.parquet" : (isTsv ? "text/tab-separated-values" : "text/csv"),
            });
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = msg.filename || (isPq ? "record.parquet" : "record.tsv");
            a.click();
            URL.revokeObjectURL(a.href);
        } catch (e) { /* ignore */ }
    }
    isRecording = false;
    isRecordingStopping = false;
    if (recordTimerInterval) { clearInterval(recordTimerInterval); recordTimerInterval = null; }
    if (recordStopFallbackTimer) { clearTimeout(recordStopFallbackTimer); recordStopFallbackTimer = null; }
    recordBtn.disabled = false;
    recordBtn.textContent = "\u25CF REC";
    recordBtn.classList.remove("recording");
    if (recordTimerEl) recordTimerEl.style.display = "none";
    recordSizeBytes = 0;
    if (pendingRecordingRestart && isLiveMode()) {
        pendingRecordingRestart = false;
        startRecording();
    } else {
        pendingRecordingRestart = false;
    }
}

function onAlarmRecordingReady(msg) {
    const path = msg.path || msg.filename || "";
    showRecordPathToast(path, { filename: msg.filename || "" });
    void refreshServerRecordings();
    if (msg.file_base64) {
        try {
            const bin = atob(msg.file_base64);
            const bytes = new Uint8Array(bin.length);
            for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
            const low = (msg.filename || "").toLowerCase();
            const isTsv = low.endsWith(".tsv");
            const isPq = low.endsWith(".parquet");
            const blob = new Blob([bytes], {
                type: isPq ? "application/vnd.apache.parquet" : (isTsv ? "text/tab-separated-values" : "text/csv"),
            });
            const a = document.createElement("a");
            a.href = URL.createObjectURL(blob);
            a.download = msg.filename || (isPq ? "alarm.parquet" : "alarm.tsv");
            a.click();
            URL.revokeObjectURL(a.href);
        } catch (e) { /* ignore */ }
    }
}

function onAlarmTriggered(triggers) {
    const now = Date.now();
    if (now - lastAutoTsvTime < AUTO_TSV_COOLDOWN_MS) return;
    lastAutoTsvTime = now;

    const reasons = triggers.map(t => t.reason).join(" | ");
    const triggerNames = triggers.map(t => t.name);

    sendAlarmNotification(reasons);

    setTimeout(() => {
        generateAlarmTsv(triggerNames);
        showAlarmBanner(reasons);
    }, AUTO_TSV_DELAY_MS);
}

function generateAlarmTsv(triggerNames) {
    const cols = Array.from(monitoredNames);
    if (cols.length === 0) return;

    const nowEpoch = Date.now() / 1000;
    const tMin = nowEpoch - AUTO_TSV_HISTORY_SEC - 1;
    const tMax = nowEpoch;

    const allTimestamps = new Set();
    const colData = {};

    for (const name of cols) {
        const hist = historyCache[name];
        colData[name] = {};
        if (!hist || !hist.timestamps) continue;
        for (let i = 0; i < hist.timestamps.length; i++) {
            const t = hist.timestamps[i];
            if (t >= tMin && t <= tMax) {
                allTimestamps.add(t);
                colData[name][t] = hist.values[i];
            }
        }
    }

    const sortedTs = Array.from(allTimestamps).sort((a, b) => a - b);
    if (sortedTs.length === 0) return;

    const t0 = sortedTs[0];
    const header = ["time_s"].concat(cols).join("\t");
    const lines = [header];
    for (const t of sortedTs) {
        const row = [(t - t0).toFixed(4)];
        for (const name of cols) {
            const v = colData[name][t];
            row.push(v !== undefined ? String(v) : "");
        }
        lines.push(row.join("\t"));
    }

    const content = lines.join("\n");
    const blob = new Blob([content], { type: "text/tab-separated-values" });

    const d = new Date();
    const pad2 = n => String(n).padStart(2, "0");
    const trigLabel = triggerNames.slice(0, 2).join("_").replace(/\./g, "-");
    const fname = "alarm_" + trigLabel + "_" +
        d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate()) + "_" +
        pad2(d.getHours()) + "-" + pad2(d.getMinutes()) + "-" + pad2(d.getSeconds()) + ".tsv";

    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = fname;
    a.click();
    URL.revokeObjectURL(a.href);
}

const alarmBanner = document.getElementById("alarmBanner");
const alarmBannerText = document.getElementById("alarmBannerText");
document.getElementById("alarmBannerDismiss").addEventListener("click", dismissAlarmBanner);

function showAlarmBanner(message) {
    alarmBannerText.textContent = message;
    alarmBanner.style.display = "flex";
    alarmBanner.classList.add("alarm-banner-visible");
}

function dismissAlarmBanner() {
    alarmBanner.style.display = "none";
    alarmBanner.classList.remove("alarm-banner-visible");
}

function startInlineEdit(itemEl, name) {
    if (!isLiveMode()) return;
    if (editingName === name) return;
    const vd = varsByName[name];
    if (!vd) return;
    if (vd.type === "string" || vd.type === "array") return;
    if (isArincDerivedName(name)) return;

    editingName = name;
    const valEl = itemEl.querySelector(".mon-value");
    const currentText = valEl.textContent;
    const tr = I18N[currentLang] || I18N.es;

    const input = document.createElement("input");
    const ori = (varFormat[name] && varFormat[name].ori) ? varFormat[name].ori : "dec";
    const physOn = vd.type === "double" && physicalConversionActiveForDisplay(name)
        && ensurePhysicalDefaults(ensureVarFormatEntry(name).physical).category !== "none";
    const needsTextInput = vd.type === "bool" || (!physOn && (ori === "hex" || ori === "bin" || ori === "arinc429"));
    input.type = needsTextInput ? "text" : "number";
    input.className = "mon-edit-input";
    if (vd.type === "bool") {
        input.value = vd.value ? "true" : "false";
    } else if (!physOn && ori === "hex") {
        input.value = "0x" + ((Math.round(Number(vd.value)) >>> 0).toString(16).toUpperCase());
    } else if (!physOn && (ori === "bin" || ori === "arinc429")) {
        input.value = "0b" + ((Math.round(Number(vd.value)) >>> 0).toString(2));
    } else if (physOn) {
        const p = ensurePhysicalDefaults(ensureVarFormatEntry(name).physical);
        input.value = String(physicalRawToDisplay(Number(vd.value), p));
    } else {
        input.value = vd.value;
    }
    if (vd.type === "double") input.step = "any";

    valEl.textContent = "";
    valEl.classList.add("mon-value--editing");

    const actions = document.createElement("span");
    actions.className = "mon-edit-actions";
    const okBtn = document.createElement("button");
    okBtn.type = "button";
    okBtn.className = "btn-mon-edit-ok";
    okBtn.textContent = "\u2713";
    okBtn.title = tr.inlineEditConfirm || "Confirmar";
    const cancelBtn = document.createElement("button");
    cancelBtn.type = "button";
    cancelBtn.className = "btn-mon-edit-cancel";
    cancelBtn.textContent = "\u2715";
    cancelBtn.title = tr.inlineEditCancel || "Cancelar";

    okBtn.addEventListener("mousedown", (e) => e.preventDefault());
    cancelBtn.addEventListener("mousedown", (e) => e.preventDefault());

    valEl.appendChild(input);
    actions.appendChild(okBtn);
    actions.appendChild(cancelBtn);
    valEl.appendChild(actions);

    input.focus();
    input.select();

    let done = false;

    function teardownEditingChrome() {
        valEl.classList.remove("mon-value--editing");
        valEl.replaceChildren();
    }

    function commit() {
        if (done) return;
        done = true;
        let sendVal, varType;
        const raw = input.value.trim();
        const fmt = varFormat[name];
        const oriResolved = fmt ? (fmt.ori || "dec") : "dec";

        if (vd.type === "bool") {
            sendVal = (raw === "1" || raw.toLowerCase() === "true") ? 1 : 0;
            varType = "bool";
        } else if (vd.type === "int32") {
            const parsed = parseNumericWithFormat(raw, oriResolved);
            sendVal = Number.isFinite(parsed) ? (Math.trunc(parsed) | 0) : 0;
            varType = "int32";
        } else {
            const pPhys = ensurePhysicalDefaults(ensureVarFormatEntry(name).physical);
            const usePhys = physicalConversionActiveForDisplay(name) && pPhys.category !== "none";
            let parsed;
            if (usePhys) {
                parsed = parseFloat(raw);
                sendVal = Number.isFinite(parsed) ? physicalDisplayToRaw(parsed, pPhys) : 0;
            } else {
                parsed = parseNumericWithFormat(raw, oriResolved);
                sendVal = Number.isFinite(parsed) ? parsed : 0;
            }
            varType = "double";
        }

        sendWsAction({
            action: "set_var",
            name: name,
            value: sendVal,
            var_type: varType,
        });
        editingName = null;
        teardownEditingChrome();
        valEl.textContent = formatValue(sendVal, varType, name);
    }

    function cancel() {
        if (done) return;
        done = true;
        editingName = null;
        teardownEditingChrome();
        valEl.textContent = currentText;
    }

    okBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        commit();
    });
    cancelBtn.addEventListener("click", (e) => {
        e.stopPropagation();
        cancel();
    });

    input.addEventListener("keydown", (e) => {
        if (e.key === "Enter") { e.preventDefault(); commit(); }
        else if (e.key === "Escape") { e.preventDefault(); cancel(); }
    });
    input.addEventListener("click", (e) => e.stopPropagation());

    valEl.addEventListener("focusout", (e) => {
        if (done) return;
        const rt = e.relatedTarget;
        if (rt && valEl.contains(rt)) return;
        window.setTimeout(() => {
            if (done) return;
            if (document.activeElement && valEl.contains(document.activeElement)) return;
            cancel();
        }, 0);
    });
}

