function markReconnectPending() {
    if (!reconnectBtn.classList.contains("btn-pending")) {
        reconnectBtn.classList.add("btn-pending");
    }
}

function clearReconnectPending() {
    reconnectBtn.classList.remove("btn-pending");
}

portSelect.addEventListener("change", () => { markReconnectPending(); updateMultiInstanceWarning(); });

const multiInstanceWarningCloseBtn = document.getElementById("multiInstanceWarningClose");
if (multiInstanceWarningCloseBtn) {
    multiInstanceWarningCloseBtn.addEventListener("click", hideMultiInstanceWarning);
}

reconnectBtn.addEventListener("click", async () => {
    if (ws) {
        try { ws.close(); } catch (e) { /* ignore */ }
        ws = null;
    }
    try {
        const [connResp, udsResp] = await Promise.all([
            fetch("/api/connection_info").then((r) => r.ok ? r.json() : null),
            fetch("/api/uds_instances").then((r) => r.ok ? r.json() : null)
        ]);
        if (connResp) connectionInfo = connResp;
        udsInstances = (udsResp && Array.isArray(udsResp.instances)) ? udsResp.instances : [];
        if (udsInstances.length > 0) {
            fillPortSelectWithUds();
            updateMultiInstanceWarning();
            resetStateForNewTarget();
            connect();
        } else {
            resetStateForNewTarget();
            statusEl.textContent = (I18N[currentLang] || I18N.es).statusNoInstances || "No hay instancias VarMonitor (UDS)";
            statusEl.className = "status disconnected";
        }
    } catch (e) { resetStateForNewTarget(); }
});

if (hideLevelsInput) {
    hideLevelsInput.addEventListener("change", () => {
        const v = parseInt(hideLevelsInput.value || "0", 10);
        hideLevels = isNaN(v) ? 0 : Math.max(0, Math.min(8, v));
        hideLevelsInput.value = String(hideLevels);
        rebuildMonitorList();
        saveConfig();
    });
}

function formatNameWithHiddenLevels(name, levels) {
    const lvl = Math.max(0, Math.min(8, levels | 0));
    if (lvl <= 0) return name;
    const parts = name.split(".");
    if (parts.length <= 1) return name;
    const lastIdx = parts.length - 1;
    const toHide = Math.min(lvl, lastIdx);
    for (let i = 0; i < toHide; i++) {
        const p = parts[i];
        if (p.length > 0) parts[i] = p[0];
    }
    return parts.join(".");
}

function resetStateForNewTarget() {
    clearUserLayout();
    clearDataBuffers();
    offlineDataset = null;
    offlineRecordingName = "";
    markerA = null;
    markerB = null;
    updateOfflineDatasetStatus();
    updateMarkerInfoLabel();
    stopOfflinePlayback();

    // Parar grabacion si estaba activa
    isRecording = false;
    isRecordingStopping = false;
    pendingRecordingRestart = false;
    recordBuffer = [];
    recordColumns = [];
    recordSizeBytes = 0;
    recordStartTime = null;
    if (recordTimerInterval) {
        clearInterval(recordTimerInterval);
        recordTimerInterval = null;
    }
    recordBtn.disabled = false;
    recordTimerEl.style.display = "none";
    recordBtn.classList.remove("btn-record-active");
}

// --- Drag & drop: Columna 2 como zona de drop desde Columna 1 ---

monitorListEl.addEventListener("dragover", (e) => {
    if (!e.dataTransfer) return;
    e.preventDefault();
    const isReorder = e.dataTransfer.types.includes("application/x-monitor-reorder");
    if (isReorder) {
        e.dataTransfer.dropEffect = "move";
        monitorListEl.classList.remove("mon-drop-over");
        const under = document.elementFromPoint(e.clientX, e.clientY);
        const wrap = under && under.closest ? under.closest(".monitor-item-wrap") : null;
        monitorListEl.querySelectorAll(".monitor-item-wrap").forEach(w => {
            w.classList.remove("monitor-drop-before", "monitor-drop-after");
            delete w.dataset.dropPosition;
        });
        if (wrap) {
            const rect = wrap.getBoundingClientRect();
            const mid = rect.top + rect.height / 2;
            const before = e.clientY < mid;
            wrap.classList.add(before ? "monitor-drop-before" : "monitor-drop-after");
            wrap.dataset.dropPosition = before ? "before" : "after";
        }
    } else {
        e.dataTransfer.dropEffect = "copy";
        monitorListEl.classList.add("mon-drop-over");
    }
});

monitorListEl.addEventListener("dragleave", (e) => {
    if (!monitorListEl.contains(e.relatedTarget)) {
        monitorListEl.classList.remove("mon-drop-over");
        monitorListEl.querySelectorAll(".monitor-item-wrap").forEach(w => {
            w.classList.remove("monitor-drop-before", "monitor-drop-after");
            delete w.dataset.dropPosition;
        });
    }
});

function addDroppedVarToMonitorByName(nameRaw) {
    const name = String(nameRaw || "").trim();
    if (!name) return false;
    if (!knownVarNames.includes(name)) return false;
    if (!monitoredNames.has(name)) {
        ensureArincBaseMonitored(name);
        ensureMonitoredName(name);
        sendMonitored();
    }
    browserSelection.delete(name);
    saveConfig();
    rebuildMonitorList();
    if (isPlaybackMode() && offlineDataset) {
        const tNow = Number.isFinite(offlinePlayback.currentTs) ? offlinePlayback.currentTs : offlineDataset.minTs;
        applyOfflineTime(tNow);
    }
    updateMonitorValues();
    renderBrowserList();
    return true;
}

monitorListEl.addEventListener("drop", (e) => {
    if (!e.dataTransfer) return;
    e.preventDefault();
    monitorListEl.classList.remove("mon-drop-over");
    monitorListEl.querySelectorAll(".monitor-item-wrap").forEach(w => {
        w.classList.remove("monitor-drop-before", "monitor-drop-after");
        delete w.dataset.dropPosition;
    });

    const reorderName = e.dataTransfer.getData("application/x-monitor-reorder");
    if (reorderName) {
        const wrap = e.target.closest ? e.target.closest(".monitor-item-wrap") : null;
        const targetName = wrap ? wrap.dataset.name : null;
        const pos = wrap ? (wrap.dataset.dropPosition || "after") : "after";
        const fromIdx = monitoredOrder.indexOf(reorderName);
        if (fromIdx === -1) {
            setArincVizDropActive(false);
            return;
        }
        let toIdx = targetName ? monitoredOrder.indexOf(targetName) : monitoredOrder.length;
        if (toIdx === -1) toIdx = monitoredOrder.length;
        if (pos === "after") toIdx += 1;
        if (toIdx > fromIdx) toIdx -= 1;
        if (fromIdx === toIdx) {
            setArincVizDropActive(false);
            return;
        }
        monitoredOrder.splice(fromIdx, 1);
        monitoredOrder.splice(toIdx, 0, reorderName);
        const draggedWrap = monitorListEl.querySelector(`.monitor-item-wrap[data-name="${CSS.escape(reorderName)}"]`);
        if (draggedWrap && wrap && draggedWrap !== wrap) {
            if (pos === "before") {
                monitorListEl.insertBefore(draggedWrap, wrap);
            } else {
                if (wrap.nextSibling) monitorListEl.insertBefore(draggedWrap, wrap.nextSibling);
                else monitorListEl.appendChild(draggedWrap);
            }
        } else if (draggedWrap && !wrap) {
            monitorListEl.appendChild(draggedWrap);
        }
        saveConfig();
        rebuildMonitorList();
        setArincVizDropActive(false);
        return;
    }

    addDroppedVarToMonitorByName(getDraggedMonitorVarName(e.dataTransfer));
    setArincVizDropActive(false);
});

if (colMonitorEl) {
    colMonitorEl.addEventListener("dragover", (e) => {
        if (!e.dataTransfer) return;
        const isReorder = e.dataTransfer.types.includes("application/x-monitor-reorder");
        if (isReorder) return;
        e.preventDefault();
        e.dataTransfer.dropEffect = "copy";
        monitorListEl.classList.add("mon-drop-over");
    });
    colMonitorEl.addEventListener("dragleave", (e) => {
        if (!colMonitorEl.contains(e.relatedTarget)) {
            monitorListEl.classList.remove("mon-drop-over");
        }
    });
    colMonitorEl.addEventListener("drop", (e) => {
        if (!e.dataTransfer) return;
        const isReorder = e.dataTransfer.types.includes("application/x-monitor-reorder");
        if (isReorder) return;
        e.preventDefault();
        monitorListEl.classList.remove("mon-drop-over");
        addDroppedVarToMonitorByName(getDraggedMonitorVarName(e.dataTransfer));
        setArincVizDropActive(false);
    });
}

async function initialScanAndConnect() {
    if (isOfflineMode()) {
        setOfflineStatus();
        await refreshServerRecordings();
        return;
    }
    if (isReplayMode()) {
        try {
            await refreshServerRecordings();
        } catch (e) {
            console.warn("[VarMonitor] refreshServerRecordings:", e);
        }
        setOfflineStatus();
    }
    try {
        if (udsInstances.length > 0) {
            fillPortSelectWithUds();
        } else if (portSelect) {
            portSelect.innerHTML = "";
        }
        updateMultiInstanceWarning();
    } catch (e) {
        console.error("[VarMonitor] initialScanAndConnect (antes de WS):", e);
    }
    try {
        ensureWsMatchesSelection();
    } catch (e) {
        console.error("[VarMonitor] ensureWsMatchesSelection:", e);
    }
}

// --- Data handlers ---

function onVarNames(names) {
    if (!Array.isArray(names)) return;
    // Evitar vaciados transitorios: si llega [] pero ya teníamos catálogo, no borrar UI.
    if (names.length === 0 && baseKnownVarNames.length > 0 && (isLiveMode() || isReplayMode() || isArincRegistryMode())) {
        return;
    }
    // En replay con TSV cargado: unir siempre con las del archivo para no perder unas u otras.
    if (isReplayMode() && offlineDataset && Array.isArray(offlineDataset.names) && offlineDataset.names.length > 0) {
        names = [...new Set([...names, ...offlineDataset.names])].sort();
    }
    const sorted = names.slice().sort();
    const prunedArincViz = arincVizItems.filter((n) => sorted.includes(n));
    if (prunedArincViz.length !== arincVizItems.length) {
        arincVizItems = prunedArincViz;
        saveConfig();
        rebuildPlotArea();
    }
    const key = sorted.join(",");
    const oldKey = baseKnownVarNames.join(",");

    varCountEl.textContent = `${sorted.length} vars`;

    if (key !== oldKey) {
        baseKnownVarNames = sorted;
        rebuildKnownVarNamesWithDerived();
        browserListDirty = true;
        renderBrowserList();
        if (varDrawer && varDrawer.style.display === "flex") positionVarDrawer();
    } else {
        // Mismo catálogo base: rebuildKnownVarNamesWithDerived() no añade hoy variables derivadas al browser.
        // Evitamos join(",") sobre decenas de miles de nombres (picos de memoria / presión al GC).
        rebuildKnownVarNamesWithDerived();
    }
}

function injectBrowserHeapTelemetryIntoVarsUpdate(data) {
    if (!Array.isArray(data)) return data;
    let heapMb = null;
    try {
        const m = performance.memory;
        if (m && typeof m.usedJSHeapSize === "number") {
            heapMb = m.usedJSHeapSize / (1024 * 1024);
        }
    } catch (e) { /* no performance.memory (p. ej. Firefox) */ }
    if (heapMb == null) return data;
    // No usar .map(): con miles de variables cada vars_update clonaba un array gigante → presión
    // brutal al GC si además coincidía con pintar gráficos (memoria que tarda en estabilizarse).
    for (let i = 0; i < data.length; i++) {
        const item = data[i];
        if (item && item.name === "varmon.telemetry.browser_js_heap_mb") {
            item.value = heapMb;
            item.type = "double";
            break;
        }
    }
    return data;
}

/** Normaliza entrada de `varGraphAssignment`: siempre lista de gid (config antigua usaba un solo string). */
function normalizeVarGraphEntry(raw) {
    if (raw == null || raw === "") return [];
    if (Array.isArray(raw)) return raw.filter((x) => typeof x === "string" && x.length > 0);
    if (typeof raw === "string") return raw ? [raw] : [];
    return [];
}

function varGraphEntryHasGid(entry, gid) {
    return normalizeVarGraphEntry(entry).includes(gid);
}

/** Migra mapa in-place: valores string → string[]. Elimina claves vacías. */
function migrateVarGraphAssignmentMap(va) {
    if (!va || typeof va !== "object") return;
    for (const k of Object.keys(va)) {
        const list = normalizeVarGraphEntry(va[k]);
        if (list.length === 0) delete va[k];
        else va[k] = list;
    }
}

function cloneVarGraphAssignmentMap(raw) {
    if (!raw || typeof raw !== "object") return {};
    const out = {};
    for (const k of Object.keys(raw)) {
        const list = normalizeVarGraphEntry(raw[k]);
        if (list.length) out[k] = list.slice();
    }
    return out;
}

function addVarGraphGid(va, name, gid) {
    if (!va || !name || !gid) return;
    const cur = normalizeVarGraphEntry(va[name]);
    if (!cur.includes(gid)) cur.push(gid);
    va[name] = cur;
}

function removeVarGraphGid(va, name, gid) {
    if (!va || !name || !gid) return;
    const cur = normalizeVarGraphEntry(va[name]);
    const next = cur.filter((g) => g !== gid);
    if (next.length === 0) delete va[name];
    else va[name] = next;
}

/** Quita `gid` de todas las variables en el mapa (p. ej. al borrar un gráfico). */
function removeGidFromVarGraphMap(va, gid) {
    if (!va || !gid || typeof va !== "object") return;
    for (const k of Object.keys(va)) {
        removeVarGraphGid(va, k, gid);
    }
}

/** Asignación real a un gráfico existente (evita tratar "", 0, etc. como válidos). */
function graphAssignmentIsPlotted(g, glist) {
    const gl = Array.isArray(glist) && glist.length ? glist : graphList;
    if (Array.isArray(g)) {
        return g.some((x) => typeof x === "string" && x.length > 0 && gl.includes(x));
    }
    return typeof g === "string" && g.length > 0 && gl.includes(g);
}

function varScalarPlottedInGlobalGraphList(name) {
    return normalizeVarGraphEntry(varGraphAssignment[name]).some((g) => graphList.includes(g));
}

/**
 * Reutiliza el objeto en varsByName en lugar de asignar cada vez el item del JSON parseado.
 * Con miles de variables y alta frecuencia de vars_update, reemplazar miles de referencias/tick
 * + activar Plotly de golpe dejaba el heap en niveles altos de forma sostenida (GC no recuperaba).
 */
function mergeVarsByNameInPlace(item) {
    if (!item || !item.name) return null;
    const prev = varsByName[item.name];
    if (!prev || typeof prev !== "object") {
        varsByName[item.name] = item;
        return item;
    }
    const prevArr = Array.isArray(prev.value);
    const itemArr = Array.isArray(item.value);
    if (prevArr !== itemArr) {
        varsByName[item.name] = item;
        return item;
    }
    if (prevArr) {
        prev.value = item.value;
        prev.timestamp = item.timestamp;
        if (item.type != null) prev.type = item.type;
        return prev;
    }
    const pt = String(prev.type || "");
    const it = String(item.type || "");
    if (pt !== it) {
        const scalarish = new Set(["double", "float", "int", "int32", "uint32", "uint64", "int64", "bool"]);
        if (!(scalarish.has(pt) && scalarish.has(it))) {
            varsByName[item.name] = item;
            return item;
        }
    }
    prev.value = item.value;
    prev.timestamp = item.timestamp;
    if (item.type != null) prev.type = item.type;
    return prev;
}

function onVarsUpdate(data, opts = {}) {
    if (!Array.isArray(data)) return;
    data = injectBrowserHeapTelemetryIntoVarsUpdate(data);
    let appendHistory = opts.appendHistory !== false;
    const needHistBuffers = liveModeNeedsHistoryBuffers();
    const hadHistoryBuffersBefore = !!lastLiveHistoryNeed;
    if (isLiveMode() && appendHistory && !needHistBuffers) {
        appendHistory = false;
    }
    if (isLiveMode() && lastLiveHistoryNeed === true && !needHistBuffers) {
        purgeHistoryCacheWithoutPlot();
        for (const k of Object.keys(arrayElemHistory)) delete arrayElemHistory[k];
        for (let ci = 0; ci < computedVars.length; ci++) {
            const cn = computedVars[ci].name;
            const h = computedHistories[cn];
            if (h) {
                h.timestamps.length = 0;
                h.values.length = 0;
            }
            delete historyCache[cn];
        }
    }
    // Primer gráfico en vivo tras solo monitorizar: estado limpio de historial (sin arrastre raro).
    if (isLiveMode() && lastLiveHistoryNeed === false && needHistBuffers) {
        purgeHistoryCacheWithoutPlot();
    }
    if (needHistBuffers && !hadHistoryBuffersBefore) {
        nextAllowedRenderAt = 0;
    }
    lastLiveHistoryNeed = needHistBuffers;
    const forcedTs = (typeof opts.timestamp === "number" && Number.isFinite(opts.timestamp)) ? opts.timestamp : null;
    const isOfflineSnapshot = forcedTs != null && opts.appendHistory === false;
    const changedNames = new Set();
    const accepted = [];

    for (let i = 0; i < data.length; i++) {
        const item = data[i];
        if (!item || !item.name) continue;
        // En replay, si una variable del TSV está impuesta, ignorar cualquier valor entrante de SHM.
        if (isReplayMode() && !isOfflineSnapshot && impositionNames.has(item.name) && isVarInTsv(item.name)) {
            continue;
        }
        const stored = mergeVarsByNameInPlace(item);
        if (!stored) continue;
        accepted.push(stored);
        changedNames.add(item.name);
    }
    fireHook("on_vars_update", accepted);
    if (accepted.length === 0) return;

    if (computedVars.length > 0) evalComputedVars();
    const nowTs = forcedTs != null
        ? forcedTs
        : (isReplayMode() ? getReplayCurrentTs() : (Date.now() / 1000));
    // En modo live usamos tiempo relativo desde el inicio de sesión para los
    // historiales de las gráficas, así evitamos timestamps absolutos enormes.
    if (isLiveMode()) {
        if (sessionStartTime == null) sessionStartTime = nowTs;
    }
    const tsForHistBase = (isLiveMode() && sessionStartTime != null)
        ? (nowTs - sessionStartTime)
        : nowTs;
    changedNames.forEach((baseName) => {
        if (!isArincEnabled(baseName)) return;
        if (isArincDerivedName(baseName)) return;
        if (isReplayMode() && isVarInTsv(baseName) && impositionNames.has(baseName)) return;
        const vd = varsByName[baseName];
        if (!vd || Array.isArray(vd.value)) return;
        const num = typeof vd.value === "number" ? vd.value : Number(vd.value);
        if (!Number.isFinite(num)) return;
        let ts = (vd.timestamp && Number.isFinite(vd.timestamp)) ? vd.timestamp : nowTs;
        if (isLiveMode() && sessionStartTime != null) {
            ts = ts - sessionStartTime;
        }
        pushArincDerivedSample(baseName, ts, num, appendHistory);
    });
    const hadArrayElems = trackArrayElementHistories(appendHistory);

    // Acumular buffer para gráficos desde el poll de monitorización (solo escalares; arrays en arrayElemHistory, computed en evalComputedVars).
    if (appendHistory) {
        const now = tsForHistBase;
        // Importante: vars_update en live puede venir en delta (solo cambios). Si aquí
        // usáramos únicamente `accepted`, las señales constantes quedarían "a saltos".
        // Para trazas continuas, empujamos el valor actual de todas las variables que
        // realmente requieren histórico de plot.
        const namesToSample = new Set();
        for (let i = 0; i < accepted.length; i++) namesToSample.add(accepted[i].name);
        for (const n of monitoredNames) {
            if (needsScalarPlotHistory(n)) namesToSample.add(n);
        }
        for (const name of namesToSample) {
            if (isComputed(name)) continue;
            if (isArincDerivedName(name)) continue;
            // En replay, solo bloqueamos histórico SHM para variables TSV impuestas.
            if (isReplayMode() && isVarInTsv(name) && impositionNames.has(name)) continue;
            const v = varsByName[name];
            if (!v) continue;
            if (Array.isArray(v.value)) continue;
            if (!needsScalarPlotHistory(name)) continue;
            const num =
                typeof v.value === "number"
                    ? v.value
                    : (v.value === true ? 1 : v.value === false ? 0 : Number(v.value));
            if (!isFinite(num)) continue;
            if (!historyCache[name]) historyCache[name] = { timestamps: [], values: [] };
            historyCache[name].timestamps.push(now);
            historyCache[name].values.push(num);
        }
        if (!isReplayMode()) trimLocalHistory();
    }
    if (isLocalRecording && isLiveMode()) {
        localRecordSamples.push(buildLocalFrontendSample(nowTs));
        if (localRecordSamples.length > 120000) localRecordSamples = localRecordSamples.slice(-120000);
    }
    pruneVarsByName();
    schedulePlotRender();

    updateMonitorValues();
    if (
        isLiveMode()
        && liveReplayEmbedDataset
        && Number.isFinite(liveReplayEmbedPlayback.currentTs)
        && (liveReplayEmbedPlayback.isPlaying || liveReplayEmbedCiEngaged)
    ) {
        let needLiveRefInject = false;
        for (const name of Object.keys(alarms)) {
            if (alarms[name] && alarms[name].compareToRef && isVarInLiveReplayEmbed(name)) {
                needLiveRefInject = true;
                break;
            }
        }
        if (needLiveRefInject) {
            applyLiveEmbedShmInjectionsBatch(liveReplayEmbedPlayback.currentTs);
        }
    }
    evaluateLocalAlarmsNow();
    renderArincBusHealth();
}

// --- Resize ---
let plotGridResizeRaf = 0;
function schedulePlotGridResize() {
    if (plotGridResizeRaf) return;
    plotGridResizeRaf = requestAnimationFrame(() => {
        plotGridResizeRaf = 0;
        if (typeof Plotly === "undefined") return;
        const els = Array.from(
            document.querySelectorAll(".live-pane--plot .plot-area .js-plotly-plot, #plotArea .js-plotly-plot")
        );
        for (const el of els) {
            const host = el.parentElement || el;
            const rect = host.getBoundingClientRect();
            const width = Math.max(Math.floor(rect.width), 220);
            const height = Math.max(Math.floor(rect.height), 120);
            Plotly.relayout(el, { width, height }).catch(() => {});
        }
    });
}

let resizeTimer = null;
const resizeObserver = new ResizeObserver(() => {
    if (resizeTimer) clearTimeout(resizeTimer);
    resizeTimer = setTimeout(() => {
        const paneIds = getLivePlotLeafIds();
        const multiPlot = paneIds.length > 1;
        for (const paneId of paneIds) {
            const stPane = getPlotPaneState(paneId);
            for (const gid of stPane.graphList || []) {
                const ik = makePlotInstanceKey(paneId, gid, multiPlot);
                if (!plotInstances[ik]) continue;
                const cid = multiPlot ? `plotContainer_${paneId}_${gid}` : `plotContainer_${gid}`;
                const el = document.getElementById(cid);
                if (!el) continue;
                const rect = el.getBoundingClientRect();
                Plotly.relayout(el, {
                    width: Math.max(rect.width, 200),
                    height: Math.max(rect.height, 80),
                }).catch(() => {});
            }
        }
        schedulePlotGridResize();
    }, 100);
});

async function checkAuthThenStart() {
    // En modo análisis puro (offline) no se abre WS.
    // En replay sí necesitamos WS para el modo híbrido (variables SHM/C++).
    if (isOfflineMode()) {
        await refreshServerRecordings();
        setOfflineStatus();
        return;
    }
    try {
        const r = await fetch("/api/auth_required");
        const d = await r.json();
        if (d.auth_required && !sessionStorage.getItem("varmon_password")) {
            showAuthModal();
            return;
        }
    } catch (e) { /* ignorar */ }
    try {
        const fetchP = fetchConnectionInfo();
        await fetchP;
        await initialScanAndConnect();
    } catch (e) {
        console.error("[VarMonitor] checkAuthThenStart:", e);
        if (hasBackendConnectionMode()) {
            try { connect(); } catch (e2) { console.error(e2); }
        }
    }
}

if (authSubmitBtn && authPasswordInput) {
    authSubmitBtn.addEventListener("click", async () => {
        const p = authPasswordInput.value.trim();
        if (!p) return;
        sessionStorage.setItem("varmon_password", p);
        hideAuthModal();
        if (_pendingBrowseAuthResolve) {
            const r = await fetch("/api/browse?path=");
            const ok = r.status !== 401;
            if (!ok) {
                sessionStorage.removeItem("varmon_password");
                const authPrompt = document.getElementById("authPrompt");
                const tr = I18N[currentLang] || I18N.es;
                if (authPrompt) {
                    authPrompt.textContent =
                        tr.authWrongBrowse || "Contraseña incorrecta (explorador de archivos).";
                }
                const fn = _pendingBrowseAuthResolve;
                _pendingBrowseAuthResolve = null;
                fn(false);
                hideAuthModal();
                return;
            }
            const fn = _pendingBrowseAuthResolve;
            _pendingBrowseAuthResolve = null;
            fn(true);
            await checkAuthThenStart();
            openFirstRunModePickerIfNeeded();
            return;
        }
        await checkAuthThenStart();
        openFirstRunModePickerIfNeeded();
    });
    authPasswordInput.addEventListener("keydown", (e) => {
        if (e.key === "Enter") authSubmitBtn.click();
    });
}
document.addEventListener(
    "keydown",
    (e) => {
        if (e.key !== "Escape" || !_pendingBrowseAuthResolve) return;
        const o = document.getElementById("authOverlay");
        if (!o || o.style.display === "none") return;
        e.preventDefault();
        _pendingBrowseAuthResolve(false);
        _pendingBrowseAuthResolve = null;
        hideAuthModal();
    },
    true,
);

// checkAuthThenStart: arranca en queueMicrotask junto a applyInitialConfigFromStorage (tras loadConfig).

// --- Keyboard shortcuts ---
document.addEventListener("keydown", (e) => {
    const tag = (e.target.tagName || "").toLowerCase();
    const isInput = tag === "input" || tag === "textarea" || tag === "select" || e.target.isContentEditable;
    if (isInput && e.key !== "Escape" && !(e.ctrlKey || e.metaKey)) return;

    if (e.key === "Escape") {
        if (helpOverlay.style.display === "flex") { helpOverlay.style.display = "none"; return; }
        if (docsLangOverlay && docsLangOverlay.style.display === "flex") {
            closeDocsLangModal();
            return;
        }
        dismissAlarmBanner();
        return;
    }
    if (e.key === " ") {
        e.preventDefault();
        plotsPaused = !plotsPaused;
        updatePauseBtn();
        if (!plotsPaused) {
            nextAllowedRenderAt = 0;
            schedulePlotRender();
        }
        return;
    }
    const k = e.key.toLowerCase();
    if ((e.ctrlKey || e.metaKey) && k === "z" && !e.shiftKey) {
        e.preventDefault();
        doLayoutUndo();
        return;
    }
    if ((e.ctrlKey || e.metaKey) && (k === "y" || (k === "z" && e.shiftKey))) {
        e.preventDefault();
        doLayoutRedo();
        return;
    }
    if (k === "r" && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        recordBtn.click();
        return;
    }
    if (k === "s" && !e.ctrlKey && !e.metaKey) {
        e.preventDefault();
        screenshotBtn.click();
        return;
    }
    if ((k === "h" || k === "?") && !(e.ctrlKey || e.metaKey)) {
        e.preventDefault();
        if (helpOverlay.style.display === "flex") {
            helpOverlay.style.display = "none";
        } else {
            refreshHelpModalBody();
            helpOverlay.style.display = "flex";
        }
        return;
    }
});

whenPlotlyReady(() => {
    document.querySelectorAll(".live-pane--plot .plot-area, #plotArea").forEach((el) => {
        try {
            resizeObserver.observe(el);
        } catch (e) { /* ignore */ }
    });
    rebuildPlotArea();
    if (monitoredNames.size > 0) {
        rebuildMonitorList();
    }
    schedulePlotRender();
});
